state_get() {
  local key="$1"
  awk -F'=' -v k="$key" '$1==k {print $2; exit}' "$SKPL_STATE_FILE" 2>/dev/null
}

state_set() {
  local key="$1"
  local value="$2"
  if grep -q "^${key}=" "$SKPL_STATE_FILE" 2>/dev/null; then
    python3 - "$SKPL_STATE_FILE" "$key" "$value" <<'PY'
import sys
path, key, value = sys.argv[1:4]
rows = []
with open(path, 'r', encoding='utf-8') as f:
    rows = f.readlines()
with open(path, 'w', encoding='utf-8') as f:
    written = False
    for row in rows:
        if row.startswith(key + '='):
            f.write(f"{key}={value}\n")
            written = True
        else:
            f.write(row)
    if not written:
        f.write(f"{key}={value}\n")
PY
  else
    echo "${key}=${value}" >> "$SKPL_STATE_FILE"
  fi
}

state_reset_for_full_rerun() {
  : > "$SKPL_STATE_FILE"
  state_set STEP 1
  echo "已重置安装进度，将从第 1 步开始重新执行。"
}

run_step_guard() {
  local step="$1"
  shift
  local rc=0
  log_msg "开始: $step"
  log_msg "执行命令: $*"
  if "$@"; then
    log_msg "完成: $step"
    return 0
  fi
  rc=$?
  log_msg "失败: $step | 返回码: $rc | 命令: $*"
  return $rc
}

