# ========================================================================
# 第2层 - 长期上下文构建（独立封装）
# ========================================================================
openclaw_ai_stack_long_term_context_text() {
  local query="$1" limit="${2:-5}"
  openclaw_ai_stack_prepare
  python3 - "$query" "$limit" "$SKPL_MEMORY_EXTENSION_CONFIG" "$SKPL_AI_STACK_STATE_DIR" "$SKPL_HYBRID_MEMORY_ROOT" <<'PY'
import json, sys, sqlite3, time, re
from pathlib import Path

query = sys.argv[1]
limit = int(sys.argv[2])
config_path = Path(sys.argv[3])
state_dir = Path(sys.argv[4])
hybrid_memory_root = Path(sys.argv[5])

# 尝试从多个可能的数据库位置加载长期记忆
db_paths = [
    hybrid_memory_root / "memory.db",
    hybrid_memory_root / "hybrid-memory.sqlite3",
    state_dir / "memory-extension.db",
    state_dir / "memory.sqlite3",
]

all_entries = []

for db_path in db_paths:
    if not db_path.exists():
        continue
    try:
        conn = sqlite3.connect(str(db_path), timeout=5)
        # 尝试查询长期记忆表
        tables_to_try = ['memory_entries', 'long_term_memory', 'memories', 'memory_items', 'knowledge_base']
        for table in tables_to_try:
            try:
                # 尝试各种列名组合
                cols = conn.execute(f"PRAGMA table_info({table})").fetchall()
                col_names = [c[1].lower() for c in cols]
                has_content = any('content' in c or 'text' in c or 'summary' in c or 'value' in c for c in col_names)
                has_time = any('time' in c or 'created' in c or 'timestamp' in c or 'date' in c for c in col_names)
                if has_content and has_time:
                    time_col = next(c for c in col_names if 'time' in c or 'created' in c or 'timestamp' in c or 'date' in c)
                    content_col = next(c for c in col_names if 'content' in c or 'text' in c or 'summary' in c or 'value' in c)
                    
                    rows = conn.execute(f'''
                        SELECT {content_col}, {time_col}
                        FROM {table}
                        ORDER BY {time_col} DESC
                        LIMIT 200
                    ''').fetchall()

                    now = int(time.time())
                    for row in rows:
                        content = str(row[0] or '')
                        ts = row[1]
                        if isinstance(ts, (int, float)):
                            age_days = (now - int(ts)) / 86400.0
                            age_weight = max(0.1, 1.0 - age_days / 180.0)  # 180天衰减
                        else:
                            age_weight = 0.3

                        # 查询相关度
                        relevance = 0.3
                        if query:
                            query_words = set(re.findall(r'[\u4e00-\u9fff\w]+', query.lower()))
                            content_words = set(re.findall(r'[\u4e00-\u9fff\w]+', content.lower()))
                            if query_words and content_words:
                                relevance = len(query_words & content_words) / max(len(query_words), 1)

                        # 综合权重 = 时间衰减 * 0.4 + 相关性 * 0.6
                        combined_weight = age_weight * 0.4 + relevance * 0.6
                        all_entries.append({
                            'content': content,
                            'weight': round(combined_weight, 3),
                            'ageDays': round(age_days, 1) if 'age_days' in dir() else 0,
                            'source': db_path.name,
                        })
                    break  # 找到匹配表后不再尝试其他表
            except sqlite3.OperationalError:
                continue
        conn.close()
    except Exception:
        continue

# 按权重排序，取top-N
all_entries.sort(key=lambda x: -x['weight'])

result_entries = all_entries[:limit]
if not result_entries:
    raise SystemExit(0)

# 构建上下文文本
lines = ['[long_term_context]']
for entry in result_entries:
    content = entry['content'][:300].replace('\n', ' ')
    weight_label = 'high' if entry['weight'] > 0.6 else ('medium' if entry['weight'] > 0.3 else 'low')
    lines.append(f'[{weight_label}:{entry["weight"]:.2f}] {content}')

print('\n'.join(lines))
PY
}

# Fast memory context retrieval with adaptive strategy based on memory size
openclaw_ai_stack_memory_context_text() {
  local query="$1"
  local memory_count strategy start_time
  start_time=$(date +%s%N 2>/dev/null || echo "0")
  
  # Check if memory features are enabled
  if [ "$(openclaw_memory_feature_enabled all 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    return 0
  fi
  
  # Get memory count to determine strategy
  memory_count=$(openclaw_memory_fast_count 2>/dev/null || echo "0")
  
  # Adaptive strategy: fast path for small memory, indexed path for large memory
  if [ "$memory_count" -lt 50 ]; then
    strategy="fast"
  elif [ "$memory_count" -lt 500 ]; then
    strategy="balanced"
  else
    strategy="indexed"
  fi
  
  # Execute unified memory fetch with appropriate strategy
  openclaw_memory_unified_fetch "$query" "$strategy" "$memory_count"
  
  # Log performance if slow (for debugging)
  local end_time elapsed_ms
  end_time=$(date +%s%N 2>/dev/null || echo "0")
  if [ "$start_time" != "0" ] && [ "$end_time" != "0" ]; then
    elapsed_ms=$(( (end_time - start_time) / 1000000 ))
    if [ "$elapsed_ms" -gt 200 ]; then
      echo "[memory_perf] strategy=$strategy count=$memory_count elapsed=${elapsed_ms}ms" >&2
    fi
  fi
}

# Fast memory count (cached, no DB query)
openclaw_memory_fast_count() {
  local cache_file count
  cache_file="${SKPL_AI_STACK_CACHE_DIR}/memory-count.cache"
  
  # Check cache (TTL 60 seconds for count)
  if [ -f "$cache_file" ]; then
    local cache_age
    cache_age=$(( $(date +%s) - $(stat -c %Y "$cache_file" 2>/dev/null || echo "0") ))
    if [ "$cache_age" -lt 60 ]; then
      cat "$cache_file" 2>/dev/null
      return 0
    fi
  fi
  
  # Fast count from SQLite (COUNT is fast)
  count=$(sqlite3 "$SKPL_MEMORY_EXTENSION_DB" "SELECT COUNT(*) FROM memory_entries WHERE deleted=0;" 2>/dev/null || echo "0")
  echo "$count" > "$cache_file"
  echo "$count"
}

# Unified memory fetch with strategy-aware optimization
openclaw_memory_unified_fetch() {
  local query="$1" strategy="$2" memory_count="$3"
  local model_context_size max_tokens
  
  # Get model context size once
  model_context_size=$(openclaw_get_model_context_size 2>/dev/null || echo "8192")
  max_tokens=$(( model_context_size * 15 / 100 ))  # 15% default
  
  # Single Python execution for all memory layers
  python3 - "$query" "$strategy" "$memory_count" "$max_tokens" "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_AI_STACK_CONTEXT_STATE_FILE" "$SKPL_HYBRID_MEMORY_DB" <<'PY'
import json
import sqlite3
import sys
import os
import time
from pathlib import Path

query = sys.argv[1]
strategy = sys.argv[2]  # fast, balanced, indexed
memory_count = int(sys.argv[3])
max_tokens = int(sys.argv[4])
db_path = sys.argv[5]
context_file = sys.argv[6]
hybrid_db = sys.argv[7]

lines = ['[memory_context]']
total_tokens = 0
def estimate_tokens(text):
    return len(text) // 4 + 1

def add_if_fits(content, source):
    global total_tokens
    tokens = estimate_tokens(content)
    if total_tokens + tokens <= max_tokens:
        lines.append(f"- [{source}] {content[:200]}")
        total_tokens += tokens
        return True
    return False

# Layer 1: Short-term memory (always fast - from JSON file)
try:
    if os.path.exists(context_file):
        with open(context_file, 'r', encoding='utf-8') as f:
            ctx = json.load(f)
        turns = ctx.get('recentTurns', [])
        for item in turns[-6:]:  # Last 6 turns
            if isinstance(item, dict):
                q = str(item.get('query', '')).strip()[:180]
                if q:
                    add_if_fits(f"recent: {q}", "short")
except Exception:
    pass

# For fast strategy with small memory: full scan is faster than index
if strategy == 'fast' and memory_count < 50:
    try:
        conn = sqlite3.connect(db_path)
        conn.execute("PRAGMA query_only = 1")
        rows = conn.execute(
            "SELECT category, title, content FROM memory_entries WHERE deleted=0 ORDER BY updated_at DESC LIMIT 20"
        ).fetchall()
        conn.close()
        
        for category, title, content in rows:
            text = f"{title or ''}: {content or ''}".strip(': ')
            if text and not add_if_fits(text, category or "memory"):
                break
    except Exception:
        pass

else:
    # Balanced/Indexed: Use similarity search
    try:
        # Build query tokens once
        query_words = set(''.join(c if c.isalnum() else ' ' for c in query.lower()).split())
        
        conn = sqlite3.connect(db_path)
        conn.execute("PRAGMA query_only = 1")
        
        # For indexed strategy, use FTS5 if available
        if strategy == 'indexed':
            try:
                # Try FTS5 match
                fts_rows = conn.execute(
                    "SELECT category, title, content FROM memory_entries_fts WHERE memory_entries_fts MATCH ? ORDER BY rank LIMIT 10",
                    (query,)
                ).fetchall()
                for category, title, content in fts_rows:
                    text = f"{title or ''}: {content or ''}".strip(': ')
                    if text and not add_if_fits(text, category or "fts"):
                        break
            except Exception:
                pass  # FTS5 not available, fall through
        
        # Fallback: token similarity with early termination
        rows = conn.execute(
            "SELECT category, title, content FROM memory_entries WHERE deleted=0 ORDER BY updated_at DESC LIMIT 100"
        ).fetchall()
        conn.close()
        
        scored = []
        for category, title, content in rows:
            text = f"{title or ''} {content or ''}"
            text_words = set(''.join(c if c.isalnum() else ' ' for c in text.lower()).split())
            if text_words and query_words:
                inter = len(query_words & text_words)
                union = len(query_words | text_words)
                score = inter / union if union else 0
                if score >= 0.3:  # Lower threshold for balanced
                    scored.append((score, category, title, content))
        
        scored.sort(reverse=True)
        for score, category, title, content in scored[:10]:
            text = f"{title or ''}: {content or ''}".strip(': ')
            if text and not add_if_fits(text, category or "memory"):
                break
    except Exception:
        pass

# Add stats line (minimal format)
if len(lines) > 1:
    lines.append(f"[m:cnt={memory_count},tok={total_tokens},strat={strategy}]")
    print('\n'.join(lines))
PY
}

openclaw_ai_stack_cloud_memory_policy() {
  memory_extension_prepare
  python3 - "$SKPL_MEMORY_EXTENSION_CONFIG" <<'PY'
import json, sys
cfg = json.loads(open(sys.argv[1], 'r', encoding='utf-8').read())
privacy = cfg.get('privacy', {}) if isinstance(cfg, dict) else {}
global_enabled = bool(cfg.get('enabled', True))
long_enabled = bool((cfg.get('longTerm') or {}).get('enabled', True))
local_only = bool(privacy.get('localOnly', True))
cloud_upload = bool(privacy.get('cloudUploadMemory', False))
if not global_enabled or not long_enabled:
    print('disabled')
elif local_only:
    print('local-only')
elif cloud_upload:
    print('allow')
else:
    print('strip')
PY
}

openclaw_ai_stack_filter_memory_for_cloud() {
  local memory_text="$1"
  local policy
  policy=$(openclaw_ai_stack_cloud_memory_policy)
  if [ "$policy" = "allow" ]; then
    printf '%s\n' "$memory_text"
    return 0
  fi
  if [ "$policy" = "disabled" ]; then
    return 0
  fi
  if [ "$policy" = "local-only" ]; then
    printf '%s\n' "[memory_context]\n- 当前为本地 only 模式，长期记忆只在本地推理链路使用。"
    return 0
  fi
  printf '%s\n' "[memory_context]\n- 云端模式已启用记忆禁传，本次不上传本地长期记忆。"
}

# ========================================================================
# 结构化数据检索引擎 — 支持JSON/CSV/表格数据的索引和查询
# ========================================================================
openclaw_ai_stack_structured_search() {
  local query="$1" data_type="${2:-json}"
  memory_extension_prepare
  python3 - "$query" "$data_type" "$SKPL_MEMORY_EXTENSION_DB" <<'PY'
import json, re, sqlite3, sys
query_text = sys.argv[1].lower()
data_type = sys.argv[2]
db_path = sys.argv[3]

conn = sqlite3.connect(db_path)
conn.execute('''CREATE TABLE IF NOT EXISTS structured_data (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    source TEXT, data_type TEXT, field_name TEXT, field_value TEXT,
    raw_payload TEXT, indexed_at INTEGER
)''')
conn.execute('CREATE INDEX IF NOT EXISTS idx_structured_field ON structured_data(field_name, field_value)')
conn.execute('CREATE INDEX IF NOT EXISTS idx_structured_type ON structured_data(data_type)')

# 搜索
query_words = re.findall(r'[\w\u4e00-\u9fff]+', query_text)
if not query_words:
    conn.close()
    print(json.dumps({'results': [], 'count': 0}, ensure_ascii=False))
    raise SystemExit(0)

results = []
for word in query_words:
    rows = conn.execute(
        'SELECT DISTINCT id, source, data_type, field_name, field_value, raw_payload, indexed_at FROM structured_data WHERE field_value LIKE ? OR field_name LIKE ? LIMIT 50',
        (f'%{word}%', f'%{word}%')
    ).fetchall()
    for row in rows:
        entry = {
            'id': row[0], 'source': row[1], 'type': row[2],
            'field': row[3], 'value': row[4][:500],
            'payload': row[5][:2000] if row[5] else '',
            'indexedAt': row[6],
        }
        # 计算相关性分数 (多词匹配加权)
        score = 0
        val_lower = (row[4] or '').lower()
        for w in query_words:
            score += val_lower.count(w)
            if (row[3] or '').lower() == w:
                score += 3
        entry['score'] = score
        if score > 0:
            results.append(entry)

results.sort(key=lambda x: -x['score'])

# 去重
seen_ids = set()
unique_results = []
for r in results:
    if r['id'] not in seen_ids:
        seen_ids.add(r['id'])
        unique_results.append(r)
conn.close()
print(json.dumps({'results': unique_results[:30], 'count': len(unique_results)}, ensure_ascii=False))
PY
}

# 结构化数据索引 (新增条目)
openclaw_ai_stack_structured_index() {
  local source="$1" entry_json="$2"
  memory_extension_prepare
  python3 - "$source" "$entry_json" "$SKPL_MEMORY_EXTENSION_DB" <<'PY'
import json, sys, time
source = sys.argv[1]
entry = json.loads(sys.argv[2])
db_path = sys.argv[3]
conn = sqlite3.connect(db_path)
conn.execute('''CREATE TABLE IF NOT EXISTS structured_data (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    source TEXT, data_type TEXT, field_name TEXT, field_value TEXT,
    raw_payload TEXT, indexed_at INTEGER
)''')
conn.execute('CREATE INDEX IF NOT EXISTS idx_structured_field ON structured_data(field_name, field_value)')
conn.execute('CREATE INDEX IF NOT EXISTS idx_structured_type ON structured_data(data_type)')

data_type = entry.get('type', 'json')
raw_payload = json.dumps(entry.get('data', {}), ensure_ascii=False) if entry.get('data') else ''
payload = entry.get('data', {})
now_ts = int(time.time())

count = [0]
def flatten(data, prefix=''):
    if isinstance(data, dict):
        for k, v in data.items():
            flatten(v, f'{prefix}.{k}' if prefix else k)
    elif isinstance(data, list):
        for i, v in enumerate(data):
            flatten(v, f'{prefix}[{i}]')
    else:
        conn.execute(
            'INSERT INTO structured_data (source, data_type, field_name, field_value, raw_payload, indexed_at) VALUES (?,?,?,?,?,?)',
            (source, data_type, prefix or 'root', str(data)[:2000], raw_payload, now_ts)
        )
        count[0] += 1

flatten(payload if payload else entry)
conn.commit()
conn.close()
print(json.dumps({'indexed': count[0], 'source': source}, ensure_ascii=False))
PY
}

# ========================================================================
# 多模态向量检索引擎 — 支持图像/音频等非文本数据的向量索引
# ========================================================================
openclaw_ai_stack_multimodal_vector_search() {
  local query_text="$1" modality="${2:-image}"
  openclaw_ai_stack_prepare
  memory_extension_prepare
  python3 - "$query_text" "$modality" "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_AI_STACK_ROOT/config.json" <<'PY'
import json, re, sqlite3, sys, time

query_text = sys.argv[1]
modality = sys.argv[2]
db_path = sys.argv[3]
cfg_path = sys.argv[4]
cfg = json.loads(open(cfg_path, 'r', encoding='utf-8').read())

conn = sqlite3.connect(db_path)
conn.execute('''CREATE TABLE IF NOT EXISTS multimodal_vectors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    modality TEXT, file_path TEXT, description TEXT,
    ocr_text TEXT, features TEXT, vector TEXT,
    source_hash TEXT, indexed_at INTEGER
)''')
conn.execute('CREATE INDEX IF NOT EXISTS idx_mmv_modality ON multimodal_vectors(modality)')
conn.execute('CREATE INDEX IF NOT EXISTS idx_mmv_hash ON multimodal_vectors(source_hash)')

# 搜索: 基于描述文本匹配 + OCR文本匹配
query_words = re.findall(r'[\w\u4e00-\u9fff]+', query_text.lower())
if not query_words:
    conn.close()
    print(json.dumps({'results': [], 'count': 0}, ensure_ascii=False))
    raise SystemExit(0)

results = []
for word in query_words:
    rows = conn.execute(
        'SELECT id, modality, file_path, description, ocr_text, features, source_hash, indexed_at FROM multimodal_vectors WHERE (description LIKE ? OR ocr_text LIKE ?) AND modality = ? LIMIT 30',
        (f'%{word}%', f'%{word}%', modality)
    ).fetchall()
    for row in rows:
        desc = (row[3] or '').lower()
        ocr = (row[4] or '').lower()
        score = sum(desc.count(w) * 2 + ocr.count(w) * 3 for w in query_words)
        results.append({
            'id': row[0], 'modality': row[1], 'filePath': row[2],
            'description': row[3], 'ocrText': (row[4] or '')[:200],
            'features': row[5], 'score': score,
            'sourceHash': row[6], 'indexedAt': row[7],
        })

results.sort(key=lambda x: -x['score'])
unique = {}
for r in results:
    h = r.get('sourceHash') or str(r['id'])
    if h not in unique or unique[h]['score'] < r['score']:
        unique[h] = r

conn.close()
print(json.dumps({'results': list(unique.values())[:20], 'count': len(unique)}, ensure_ascii=False))
PY
}

# 多模态向量索引 (新增条目)
