import json
import sys
from pathlib import Path

cache_dir = Path(sys.argv[1])
query = (sys.argv[2] or '').strip().lower()
tokens = [part for part in query.split() if part]
best = None
best_score = 0
for path in cache_dir.glob('*.json'):
    try:
        data = json.loads(path.read_text(encoding='utf-8'))
