PY
}

memory_extension_prepare() {
  hybrid_memory_prepare_dirs
  python3 - "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_MEMORY_EXTENSION_CONFIG" <<'PY'
import json
import sqlite3
import sys
from pathlib import Path

db_path = Path(sys.argv[1])
config_path = Path(sys.argv[2])
db_path.parent.mkdir(parents=True, exist_ok=True)
conn = sqlite3.connect(db_path)
conn.execute('create table if not exists memory_entries (id integer primary key autoincrement, category text not null, title text not null, content text not null, tags text not null default "[]", sensitive integer not null default 0, deleted integer not null default 0, created_at integer not null, updated_at integer not null)')
conn.execute('create index if not exists idx_memory_entries_category on memory_entries(category)')
conn.execute('create index if not exists idx_memory_entries_deleted on memory_entries(deleted)')
conn.commit()
conn.close()

default_config = {
    'enabled': True,
    'shortTerm': {'enabled': True, 'maxItems': 24},
    'midTerm': {'enabled': True, 'retentionDays': 14},
    'longTerm': {'enabled': True, 'autoExtract': 'balanced'},
    'knowledgeBase': {'enabled': True, 'weight': 1.0},
    'privacy': {
        'localOnly': True,
        'maskSensitive': True,
        'blockedKeywords': [],
        'encryptAtRest': False,
        'cloudUploadMemory': False
    },
    'injection': {
        'maxContextPercent': 15,
        'similarityThreshold': 0.58,
        'maxResults': 5
    },
    'maintenance': {
        'cleanupDays': 30,
        'autoUpdateMinutes': 30
    }
}

if config_path.exists():
    try:
        current = json.loads(config_path.read_text(encoding='utf-8'))
        if isinstance(current, dict):
            merged = default_config
            merged.update(current)
            default_config = merged
    except Exception:
        pass

config_path.write_text(json.dumps(default_config, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
PY
}

memory_extension_search_json() {
  local query="$1"
  if [ "$(openclaw_memory_feature_enabled all 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    printf '%s\n' '[]'
    return 0
  fi
  if [ "$(openclaw_memory_feature_enabled longTerm 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    printf '%s\n' '[]'
    return 0
  fi
  memory_extension_prepare
  python3 - "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_MEMORY_EXTENSION_CONFIG" "$query" <<'PY'
import json
import sqlite3
import sys
import base64

db_path = sys.argv[1]
config_path = sys.argv[2]
query = (sys.argv[3] or '').strip().lower()
cfg = json.loads(open(config_path, 'r', encoding='utf-8').read())
privacy = cfg.get('privacy', {}) if isinstance(cfg, dict) else {}

def decrypt_if_needed(value):
    if not isinstance(value, str):
        return value
    if not value.startswith('enc::'):
        return value
    try:
        import os
        from cryptography.fernet import Fernet
        
        key_file = os.path.expanduser('~/.skpl/.memory-key')
        if os.path.exists(key_file):
            with open(key_file, 'r') as f:
                key = f.read().strip()
        else:
            key = os.environ.get('OPENCLAW_MEMORY_KEY', '')
            if not key:
                return value
        
        key = key.ljust(32, '0')[:32]
        key = base64.urlsafe_b64encode(key.encode())
        
        cipher = Fernet(key)
        token = base64.urlsafe_b64decode(value[5:].encode())
        return cipher.decrypt(token).decode('utf-8')
    except Exception:
        # Fallback to legacy XOR
        try:
            raw = base64.b64decode(value[5:].encode('utf-8')).decode('utf-8')
            return ''.join(chr(ord(ch) ^ 23) for ch in raw)
        except Exception:
            return value

conn = sqlite3.connect(db_path)
rows = conn.execute('select id, category, title, content, tags, sensitive, updated_at from memory_entries where deleted = 0 order by updated_at desc limit 200').fetchall()
conn.close()

def score_item(row, needle):
    _id, category, title, content, tags_raw, sensitive, updated_at = row
    title = decrypt_if_needed(title)
    content = decrypt_if_needed(content)
    tags = []
    try:
        tags = json.loads(tags_raw or '[]')
        if not isinstance(tags, list):
            tags = []
    except Exception:
        tags = []
    text = ' '.join([category or '', title or '', content or '', ' '.join(str(x) for x in tags)])
    hay = text.lower()
    score = 0.0
    reasons = []
    if not needle:
        score = 0.1
    else:
        if needle in (title or '').lower():
            score += 2.2
            reasons.append('标题命中')
        if needle in (content or '').lower():
            score += 1.6
            reasons.append('内容命中')
        if needle in (category or '').lower():
            score += 1.2
            reasons.append('分类命中')
        for tag in tags:
            t = str(tag).lower()
            if needle in t:
                score += 1.4
                reasons.append('标签命中')
                break
        tokens = [t for t in needle.split() if t]
        for token in tokens:
            if token in hay:
                score += 0.35
    return {
        'id': _id,
        'source': 'memory-extension',
        'summary': title,
        'score': score,
        'channels': ['long-term-memory'],
        'category': category,
        'sensitive': bool(sensitive),
        'updatedAt': updated_at,
        'explain': ' / '.join(reasons[:3]) if reasons else '长期记忆命中',
    }

items = [score_item(row, query) for row in rows]
items = [item for item in items if item['score'] > 0]
items.sort(key=lambda x: (x['score'], x['updatedAt']), reverse=True)
print(json.dumps(items[:5], ensure_ascii=False))
PY
}

memory_extension_upsert_entry() {
  local category="$1" title="$2" content="$3" tags_json="${4:-[]}" sensitive="${5:-0}"
  [ -n "$category" ] || return 1
  [ -n "$title" ] || return 1
  [ -n "$content" ] || return 1
  if [ "$(openclaw_memory_feature_enabled all 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    echo "ℹ️ 记忆总开关当前关闭，已跳过写入。"
    return 0
  fi
  if [ "$(openclaw_memory_feature_enabled longTerm 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    echo "ℹ️ 长期记忆当前关闭，已跳过写入。"
    return 0
  fi
  memory_extension_prepare
  python3 - "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_MEMORY_EXTENSION_CONFIG" "$category" "$title" "$content" "$tags_json" "$sensitive" <<'PY'
import json
import sqlite3
import sys
import time
import base64

db_path, config_path, category, title, content, tags_raw, sensitive = sys.argv[1:8]
now = int(time.time())
cfg = json.loads(open(config_path, 'r', encoding='utf-8').read())
privacy = cfg.get('privacy', {}) if isinstance(cfg, dict) else {}
blocked = [str(item).lower() for item in privacy.get('blockedKeywords', []) if str(item).strip()]

def mask_sensitive_text(value):
    import re
    value = re.sub(r'([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\.[A-Za-z]{2,})', r'***@\2', value)
    value = re.sub(r'\b1\d{10}\b', '1**********', value)
    value = re.sub(r'\b\d{15,19}\b', '****', value)
    return value

def encrypt_text(value):
    raw = ''.join(chr(ord(ch) ^ 23) for ch in value)
    return 'enc::' + base64.b64encode(raw.encode('utf-8')).decode('utf-8')

merged_text = ' '.join([category, title, content]).lower()
for word in blocked:
    if word and word in merged_text:
        raise SystemExit(4)

if bool(privacy.get('maskSensitive', True)):
    title = mask_sensitive_text(title)
    content = mask_sensitive_text(content)

if bool(privacy.get('encryptAtRest', False)):
    title = encrypt_text(title)
    content = encrypt_text(content)

conn = sqlite3.connect(db_path)
row = conn.execute('select id from memory_entries where deleted = 0 and category = ? and title = ? limit 1', (category, title)).fetchone()
if row:
    conn.execute('update memory_entries set content = ?, tags = ?, sensitive = ?, updated_at = ? where id = ?', (content, tags_raw, int(sensitive), now, row[0]))
else:
    conn.execute('insert into memory_entries (category, title, content, tags, sensitive, deleted, created_at, updated_at) values (?, ?, ?, ?, ?, 0, ?, ?)', (category, title, content, tags_raw, int(sensitive), now, now))
conn.commit()
conn.close()
PY
  local rc=$?
  if [ "$rc" = "4" ]; then
    echo "⚠️ 该记忆命中屏蔽关键词，已跳过写入。"
    return 0
  fi
  return "$rc"
}

memory_extension_get_config_json() {
  memory_extension_prepare
  python3 - "$SKPL_MEMORY_EXTENSION_CONFIG" <<'PY'
from pathlib import Path
import json
import sys
path = Path(sys.argv[1])
print(path.read_text(encoding='utf-8'))
PY
}

memory_extension_update_config_field() {
  local field_path="$1" field_value="$2" value_type="${3:-string}"
  memory_extension_prepare
  python3 - "$SKPL_MEMORY_EXTENSION_CONFIG" "$field_path" "$field_value" "$value_type" <<'PY'
import json
import sys
from pathlib import Path

path = Path(sys.argv[1])
field_path = sys.argv[2].split('.')
field_value = sys.argv[3]
value_type = sys.argv[4]
data = json.loads(path.read_text(encoding='utf-8'))
cur = data
for key in field_path[:-1]:
    node = cur.get(key)
    if not isinstance(node, dict):
        node = {}
        cur[key] = node
    cur = node
last = field_path[-1]
if value_type == 'bool':
    cur[last] = field_value.lower() in ('1', 'true', 'yes', 'y', 'on')
elif value_type == 'int':
    cur[last] = int(field_value)
elif value_type == 'float':
    cur[last] = float(field_value)
elif value_type == 'json':
    cur[last] = json.loads(field_value)
else:
    cur[last] = field_value
path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
PY
}

openclaw_detect_hardware_profile_json() {
  if skpl_cached_hardware_profile 2>/dev/null; then
    return 0
  fi
  # 使用子shell和timeout确保不会卡住
  # WSL检测：在WSL环境中跳过nvidia-smi避免挂起
  if grep -qi "microsoft\|WSL" /proc/sys/kernel/osrelease 2>/dev/null || [ -n "$WSL_DISTRO_NAME" ]; then
    echo '{"tier":"entry-cpu","memoryMb":8192,"cpuThreads":4,"cpuInstructionSet":[],"gpu":{"present":false,"name":"WSL-skipped","vramMb":0,"freeVramMb":0},"storage":{"totalGb":256,"freeGb":128,"type":"ssd"},"network":{"online":true,"latencyMs":50,"quality":"online"},"battery":{"present":false,"percent":null},"budget":{"reserveGpuMb":0,"reserveMemoryMb":512,"usableMemoryMb":7680,"usableGpuMb":0}}'
    return 0
  fi
  (
    timeout 10 python3 - <<'PY'
import json
import os
import re
import shutil
import subprocess
from pathlib import Path

def read_mem_mb():
    try:
        with open('/proc/meminfo', 'r', encoding='utf-8') as f:
            for line in f:
                if line.startswith('MemTotal:'):
                    return int(line.split()[1]) // 1024
    except Exception:
        pass
    return 0

def cpu_threads():
    try:
        return os.cpu_count() or 1
    except Exception:
        return 1

def cpu_flags():
    try:
        with open('/proc/cpuinfo', 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if line.lower().startswith('flags') or line.lower().startswith('features'):
                    return line.split(':', 1)[1].strip().split()
    except Exception:
        pass
    return []

def cpu_instruction_profile(flags):
    wanted = ['avx512f', 'avx2', 'avx', 'f16c', 'sse4_2', 'neon']
    return [flag for flag in wanted if flag in set(flags)]

def storage_info():
    try:
        usage = shutil.disk_usage('/')
        rotational = None
        storage_type = 'unknown'
        try:
            root_dev = os.path.realpath('/dev/disk/by-uuid')
        except Exception:
            root_dev = ''
        for candidate in ('/sys/block/nvme0n1/queue/rotational', '/sys/block/sda/queue/rotational', '/sys/block/vda/queue/rotational'):
            p = Path(candidate)
            if p.exists():
                rotational = p.read_text().strip()
                break
        if rotational == '0':
            storage_type = 'ssd'
        elif rotational == '1':
            storage_type = 'hdd'
        return {'totalGb': round(usage.total / (1024**3), 1), 'freeGb': round(usage.free / (1024**3), 1), 'type': storage_type}
    except Exception:
        return {'totalGb': 0, 'freeGb': 0, 'type': 'unknown'}

def network_info():
    latency_ms = None
    online = False
    quality = 'offline'
    # 修复：使用 socket 直接检测，避免 bash -lc 加载慢的问题
    try:
        import socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(2)
        result = sock.connect_ex(('223.5.5.5', 53))  # 阿里云 DNS
        if result == 0:
            online = True
        sock.close()
    except Exception:
        online = False
    # 延迟检测 - 使用更轻量的方式
    if online:
        try:
            import time
            start = time.time()
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(2)
            sock.connect(('223.5.5.5', 53))
            sock.close()
            latency_ms = (time.time() - start) * 1000
        except Exception:
            latency_ms = None
    if online and latency_ms is not None:
        if latency_ms <= 80:
            quality = 'excellent'
        elif latency_ms <= 180:
            quality = 'normal'
        else:
            quality = 'slow'
    elif online:
        quality = 'online'
    return {'online': online, 'latencyMs': latency_ms, 'quality': quality}

def battery_present():
    base = Path('/sys/class/power_supply')
    if not base.exists():
        return {'present': False, 'percent': None}
    for item in base.iterdir():
        try:
            if item.name.startswith('BAT'):
                cap = item / 'capacity'
                percent = int(cap.read_text().strip()) if cap.exists() else None
                return {'present': True, 'percent': percent}
        except Exception:
            pass
    return {'present': False, 'percent': None}

def gpu_info():
    if not shutil.which('nvidia-smi'):
        return {'present': False, 'name': '', 'vramMb': 0, 'freeVramMb': 0}
    try:
        out = subprocess.check_output(['nvidia-smi', '--query-gpu=name,memory.total,memory.free', '--format=csv,noheader,nounits'], text=True, timeout=3)
        line = out.strip().splitlines()[0]
        parts = [p.strip() for p in line.split(',')]
        return {'present': True, 'name': parts[0], 'vramMb': int(parts[1]), 'freeVramMb': int(parts[2])}
    except Exception:
        return {'present': False, 'name': '', 'vramMb': 0, 'freeVramMb': 0}

mem_mb = read_mem_mb()
threads = cpu_threads()
flags = cpu_flags()
gpu = gpu_info()
storage = storage_info()
battery = battery_present()
network = network_info()

if gpu['present']:
    vram = gpu['vramMb']
    # 规范要求: 每级需同时满足VRAM和系统内存约束
    if vram >= 48000 and mem_mb >= 128000:
        tier = 'server'
    elif vram >= 16000 and mem_mb >= 64000:
        tier = 'workstation'
    elif vram >= 12000 and mem_mb >= 32000:
        tier = 'flagship-gpu'
    elif vram >= 8000 and mem_mb >= 16000:
        tier = 'golden-gpu'
    elif vram >= 4000 and mem_mb >= 8000:
        tier = 'advanced-gpu'
    elif vram >= 2000 and mem_mb >= 8000:
        tier = 'entry-gpu'
    else:
        # GPU存在但规格不足对应tier，降级到CPU tier
        if mem_mb < 4096:
            tier = 'emergency-cpu'
        elif mem_mb < 8192:
            tier = 'entry-cpu'
        else:
            tier = 'advanced-cpu'
else:
    if mem_mb < 4096:
        tier = 'emergency-cpu'
    elif mem_mb < 8192:
        tier = 'entry-cpu'
    elif mem_mb < 16384:
        tier = 'advanced-cpu'
    else:
        tier = 'advanced-cpu'

budget = {
    'reserveGpuMb': 200,
    'reserveMemoryMb': 512,
    'usableMemoryMb': max(mem_mb - 512, 0),
    'usableGpuMb': max(gpu['freeVramMb'] - 200, 0) if gpu['present'] else 0,
}

print(json.dumps({
    'tier': tier,
    'memoryMb': mem_mb,
    'cpuThreads': threads,
    'cpuInstructionSet': cpu_instruction_profile(flags),
    'gpu': gpu,
    'storage': storage,
    'network': network,
    'battery': battery,
    'budget': budget,
}, ensure_ascii=False))
PY
  ) || {
    # 超时或失败时使用默认值
    echo '{"tier":"unknown","memoryMb":8192,"cpuThreads":4,"cpuInstructionSet":[],"gpu":{"present":false,"name":"","vramMb":0,"freeVramMb":0},"storage":{"totalGb":0,"freeGb":0,"type":"unknown"},"network":{"online":false,"latencyMs":null,"quality":"offline"},"battery":{"present":false,"percent":null},"budget":{"reserveGpuMb":200,"reserveMemoryMb":512,"usableMemoryMb":7680,"usableGpuMb":0}}'
    return 0
  }
  skpl_cache_hardware_profile
}

openclaw_render_hardware_profile() {
  local profile_json
  profile_json=$(openclaw_detect_hardware_profile_json)
  python3 - "$profile_json" <<'PY'
import json, sys
data = json.loads(sys.argv[1])
gpu = data.get('gpu', {})
storage = data.get('storage', {})
battery = data.get('battery', {})
budget = data.get('budget', {})
print(f"硬件分级: {data.get('tier', 'unknown')}")
print(f"系统内存: {data.get('memoryMb', 0)} MB")
print(f"CPU线程: {data.get('cpuThreads', 1)}")
if gpu.get('present'):
    print(f"GPU: {gpu.get('name', '-')}")
    print(f"显存: {gpu.get('vramMb', 0)} MB / 可用 {gpu.get('freeVramMb', 0)} MB")
else:
    print("GPU: 未检测到")
print(f"磁盘剩余: {storage.get('freeGb', 0)} GB / 总计 {storage.get('totalGb', 0)} GB")
if battery.get('present'):
    print(f"电池: {battery.get('percent')}%")
else:
    print("电池: 未检测到")
print(f"记忆保留预算: GPU {budget.get('reserveGpuMb', 0)} MB / 内存 {budget.get('reserveMemoryMb', 0)} MB")
PY
}

hybrid_memory_write_broker() {
  hybrid_memory_prepare_dirs
  cat > "$SKPL_HYBRID_MEMORY_BROKER" <<'PY'
#!/usr/bin/env python3
import hashlib
import json
import math
import sqlite3
import sys
import time
from pathlib import Path

db_path = Path(sys.argv[1])
action = sys.argv[2] if len(sys.argv) > 2 else 'status'
payload = Path(sys.argv[3]) if len(sys.argv) > 3 else None

VECTOR_DIM = 128
STOPWORDS = {
    'a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in', 'into', 'is', 'of', 'on', 'or', 'the', 'to', 'with'
}

try:
    import lancedb
    LANCEDB_READY = True
except Exception:
    lancedb = None
    LANCEDB_READY = False

db_path.parent.mkdir(parents=True, exist_ok=True)
conn = sqlite3.connect(db_path)
conn.execute('create virtual table if not exists memory_fts using fts5(id, kind, source, summary, text, tags)')
conn.execute('create table if not exists memory_objects (id text primary key, kind text, source text, summary text, text text, tags text, confidence real, created_at integer)')

lancedb_path = db_path.parent / 'lancedb-store'
lance_table = None
collection_name = 'hybrid_memory'

if LANCEDB_READY:
    try:
        lancedb_path.mkdir(parents=True, exist_ok=True)
        lance_db = lancedb.connect(str(lancedb_path))
        try:
            lance_table = lance_db.open_table(collection_name)
        except Exception:
            lance_table = lance_db.create_table(collection_name, data=[{
                'id': '__bootstrap__',
                'vector': [0.0] * VECTOR_DIM,
                'summary': 'bootstrap',
                'source': 'system'
            }], mode='overwrite')
            try:
                lance_table.delete('id = "__bootstrap__"')
            except Exception:
                pass
    except Exception:
        lance_table = None


def embed_text(text: str):
    vec = [0.0] * VECTOR_DIM
    for token in (text or '').lower().split():
        digest = hashlib.sha256(token.encode('utf-8')).digest()
        idx = digest[0] % VECTOR_DIM
        sign = 1.0 if digest[1] % 2 == 0 else -1.0
        weight = 1.0 + (digest[2] / 255.0)
        vec[idx] += sign * weight
    norm = math.sqrt(sum(v * v for v in vec)) or 1.0
    return [v / norm for v in vec]


def parse_tags(raw):
    try:
        data = json.loads(raw or '[]')
        return data if isinstance(data, list) else []
    except Exception:
        return []


def tokenize(text: str):
    return [token for token in (text or '').lower().replace('_', ' ').replace('-', ' ').split() if token]


def content_tokens(text: str):
    return [token for token in tokenize(text) if token not in STOPWORDS]


def normalize_query(text: str):
    normalized = ' '.join(tokenize(text))
    alias_map = {
        'mem': 'memory',
        'memo': 'memory',
        'mems': 'memory',
        'memories': 'memory',
        'hybrid': 'hybrid memory',
        'hybrid-memory': 'hybrid memory',
        'hybridmemory': 'hybrid memory',
        'hybird': 'hybrid memory',
        'hyprid': 'hybrid memory',
        'vectordb': 'vector',
        'vec': 'vector',
        'vectors': 'vector',
        'evomapai': 'evomap',
        'evo': 'evomap',
        'evolver': 'evomap',
        'gatewayd': 'gateway',
        'gatewat': 'gateway',
        'gway': 'gateway',
        'idx': 'index',
        'indx': 'index',
        'fts': 'fts5',
        'qdrantdb': 'lancedb',
        'lance': 'lancedb',
        'lancedb': 'lancedb',
    }
    expanded = []
    for token in tokenize(normalized):
        mapped = alias_map.get(token, token)
        expanded.extend(tokenize(mapped))
    return ' '.join(expanded)


def build_fts_queries(text: str):
    normalized = normalize_query(text)
    tokens = content_tokens(normalized) or tokenize(normalized)
    queries = []

    if normalized:
        queries.append(f'"{normalized}"')
    if tokens:
        queries.append(' AND '.join(tokens))
        queries.append(' OR '.join(f'{token}*' for token in tokens if len(token) >= 2))
        if len(tokens) == 1 and len(tokens[0]) >= 2:
            queries.append(f'{tokens[0]}*')

    dedup = []
    seen = set()
    for item in queries:
        item = (item or '').strip()
        if not item or item in seen:
            continue
        seen.add(item)
        dedup.append(item)
    return dedup[:3]


def build_relaxed_queries(text: str):
    normalized = normalize_query(text)
    tokens = content_tokens(normalized) or tokenize(normalized)
    if not tokens:
        return []

    queries = []
    if len(tokens) >= 2:
        queries.append(' OR '.join(tokens))
    short_tokens = [f'{token}*' for token in tokens if len(token) >= 2]
    if short_tokens:
        queries.append(' OR '.join(short_tokens))

    dedup = []
    seen = set()
    for item in queries:
        item = (item or '').strip()
        if not item or item in seen:
            continue
        seen.add(item)
        dedup.append(item)
    return dedup[:2]


def retrieval_balance(query: str):
    tokens = content_tokens(query) or tokenize(query)
    token_count = len(tokens)
    char_count = len((query or '').strip())

    if token_count <= 1 and char_count <= 10:
        return 1.2, 0.8, '短查询偏词面'
    if token_count >= 4 or char_count >= 24:
        return 0.95, 1.15, '长查询偏语义'
    return 1.05, 1.0, '中等查询均衡融合'


def compact_text(*parts):
    return ' '.join(part.strip() for part in parts if part and part.strip())


def lexical_bonus(query: str, summary: str, source: str, text: str, tags):
    query_text = (query or '').strip().lower()
    if not query_text:
        return 0.0, []

    summary_text = (summary or '').lower()
    tag_text = ' '.join(tags or []).lower()
    body_text = (text or '').lower()
    source_text = (source or '').lower()
    full_text = compact_text(summary or '', text or '', ' '.join(tags or []), source or '').lower()
    query_tokens = content_tokens(query_text) or tokenize(query_text)
    tag_set = {str(tag).lower() for tag in (tags or [])}
    bonus = 0.0
    reasons = []

    if query_text in tag_set:
        bonus += 1.35
        reasons.append('标签精确命中')

    if query_text and query_text in summary_text:
        bonus += 1.55
        reasons.append('标题短语命中')
    elif query_text and query_text in tag_text:
        bonus += 1.1
        reasons.append('标签短语命中')
    elif query_text and query_text in body_text:
        bonus += 0.9
        reasons.append('正文短语命中')
    elif query_text and query_text in source_text:
        bonus += 0.55
        reasons.append('来源短语命中')

    token_hits = 0
    for token in query_tokens:
        token_weight = 0.65 if token in STOPWORDS else 1.0
        if any(tag == token for tag in tag_set):
            bonus += 0.7 * token_weight
            reasons.append(f'标签命中:{token}')
        elif any(tag.startswith(token) for tag in tag_set if len(token) >= 2):
            bonus += 0.35 * token_weight
            reasons.append(f'标签前缀命中:{token}')

        if summary_text.startswith(token):
            bonus += 0.5 * token_weight
            reasons.append(f'标题前缀命中:{token}')
        if token in summary_text:
            bonus += 0.52 * token_weight
            token_hits += 1
            reasons.append(f'标题命中:{token}')
        elif token in tag_text:
            bonus += 0.38 * token_weight
            token_hits += 1
            reasons.append(f'标签命中:{token}')
        elif token in body_text:
            bonus += 0.2 * token_weight
            token_hits += 1
            reasons.append(f'正文命中:{token}')
        elif token in source_text:
            bonus += 0.12 * token_weight
            token_hits += 1
            reasons.append(f'来源命中:{token}')
        if token in tag_set:
            bonus += 0.18 * token_weight
        if source and token in source_text:
            bonus += 0.15 * token_weight

    if token_hits and query_tokens and token_hits == len(query_tokens):
        bonus += 0.5
        reasons.append('关键词全命中')
    elif token_hits:
        reasons.append(f'关键词命中{token_hits}个')

    return bonus, reasons


def score_text_match(query: str, title: str, body: str, source: str, base_score: float, channel: str):
    query = normalize_query(query)
    tags = tokenize(title) + tokenize(source)
    bonus, reasons = lexical_bonus(query, title or '', source or '', body or '', tags)
    return {
        'score': base_score + bonus,
        'reasons': reasons[:4],
        'channel': channel,
    }


def upsert_vector(data):
    if not lance_table:
        return
    text = ' '.join(filter(None, [data.get('summary', ''), data.get('text', ''), ' '.join(data.get('tags', []))]))
    vector = embed_text(text)
    try:
        lance_table.delete(f"id = '{(data.get('id') or '').replace("'", "''")}'")
    except Exception:
        pass
    lance_table.add([{
        'id': data.get('id'),
        'vector': vector,
        'summary': data.get('summary'),
        'source': data.get('source'),
    }])

if action == 'ingest' and payload and payload.exists():
    data = json.loads(payload.read_text(encoding='utf-8'))
    conn.execute(
        'insert or replace into memory_objects (id, kind, source, summary, text, tags, confidence, created_at) values (?, ?, ?, ?, ?, ?, ?, ?)',
        (
            data.get('id'), data.get('kind'), data.get('source'), data.get('summary'), data.get('text'),
            json.dumps(data.get('tags', []), ensure_ascii=False), float(data.get('confidence', 0.5)), int(time.time())
        )
    )
    conn.execute('delete from memory_fts where id = ?', (data.get('id'),))
    conn.execute(
        'insert into memory_fts (id, kind, source, summary, text, tags) values (?, ?, ?, ?, ?, ?)',
        (
            data.get('id'), data.get('kind'), data.get('source'), data.get('summary'), data.get('text'),
            ' '.join(data.get('tags', []))
        )
    )
    conn.commit()
    upsert_vector(data)
    print('ingested')
elif action == 'status':
    count = conn.execute('select count(*) from memory_objects').fetchone()[0]
    vector_count = 0
    if lance_table:
        try:
            vector_count = len(lance_table.search().limit(1000000).to_list())
        except Exception:
            vector_count = 0
    print(json.dumps({
        'objects': count,
        'plugins': {
            'fts5': {'enabled': True, 'status': 'ready'},
            'vector': {'enabled': bool(lance_table), 'status': 'ready' if lance_table else ('missing-package' if not LANCEDB_READY else 'init-failed')},
            'rerank': {'enabled': False, 'status': 'reserved'},
        },
        'vectorObjects': vector_count,
    }, ensure_ascii=False))
elif action == 'search':
    query = sys.argv[3] if len(sys.argv) > 3 else ''
    normalized_query = normalize_query(query)
    results = {}
    query_tokens = content_tokens(normalized_query) or tokenize(normalized_query)
    fts_queries = build_fts_queries(query)
    lexical_weight, semantic_weight, balance_reason = retrieval_balance(normalized_query)

    for query_rank, fts_query in enumerate(fts_queries, start=1):
        try:
            rows = conn.execute(
                'select id, summary, source, text, tags from memory_fts where memory_fts match ? limit 8',
                (fts_query,)
            ).fetchall()
        except Exception:
            rows = []

        for rank, row in enumerate(rows, start=1):
            rid, summary, source, text, tags_raw = row
            tags = (tags_raw or '').split()
            item = results.setdefault(rid, {'id': rid, 'summary': summary, 'source': source, 'score': 0.0, 'channels': [], 'reasons': [], 'created_at': 0, 'field_rank': 0, 'used_fallback': False})
            item['score'] += ((1.4 / rank) / query_rank) * lexical_weight
            bonus, reasons = lexical_bonus(normalized_query, summary, source, text, tags)
            item['score'] += bonus * lexical_weight
            item['field_rank'] = max(item.get('field_rank', 0), 4)
            item['reasons'].append(balance_reason)
            if query_rank == 1:
                item['reasons'].append('短语检索命中')
            elif query_rank == 2:
                item['reasons'].append('多词检索命中')
            else:
                item['reasons'].append('前缀检索命中')
            item['reasons'].extend(reasons)
            item['channels'].append('fts5')

    if not results:
        for query_rank, fts_query in enumerate(build_relaxed_queries(query), start=1):
            try:
                rows = conn.execute(
                    'select id, summary, source, text, tags from memory_fts where memory_fts match ? limit 8',
                    (fts_query,)
                ).fetchall()
            except Exception:
                rows = []

            for rank, row in enumerate(rows, start=1):
                rid, summary, source, text, tags_raw = row
                tags = (tags_raw or '').split()
                item = results.setdefault(rid, {'id': rid, 'summary': summary, 'source': source, 'score': 0.0, 'channels': [], 'reasons': [], 'created_at': 0, 'field_rank': 0, 'used_fallback': False})
                item['score'] += ((0.95 / rank) / query_rank) * lexical_weight
                bonus, reasons = lexical_bonus(normalized_query, summary, source, text, tags)
                item['score'] += bonus * 0.85 * lexical_weight
                item['field_rank'] = max(item.get('field_rank', 0), 3)
                item['used_fallback'] = True
                item['reasons'].append(balance_reason)
                item['reasons'].append('宽松检索回退')
                item['reasons'].extend(reasons)
                item['channels'].append('fts5')

    if lance_table:
        query_vector = embed_text(normalized_query)
        try:
            vector_hits = lance_table.search(query_vector).limit(8).to_list()
        except Exception:
            vector_hits = []
        for rank, hit in enumerate(vector_hits, start=1):
            payload = hit or {}
            rid = payload.get('id')
            if not rid:
                continue
            item = results.setdefault(rid, {'id': rid, 'summary': payload.get('summary', ''), 'source': payload.get('source', 'vector'), 'score': 0.0, 'channels': [], 'reasons': [], 'created_at': 0, 'field_rank': 0, 'used_fallback': False})
            semantic_score = float(payload.get('_distance', 0.0) or 0.0)
            semantic_score = max(0.0, 1.0 - semantic_score)
            item['score'] += ((semantic_score * 1.1) + (0.55 / rank)) * semantic_weight
            item['field_rank'] = max(item.get('field_rank', 0), 2)
            item['reasons'].append(balance_reason)
            if semantic_score >= 0.8:
                item['reasons'].append('高语义相似')
            elif semantic_score >= 0.55:
                item['reasons'].append('语义相似')
            item['channels'].append('vector')

    fast_cards_dir = db_path.parent / 'knowledge' / 'fast-cards'
    if fast_cards_dir.is_dir():
        for card_path in list(fast_cards_dir.glob('*.md'))[:40]:
            body = card_path.read_text(encoding='utf-8', errors='ignore')
            title = body.splitlines()[0].lstrip('# ').strip() if body.splitlines() else card_path.stem
            match = score_text_match(normalized_query, title, body, 'fast-card', 0.65, 'fast-card')
            if match['score'] <= 0.66:
                continue
            rid = f'fast-card::{card_path.stem}'
            item = results.setdefault(rid, {'id': rid, 'summary': title, 'source': 'fast-card', 'score': 0.0, 'channels': [], 'reasons': [], 'created_at': 0, 'field_rank': 0, 'used_fallback': False})
            item['score'] += match['score']
            item['field_rank'] = max(item.get('field_rank', 0), 2)
            item['reasons'].append('知识卡命中')
            item['reasons'].extend(match['reasons'])
            item['channels'].append('fast-card')

    skills_dir = db_path.parent.parent / 'memos' / 'skills'
    if skills_dir.is_dir():
        for skill_path in list(skills_dir.glob('*/SKILL.md'))[:40]:
            body = skill_path.read_text(encoding='utf-8', errors='ignore')
            title = body.splitlines()[0].lstrip('# ').strip() if body.splitlines() else skill_path.parent.name
            match = score_text_match(normalized_query, title, body, 'memos-skill', 0.75, 'skill')
            if match['score'] <= 0.76:
                continue
            rid = f'skill::{skill_path.parent.name}'
            item = results.setdefault(rid, {'id': rid, 'summary': title, 'source': 'memos-skill', 'score': 0.0, 'channels': [], 'reasons': [], 'created_at': 0, 'field_rank': 0, 'used_fallback': False})
            item['score'] += match['score']
            item['field_rank'] = max(item.get('field_rank', 0), 3)
            item['reasons'].append('技能卡命中')
            item['reasons'].extend(match['reasons'])
            item['channels'].append('skill')

    for item in results.values():
        confidence = conn.execute('select confidence, created_at, text, tags from memory_objects where id = ?', (item['id'],)).fetchone()
        if confidence:
            conf_value, created_at, full_text, tags_raw = confidence
            age_hours = max((time.time() - int(created_at)) / 3600.0, 0.0)
            recency_bonus = 0.25 / (1.0 + age_hours / 24.0)
            tags = parse_tags(tags_raw)
            lexical_score, reasons = lexical_bonus(normalized_query, item.get('summary', ''), item.get('source', ''), full_text or '', tags)
            item['score'] += float(conf_value or 0.5) * 0.45 + recency_bonus + (lexical_score * 0.35 * lexical_weight)
            item['reasons'].extend(reasons)
            item['created_at'] = int(created_at or 0)

            summary_text = (item.get('summary') or '').lower()
            tag_text = ' '.join(tags or []).lower()
            body_text = (full_text or '').lower()
            source_text = (item.get('source') or '').lower()
            if normalized_query and normalized_query in summary_text:
                item['field_rank'] = max(item.get('field_rank', 0), 4)
            elif normalized_query and normalized_query in tag_text:
                item['field_rank'] = max(item.get('field_rank', 0), 3)
            elif normalized_query and normalized_query in body_text:
                item['field_rank'] = max(item.get('field_rank', 0), 2)
            elif normalized_query and normalized_query in source_text:
                item['field_rank'] = max(item.get('field_rank', 0), 1)

        if item.get('source') == 'openclaw':
            item['score'] += 0.08
        if item.get('summary') and query_tokens:
            summary_tokens = tokenize(item.get('summary', ''))
            if summary_tokens[:len(query_tokens)] == query_tokens[:len(summary_tokens)]:
                item['score'] += 0.18

    for item in results.values():
        item['channels'] = sorted(set(item.get('channels', [])))
        normalized_reasons = []
        seen_reason_prefix = set()
        for reason in item.get('reasons', []):
            if not reason:
                continue
            prefix = reason.split(':', 1)[0]
            if prefix in seen_reason_prefix:
                continue
            seen_reason_prefix.add(prefix)
            normalized_reasons.append(reason)
        item['reasons'] = normalized_reasons[:5]
        if item['channels'] == ['fts5', 'vector']:
            item['explain'] = '关键词与向量双命中'
        elif 'skill' in item['channels'] and 'vector' in item['channels']:
            item['explain'] = '技能卡与向量双命中'
        elif 'skill' in item['channels']:
            item['explain'] = '技能卡命中'
        elif 'fast-card' in item['channels']:
            item['explain'] = '知识卡命中'
        elif item['channels'] == ['fts5']:
            item['explain'] = '关键词命中'
        elif item['channels'] == ['vector']:
            item['explain'] = '向量语义命中'
        else:
            item['explain'] = '混合命中'
        if item.get('used_fallback'):
            item['explain'] = f"{item['explain']} / 宽松回退"
        if item['reasons']:
            item['explain'] = f"{item['explain']} / {'、'.join(item['reasons'][:3])}"

    dedup = []
    seen = set()
    for item in sorted(results.values(), key=lambda x: (x['score'], x.get('field_rank', 0), x.get('created_at', 0), x.get('source', ''), x.get('id', '')), reverse=True):
        summary_key = (item.get('summary') or '').strip().lower()
        if summary_key in seen:
            continue
        seen.add(summary_key)
        dedup.append(item)
        if len(dedup) >= 5:
            break

    merged = dedup
    print(json.dumps(merged, ensure_ascii=False))
conn.close()
PY
  chmod +x "$SKPL_HYBRID_MEMORY_BROKER"
}

