  start_gateway() {
    local mode="${1:-normal}" cooldown="${2:-15}" now last_restart=0

    if ! openclaw_start_gateway_allowed; then
      return 0
    fi

    if [ "$mode" != "force" ] && [ -f "$SKPL_GATEWAY_RESTART_STAMP_FILE" ]; then
      read -r last_restart < "$SKPL_GATEWAY_RESTART_STAMP_FILE" 2>/dev/null || last_restart=0
    fi

    now=$(date +%s)
    if [ "$mode" != "force" ] && [ $((now - last_restart)) -lt "$cooldown" ] && openclaw_gateway_is_running; then
      return 0
    fi

    openclaw_ensure_local_gateway_config >/dev/null 2>&1 || true
    refresh_openclaw_gateway_service >/dev/null 2>&1 || true

  if openclaw_gateway_service_active; then
      systemctl --user reset-failed openclaw-gateway.service >/dev/null 2>&1 || true
      systemctl --user restart openclaw-gateway.service >/dev/null 2>&1 || openclaw gateway restart >/dev/null 2>&1 || true
  else
      systemctl --user reset-failed openclaw-gateway.service >/dev/null 2>&1 || true
      systemctl --user start openclaw-gateway.service >/dev/null 2>&1 || openclaw gateway restart >/dev/null 2>&1 || openclaw gateway --port "$(openclaw_gateway_port)" --allow-unconfigured >/dev/null 2>&1 || openclaw_gateway_fallback_start >/dev/null 2>&1 || true
  fi
    printf '%s\n' "$now" > "$SKPL_GATEWAY_RESTART_STAMP_FILE"
    if [ "${SKPL_BATCH_MODE:-0}" != "1" ] && [ "$mode" != "nosleep" ]; then
      sleep 3
    fi
  }


  install_node_and_tools() {
    ensure_node_runtime
  }

  sync_openclaw_api_models() {
    local config_file
    config_file=$(openclaw_get_config_file)

    [ ! -f "$config_file" ] && return 0

    install jq curl >/dev/null 2>&1

    python3 - "$config_file" "$ENABLE_STATS" "$sh_v" <<'PY'
import copy
import json
import os
import platform
import sys
import time
import urllib.parse
import urllib.request
from datetime import datetime, timezone

path = sys.argv[1]
stats_enabled = (sys.argv[2].lower() == "true") if len(sys.argv) > 2 else True
script_version = sys.argv[3] if len(sys.argv) > 3 else ""

def send_stat(action):
    return

with open(path, 'r', encoding='utf-8') as f:
    obj = json.load(f)

work = copy.deepcopy(obj)
models_cfg = work.setdefault('models', {})
providers = models_cfg.get('providers', {})
if not isinstance(providers, dict) or not providers:
    print('ℹ️ 未检测到 API providers，跳过模型同步')
    raise SystemExit(0)

agents = work.setdefault('agents', {})
defaults = agents.setdefault('defaults', {})
defaults_models_raw = defaults.get('models')
if isinstance(defaults_models_raw, dict):
    defaults_models = defaults_models_raw
elif isinstance(defaults_models_raw, list):
    defaults_models = {str(x): {} for x in defaults_models_raw if isinstance(x, str)}
else:
    defaults_models = {}
defaults['models'] = defaults_models

SUPPORTED_APIS = {'openai-completions', 'openai-responses'}

changed = False
fatal_errors = []
summary = []


def model_ref(provider_name, model_id):
    return f"{provider_name}/{model_id}"


def get_primary_ref(defaults_obj):
    model_obj = defaults_obj.get('model')
    if isinstance(model_obj, str):
        return model_obj
    if isinstance(model_obj, dict):
        primary = model_obj.get('primary')
        if isinstance(primary, str):
            return primary
    return None


def set_primary_ref(defaults_obj, new_ref):
    model_obj = defaults_obj.get('model')
    if isinstance(model_obj, str):
        defaults_obj['model'] = new_ref
    elif isinstance(model_obj, dict):
        model_obj['primary'] = new_ref
    else:
        defaults_obj['model'] = {'primary': new_ref}


def ref_provider(ref):
    if not isinstance(ref, str) or '/' not in ref:
        return None
    return ref.split('/', 1)[0]


def collect_available_refs(exclude_provider=None):
    refs = []
    if not isinstance(providers, dict):
        return refs
    for pname, p in providers.items():
        if exclude_provider and pname == exclude_provider:
            continue
        if not isinstance(p, dict):
            continue
        for m in p.get('models', []) or []:
            if isinstance(m, dict) and m.get('id'):
                refs.append(model_ref(pname, str(m['id'])))
    return refs


def prompt_delete_provider(name):
    prompt = f"⚠️ {name} /models 探测连续失败 3 次。是否删除该 API 供应商及其全部相关模型？[y/N]: "
    try:
        ans = input(prompt).strip().lower()
    except EOFError:
        return False
    return ans in ('y', 'yes')


def rebind_defaults_before_delete(name):
    global changed

    replacement = None

    def get_replacement():
        nonlocal replacement
        if replacement is None:
            candidates = collect_available_refs(exclude_provider=name)
            replacement = candidates[0] if candidates else None
        return replacement

    primary_ref = get_primary_ref(defaults)
    if ref_provider(primary_ref) == name:
        repl = get_replacement()
        if not repl:
            summary.append(f'❌ {name}: 默认主模型指向该 provider，但无可用替代模型，已中止删除')
            return False
        set_primary_ref(defaults, repl)
        changed = True
        summary.append(f'🔁 删除前已切换默认主模型: {primary_ref} -> {repl}')

    for fk in ('modelFallback', 'imageModelFallback'):
        val = defaults.get(fk)
        if ref_provider(val) == name:
            repl = get_replacement()
            if not repl:
                summary.append(f'❌ {name}: {fk} 指向该 provider，但无可用替代模型，已中止删除')
                return False
            defaults[fk] = repl
            changed = True
            summary.append(f'🔁 删除前已切换 {fk}: {val} -> {repl}')

    return True


def delete_provider_and_refs(name):
    global changed

    if not rebind_defaults_before_delete(name):
        return False

    removed_refs = [r for r in list(defaults_models.keys()) if r.startswith(name + '/')]
    for r in removed_refs:
        defaults_models.pop(r, None)
    if removed_refs:
        changed = True

    if name in providers:
        providers.pop(name, None)
        changed = True

    summary.append(f'🗑️ 已删除 provider {name}，并移除 defaults.models 下 {len(removed_refs)} 个模型引用')
    return True


def fetch_remote_models_with_retry(name, base_url, api_key, retries=3):
    last_error = None
    host = (urllib.parse.urlparse(base_url).hostname or '').lower()
    domestic_rules = [
        'model-square.app.baizhi.cloud', '.baizhi.cloud', '.aliyuncs.com', '.modelscope.cn',
        '.deepseek.com', '.moonshot.cn', '.bigmodel.cn', '.siliconflow.cn', '.stepfun.com',
        '.minimax.chat', '.baichuan-ai.com', '.ppinfra.com', '.volces.com',
        '.ark.cn-beijing.volces.com', '.qianfan.baidubce.com', '.xf-yun.com',
        '.spark-api.xf-yun.com', '.hunyuan.cloud.tencent.com', '.tencentcloudapi.com'
    ]

    def is_domestic(h):
        if not h:
            return False
        for rule in domestic_rules:
            if rule.startswith('.'):
                if h.endswith(rule):
                    return True
            elif h == rule or h.endswith('.' + rule):
                return True
        return False

    for attempt in range(1, retries + 1):
        req = urllib.request.Request(
            base_url.rstrip('/') + '/models',
            headers={
                'Authorization': f'Bearer {api_key}',
                'User-Agent': 'Mozilla/5.0',
            },
        )
        try:
            if is_domestic(host):
                opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
                resp = opener.open(req, timeout=12)
            else:
                resp = urllib.request.urlopen(req, timeout=12)
            with resp:
                payload = resp.read().decode('utf-8', 'ignore')
            data = json.loads(payload)
            return data, None, attempt
        except Exception as e:
            last_error = e
            if attempt < retries:
                time.sleep(1)
    return None, last_error, retries


for name, provider in list(providers.items()):
    if not isinstance(provider, dict):
        summary.append(f'ℹ️ 跳过 {name}: provider 结构非法')
        continue

    api = provider.get('api', '')
    base_url = provider.get('baseUrl')
    api_key = provider.get('apiKey')
    model_list = provider.get('models', [])

    if not base_url or not api_key or not isinstance(model_list, list) or not model_list:
        summary.append(f'ℹ️ 跳过 {name}: 无 baseUrl/apiKey/models')
        continue

    if api not in SUPPORTED_APIS:
        summary.append(f'🔁 {name}: 发现非法协议 {api or "(unset)"}，将重新探测')
        provider['api'] = ''
        api = ''
        changed = True

    data, err, attempts = fetch_remote_models_with_retry(name, base_url, api_key, retries=3)
    if err is not None:
        summary.append(f'⚠️ {name}: /models 探测失败，已重试 {attempts} 次 ({type(err).__name__}: {err})')
        send_stat('OpenClaw API确认介入')
        if prompt_delete_provider(name):
            deleted = delete_provider_and_refs(name)
            if deleted:
                send_stat('OpenClaw API删失败Provider-确认')
                summary.append(f'✅ {name}: 用户已确认删除该 provider 及全部相关模型引用')
        else:
            send_stat('OpenClaw API删失败Provider-拒绝')
            summary.append(f'ℹ️ {name}: 用户未确认删除，保留现有 provider 配置')
        continue

    if attempts > 1:
        summary.append(f'🔁 {name}: /models 第 {attempts} 次重试后成功')

    if not (isinstance(data, dict) and isinstance(data.get('data'), list)):
        summary.append(f'⚠️ 跳过 {name}: /models 返回结构不可识别')
        continue

    remote_ids = []
    for item in data['data']:
        if isinstance(item, dict) and item.get('id'):
            remote_ids.append(str(item['id']))
    remote_set = set(remote_ids)

    if not remote_set:
        fatal_errors.append(f'❌ {name} 上游 /models 为空，无法为该 provider 提供兜底模型')
        continue

    local_models = [m for m in model_list if isinstance(m, dict) and m.get('id')]
    local_ids = [str(m['id']) for m in local_models]
    local_set = set(local_ids)

    template = None
    for m in local_models:
        template = copy.deepcopy(m)
        break
    if template is None:
        summary.append(f'⚠️ 跳过 {name}: 本地 models 无有效模板模型')
        continue

    removed_ids = [mid for mid in local_ids if mid not in remote_set]
    added_ids = [mid for mid in remote_ids if mid not in local_set]

    kept_models = [copy.deepcopy(m) for m in local_models if str(m['id']) in remote_set]
    new_models = kept_models[:]

    for mid in added_ids:
        nm = copy.deepcopy(template)
        nm['id'] = mid
        if isinstance(nm.get('name'), str):
            nm['name'] = f'{name} / {mid}'
        new_models.append(nm)

    if not new_models:
        fatal_errors.append(f'❌ {name} 同步后无可用模型，无法保障默认模型/回退模型兜底')
        continue

    expected_refs = {model_ref(name, str(m['id'])) for m in new_models if isinstance(m, dict) and m.get('id')}
    local_refs = {model_ref(name, mid) for mid in local_ids}

    first_ref = model_ref(name, str(new_models[0]['id']))

    primary_ref = get_primary_ref(defaults)
    if isinstance(primary_ref, str) and primary_ref in (local_refs - expected_refs):
        set_primary_ref(defaults, first_ref)
        changed = True
        summary.append(f'🔁 默认模型已兜底替换: {primary_ref} -> {first_ref}')

    for fk in ('modelFallback', 'imageModelFallback'):
        val = defaults.get(fk)
        if isinstance(val, str) and val in (local_refs - expected_refs):
            defaults[fk] = first_ref
            changed = True
            summary.append(f'🔁 {fk} 已兜底替换: {val} -> {first_ref}')

    stale_refs = [r for r in list(defaults_models.keys()) if r.startswith(name + '/') and r not in expected_refs]
    for r in stale_refs:
        defaults_models.pop(r, None)
        changed = True

    for r in sorted(expected_refs):
        if r not in defaults_models:
            defaults_models[r] = {}
            changed = True

    if removed_ids or added_ids or len(local_models) != len(new_models):
        provider['models'] = new_models
        changed = True

    summary.append(f'✅ {name}: 新增 {len(added_ids)} 个，删除 {len(removed_ids)} 个，当前 {len(new_models)} 个')

    if added_ids:
        summary.append(f'➕ 新增模型({len(added_ids)}):')
        for mid in added_ids:
            summary.append(f'  + {mid}')
    if removed_ids:
        summary.append(f'➖ 删除模型({len(removed_ids)}):')
        for mid in removed_ids:
            summary.append(f'  - {mid}')


if fatal_errors:
    for line in summary:
        print(line)
    for err in fatal_errors:
        print(err)
    print('❌ 模型同步失败：存在 provider 同步后无可用模型，已中止写入')
    raise SystemExit(2)

if changed:
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(work, f, ensure_ascii=False, indent=2)
        f.write('\n')
    for line in summary:
        print(line)
    print('✅ OpenClaw API 模型一致性同步完成并已写入配置')
else:
    for line in summary:
        print(line)
    print('ℹ️ 无需同步：配置已与上游 /models 保持一致')
PY
  }



  install_openclaw_panel() {
    local config_file
    echo "开始安装 OpenClaw..."
    send_stats "开始安装 OpenClaw..."
    run_openclaw_install_step || return 1
    if ! openclaw_gateway_is_running; then
      openclaw_ensure_gateway_ready || true
    fi
    config_file=$(openclaw_get_config_file)
    if [ -s "$config_file" ]; then
      echo "✅ 配置文件已就绪: $config_file"
    else
      echo "⚠️ 配置文件仍未落盘: $config_file"
    fi
    if openclaw_gateway_is_running; then
      echo "✅ OpenClaw 网关已就绪"
    else
      echo "⚠️ OpenClaw 网关暂未就绪，可在菜单中执行健康检测与修复"
    fi
    echo "提示：WebUI 在 127.0.0.1 / localhost 以外的浏览器入口通常需要一次设备审批。"
    echo "提示：WhatsApp 仍走官方扫码登录；登录命令返回后请优先执行 openclaw channels status。"
    refresh_panel_overview_cache >/dev/null 2>&1 || true
    add_app_id
    break_end

  }


  start_bot() {
    echo "启动 OpenClaw..."
    send_stats "启动 OpenClaw..."
    openclaw_ensure_gateway_ready || start_gateway
    if openclaw_gateway_is_running; then
      echo "✅ OpenClaw 网关已启动"
    else
      echo "⚠️ OpenClaw 网关状态暂未就绪"
    fi
    refresh_panel_overview_cache >/dev/null 2>&1 || true
    break_end
  }

  stop_bot() {
    echo "停止 OpenClaw..."
    send_stats "停止 OpenClaw..."
    tmux kill-session -t gateway > /dev/null 2>&1
    openclaw gateway stop >/dev/null 2>&1 || true
    refresh_panel_overview_cache >/dev/null 2>&1 || true
    echo "✅ 已执行停止操作"
    break_end
  }

  view_logs() {
    echo "查看 OpenClaw 状态日志"
    send_stats "查看 OpenClaw 日志"
    echo
    skpl_ui_section "状态摘要"
    openclaw status 2>/dev/null || true
    echo
    skpl_ui_section "网关状态"
    openclaw gateway status 2>/dev/null || true
    echo
    skpl_ui_section "最近日志"
    timeout 12 openclaw logs 2>/dev/null | python3 - <<'PY'
import sys
lines = sys.stdin.read().splitlines()
for line in lines[-80:]:
    print(line)
PY
    break_end
  }

  openclaw_latest_scope_upgrade_request_id() {
    timeout 12 openclaw logs 2>/dev/null | python3 - <<'PY'
import re
import sys

latest = ''
for line in sys.stdin.read().splitlines():
    if 'scope-upgrade' not in line and 'pending approval' not in line:
        continue
    matches = re.findall(r'\b[0-9a-fA-F]{8}-[0-9a-fA-F-]{27,}\b', line)
    if matches:
        latest = matches[-1]

if latest:
    print(latest)
PY
  }





  # OpenClaw API 协议探测逻辑已移除：不再自动探测/判定 API 类型。
  # 说明：API 类型由用户显式配置（models.providers.<name>.api），脚本不再尝试调用 /responses 做推断。

  # 构造模型配置 JSON
  build-openclaw-provider-models-json() {
    local provider_name="$1"
    local model_ids="$2"
    local models_array="["
    local first=true

    while read -r model_id; do
      [ -z "$model_id" ] && continue
      [[ $first == false ]] && models_array+=","
      first=false

      local context_window=1048576
      local max_tokens=128000
      local input_cost=0.15
      local output_cost=0.60

      case "$model_id" in
        *opus*|*pro*|*preview*|*thinking*|*sonnet*)
          input_cost=2.00
          output_cost=12.00
          ;;
        *gpt-5*|*codex*)
          input_cost=1.25
          output_cost=10.00
          ;;
        *flash*|*lite*|*haiku*|*mini*|*nano*)
          input_cost=0.10
          output_cost=0.40
          ;;
      esac

      lower=$(echo "$model_id" | tr '[:upper:]' '[:lower:]')
      models_array+=$(cat <<EOF
{
  "id": "$model_id",
  "name": "$provider_name / $model_id",
  "input": ["text", "image"],
  "contextWindow": $context_window,
  "maxTokens": $max_tokens,
  "cost": {
    "input": $input_cost,
    "output": $output_cost,
    "cacheRead": 0,
    "cacheWrite": 0
  }
}
EOF
)
    done <<< "$model_ids"

    models_array+="]"
    echo "$models_array"
  }

  # 写入 provider 与模型配置
  write-openclaw-provider-models() {
    local provider_name="$1"
    local base_url="$2"
    local api_key="$3"
    local models_array="$4"
    local config_file
    config_file=$(openclaw_get_config_file)

    # 不再自动探测/纠正 API 协议；保持用户配置为准
    DETECTED_API="openai-completions"

    [[ -f "$config_file" ]] && cp "$config_file" "${config_file}.bak.$(date +%s)"

    jq --arg prov "$provider_name" \
       --arg url "$base_url" \
       --arg key "$api_key" \
       --arg api "$DETECTED_API" \
       --argjson models "$models_array" \
    '
    .models |= (
      (. // { mode: "merge", providers: {} })
      | .mode = "merge"
      | .providers[$prov] = {
        baseUrl: $url,
        apiKey: $key,
        api: $api,
        models: $models
      }
    )
    | .agents |= (. // {})
    | .agents.defaults |= (. // {})
    | .agents.defaults.models |= (
      (if type == "object" then .
       elif type == "array" then reduce .[] as $m ({}; if ($m|type) == "string" then .[$m] = {} else . end)
       else {}
       end) as $existing
      | reduce ($models[]? | .id? // empty | tostring) as $mid (
        $existing;
        if ($mid | length) > 0 then
          .["\($prov)/\($mid)"] //= {}
        else
          .
        end
      )
    )
    ' "$config_file" > "${config_file}.tmp" && mv "${config_file}.tmp" "$config_file"
  }

  # 核心函数：获取并添加所有模型
  add-all-models-from-provider() {
    local provider_name="$1"
    local base_url="$2"
    local api_key="$3"

    echo "🔍 正在获取 $provider_name 的所有可用模型..."

    local models_json
    models_json=$(curl_fetch_models_json "$base_url" "$api_key")

    if [[ -z "$models_json" ]]; then
      echo "❌ 无法获取模型列表"
      return 1
    fi

    local model_ids=$(echo "$models_json" | grep -oP '"id":\s*"\K[^"]+')

    if [[ -z "$model_ids" ]]; then
      echo "❌ 未找到任何模型"
      return 1
    fi

    local model_count=$(echo "$model_ids" | wc -l)
    echo "✅ 发现 $model_count 个模型"

    local models_array
    models_array=$(build-openclaw-provider-models-json "$provider_name" "$model_ids")

    write-openclaw-provider-models "$provider_name" "$base_url" "$api_key" "$models_array"

    if [[ $? -eq 0 ]]; then
      echo "✅ 成功添加 $model_count 个模型到 $provider_name"
      echo "📦 模型引用格式: $provider_name/<model-id>"
      return 0
    else
      echo "❌ 配置注入失败"
      return 1
    fi
  }

  # 仅添加默认模型并保留 provider
  add-default-model-only-to-provider() {
    local provider_name="$1"
    local base_url="$2"
    local api_key="$3"
    local default_model="$4"

    if [[ -z "$default_model" ]]; then
      echo "❌ 默认模型不能为空"
      return 1
    fi

    local models_array
    models_array=$(build-openclaw-provider-models-json "$provider_name" "$default_model")

    write-openclaw-provider-models "$provider_name" "$base_url" "$api_key" "$models_array"

    if [[ $? -eq 0 ]]; then
      echo "✅ 已添加 provider：$provider_name"
      echo "✅ 仅写入默认模型：$default_model"
      return 0
    else
      echo "❌ 配置注入失败"
      return 1
    fi
  }

  add-openclaw-provider-interactive() {
    send_stats "OpenClaw API添加"
    echo "=== 交互式添加 OpenClaw Provider (全量模型) ==="

    # 1. Provider 名称
    read -erp "请输入 Provider 名称 (如: deepseek): " provider_name
    while [[ -z "$provider_name" ]]; do
      echo "❌ Provider 名称不能为空"
      read -erp "请输入 Provider 名称: " provider_name
    done

    # 2. Base URL
    read -erp "请输入 Base URL (如: https://api.xxx.com/v1): " base_url
    while [[ -z "$base_url" ]]; do
      echo "❌ Base URL 不能为空"
      read -erp "请输入 Base URL: " base_url
    done
    base_url="${base_url%/}"

    # 3. API Key
    read -rsp "请输入 API Key (输入不显示): " api_key
    echo
    while [[ -z "$api_key" ]]; do
      echo "❌ API Key 不能为空"
      read -rsp "请输入 API Key: " api_key
      echo
    done

    # 4. 不再探测/判断 API 类型；协议由用户自行选择与维护

    # 5. 获取模型列表
    echo "🔍 正在获取可用模型列表..."
    models_json=$(curl_fetch_models_json "$base_url" "$api_key")

    if [[ -n "$models_json" ]]; then
      available_models=$(echo "$models_json" | grep -oP '"id":\s*"\K[^"]+' | sort)

      if [[ -n "$available_models" ]]; then
        model_count=$(echo "$available_models" | wc -l)
        echo "✅ 发现 $model_count 个可用模型："
        echo "--------------------------------"
        # 全部显示，带序号
        i=1
        model_list=()
        while read -r model; do
          echo "[$i] $model"
          model_list+=("$model")
          ((i++))
        done <<< "$available_models"
        echo "--------------------------------"
      fi
    fi

    # 5. 选择默认模型
    echo
    read -erp "请输入默认 Model ID (或序号，留空则使用第一个): " input_model

    if [[ -z "$input_model" && -n "$available_models" ]]; then
      default_model=$(echo "$available_models" | head -1)
      echo "🎯 使用第一个模型: $default_model"
    elif [[ "$input_model" =~ ^[0-9]+$ ]] && [ "${#model_list[@]}" -gt 0 ] && [ "$input_model" -ge 1 ] && [ "$input_model" -le "${#model_list[@]}" ]; then
      default_model="${model_list[$((input_model-1))]}"
      echo "🎯 已选择模型: $default_model"
    else
      default_model="$input_model"
    fi

    # 6. 确认信息
    echo
    echo "====== 确认信息 ======"
    echo "Provider    : $provider_name"
    echo "Base URL    : $base_url"
    echo "API Key     : ****"
    echo "默认模型    : $default_model"
    echo "模型总数    : $model_count"
    echo "======================"

    read -erp "是否同时添加其他所有可用模型？(y/N): " confirm

    install jq
    if [[ "$confirm" =~ ^[Yy]$ ]]; then
      add-all-models-from-provider "$provider_name" "$base_url" "$api_key"
      add_result=$?
      finish_msg="✅ 完成！所有 $model_count 个模型已加载"
    else
      add-default-model-only-to-provider "$provider_name" "$base_url" "$api_key" "$default_model"
      add_result=$?
      finish_msg="✅ 完成！已保留 provider，并仅加载默认模型：$default_model"
    fi

    if [[ $add_result -eq 0 ]]; then
      echo
      echo "🔄 设置默认模型并重启网关..."
      openclaw models set "$provider_name/$default_model"
      openclaw_sync_sessions_model "$provider_name/$default_model"
      # 自动修复旧版 config 格式迁移 (memorySearch→agents.defaults 等)
      if openclaw_has_command openclaw; then
        echo "🔧 自动修复配置格式兼容性..."
        timeout 15 openclaw doctor --fix 2>/dev/null || true
      fi
      start_gateway
      echo "$finish_msg"
      echo "✅ 当前 API 协议类型: $DETECTED_API"
    fi

    break_end
  }



openclaw_api_manage_list() {
  local config_file
  config_file=$(openclaw_get_config_file)
  send_stats "OpenClaw API列表"

  while IFS=$'\t' read -r rec_type idx name base_url model_count api_type latency_txt latency_level; do
    case "$rec_type" in
      MSG)
        echo "$idx"
        ;;
      ROW)
        local latency_color="$gl_bai"
        case "$latency_level" in
          low) latency_color="$gl_lv" ;;
          medium) latency_color="$gl_huang" ;;
          high|unavailable) latency_color="$gl_hong" ;;
          unchecked) latency_color="$gl_bai" ;;
        esac

        printf '%b\n' "[$idx] ${name} | API: ${base_url} | 协议: ${api_type} | 模型数量: ${gl_huang}${model_count}${gl_bai} | 延迟/状态: ${latency_color}${latency_txt}${gl_bai}"
        ;;
    esac
  done < <(python3 - "$config_file" <<-'PY'
import json
import sys
import time
import urllib.request

path = sys.argv[1]
SUPPORTED_APIS = {'openai-completions', 'openai-responses'}


def ping_models(base_url, api_key):
    req = urllib.request.Request(
        base_url.rstrip('/') + '/models',
        headers={
            'Authorization': f'Bearer {api_key}',
            'User-Agent': 'OpenClaw-API-Manage/1.0',
        },
    )
    start = time.perf_counter()
    with urllib.request.urlopen(req, timeout=4) as resp:
        resp.read(2048)
    return int((time.perf_counter() - start) * 1000)


def classify_latency(latency):
    if latency == '不可用':
        return '不可用', 'unavailable'
    if latency == '未检测':
        return '未检测', 'unchecked'
    if isinstance(latency, int):
        if latency <= 800:
            level = 'low'
        elif latency <= 2000:
            level = 'medium'
        else:
            level = 'high'
        return f'{latency}ms', level
    return str(latency), 'unchecked'


try:
    with open(path, 'r', encoding='utf-8') as f:
        obj = json.load(f)
except FileNotFoundError:
    print('MSG\tℹ️ 未找到 openclaw.json，请先完成安装/初始化。')
    raise SystemExit(0)
except Exception as e:
    print(f'MSG\t❌ 读取配置失败: {type(e).__name__}: {e}')
    raise SystemExit(0)

providers = ((obj.get('models') or {}).get('providers') or {})
if not isinstance(providers, dict) or not providers:
    print('MSG\tℹ️ 当前未配置任何 API provider。')
    raise SystemExit(0)

print('MSG\t--- 已配置 API 列表 ---')

for idx, name in enumerate(sorted(providers.keys()), start=1):
    provider = providers.get(name)
    if not isinstance(provider, dict):
        base_url = '-'
        model_count = 0
        latency_raw = '不可用'
    else:
        base_url = provider.get('baseUrl') or provider.get('url') or provider.get('endpoint') or '-'
        models = provider.get('models') if isinstance(provider.get('models'), list) else []
        model_count = sum(1 for m in models if isinstance(m, dict) and m.get('id'))
        api = provider.get('api', '')
        api_key = provider.get('apiKey')

        latency_raw = '未检测'
        if api in SUPPORTED_APIS:
            if isinstance(base_url, str) and base_url != '-' and isinstance(api_key, str) and api_key:
                try:
                    latency_raw = ping_models(base_url, api_key)
                except Exception:
                    latency_raw = '不可用'
            else:
                latency_raw = '不可用'

    latency_text, latency_level = classify_latency(latency_raw)
    api_label = api if api in SUPPORTED_APIS else '-'
    print(
        'ROW\t' + '\t'.join([
            str(idx),
            str(name),
            str(base_url),
            str(model_count),
            str(api_label),
            str(latency_text),
            str(latency_level),
        ])
    )
PY
)
}
sync-openclaw-provider-interactive() {
  local config_file
  config_file=$(openclaw_get_config_file)
  send_stats "OpenClaw API按Provider同步"

  if [ ! -f "$config_file" ]; then
    echo "❌ 未找到配置文件: $config_file"
    break_end
    return 1
  fi

  read -erp "请输入要同步的 API 名称(provider)，直接回车同步全部: " provider_name
  if [ -z "$provider_name" ]; then
    if sync_openclaw_api_models; then
      start_gateway
    else
      echo "❌ API 模型同步失败，已中止重启网关。请检查 provider /models 返回后重试。"
      return 1
    fi
    break_end
    return 0
  fi

  install jq curl >/dev/null 2>&1

  python3 - "$config_file" "$provider_name" <<'PY2'
import copy
import json
import sys
import time
import urllib.parse
import urllib.request

path = sys.argv[1]
target = sys.argv[2]
SUPPORTED_APIS = {'openai-completions', 'openai-responses'}

with open(path, 'r', encoding='utf-8') as f:
    obj = json.load(f)

work = copy.deepcopy(obj)
models_cfg = work.setdefault('models', {})
providers = models_cfg.get('providers', {})
if not isinstance(providers, dict) or not providers:
    print('❌ 未检测到 API providers，无法同步')
    raise SystemExit(2)

provider = providers.get(target)
if not isinstance(provider, dict):
    print(f'❌ 未找到 provider: {target}')
    raise SystemExit(2)

agents = work.setdefault('agents', {})
defaults = agents.setdefault('defaults', {})
defaults_models_raw = defaults.get('models')
if isinstance(defaults_models_raw, dict):
    defaults_models = defaults_models_raw
elif isinstance(defaults_models_raw, list):
    defaults_models = {str(x): {} for x in defaults_models_raw if isinstance(x, str)}
else:
    defaults_models = {}
defaults['models'] = defaults_models


def model_ref(provider_name, model_id):
    return f"{provider_name}/{model_id}"


def get_primary_ref(defaults_obj):
    model_obj = defaults_obj.get('model')
    if isinstance(model_obj, str):
        return model_obj
    if isinstance(model_obj, dict):
        primary = model_obj.get('primary')
        if isinstance(primary, str):
            return primary
    return None


def set_primary_ref(defaults_obj, new_ref):
    model_obj = defaults_obj.get('model')
    if isinstance(model_obj, str):
        defaults_obj['model'] = new_ref
    elif isinstance(model_obj, dict):
        model_obj['primary'] = new_ref
    else:
        defaults_obj['model'] = {'primary': new_ref}


def fetch_remote_models_with_retry(base_url, api_key, retries=3):
    last_error = None
    host = (urllib.parse.urlparse(base_url).hostname or '').lower()
    domestic_rules = [
        'model-square.app.baizhi.cloud', '.baizhi.cloud', '.aliyuncs.com', '.modelscope.cn',
        '.deepseek.com', '.moonshot.cn', '.bigmodel.cn', '.siliconflow.cn', '.stepfun.com',
        '.minimax.chat', '.baichuan-ai.com', '.ppinfra.com', '.volces.com',
        '.ark.cn-beijing.volces.com', '.qianfan.baidubce.com', '.xf-yun.com',
        '.spark-api.xf-yun.com', '.hunyuan.cloud.tencent.com', '.tencentcloudapi.com'
    ]

    def is_domestic(h):
        if not h:
            return False
        for rule in domestic_rules:
            if rule.startswith('.'):
                if h.endswith(rule):
                    return True
            elif h == rule or h.endswith('.' + rule):
                return True
        return False

    for attempt in range(1, retries + 1):
        req = urllib.request.Request(
            base_url.rstrip('/') + '/models',
            headers={
                'Authorization': f'Bearer {api_key}',
                'User-Agent': 'Mozilla/5.0',
            },
        )
        try:
            if is_domestic(host):
                opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
                resp = opener.open(req, timeout=12)
            else:
                resp = urllib.request.urlopen(req, timeout=12)
            with resp:
                payload = resp.read().decode('utf-8', 'ignore')
            return json.loads(payload), None, attempt
        except Exception as e:
            last_error = e
            if attempt < retries:
                time.sleep(1)
    return None, last_error, retries


api = provider.get('api', '')
base_url = provider.get('baseUrl')
api_key = provider.get('apiKey')
model_list = provider.get('models', [])

if not base_url or not api_key or not isinstance(model_list, list) or not model_list:
    print(f'❌ provider {target} 缺少 baseUrl/apiKey/models，无法执行同步')
    raise SystemExit(3)

if api not in SUPPORTED_APIS:
    print(f'ℹ️ provider {target} 当前 api={api}，但脚本已不再探测/纠正协议；请手动设置为 openai-completions 或 openai-responses')

protocol_msg = None

data, err, attempts = fetch_remote_models_with_retry(base_url, api_key, retries=3)
if err is not None:
    print(f'❌ {target}: /models 探测失败，已重试 {attempts} 次 ({type(err).__name__}: {err})')
    raise SystemExit(4)

if not (isinstance(data, dict) and isinstance(data.get('data'), list)):
    print(f'❌ {target}: /models 返回结构不可识别')
    raise SystemExit(4)

remote_ids = []
for item in data['data']:
    if isinstance(item, dict) and item.get('id'):
        remote_ids.append(str(item['id']))
remote_set = set(remote_ids)
if not remote_set:
    print(f'❌ {target}: 上游 /models 为空，已中止同步')
    raise SystemExit(5)

local_models = [m for m in model_list if isinstance(m, dict) and m.get('id')]
local_ids = [str(m['id']) for m in local_models]
local_set = set(local_ids)

template = copy.deepcopy(local_models[0]) if local_models else None
if template is None:
    print(f'❌ {target}: 本地 models 无有效模板模型，无法补全新增模型')
    raise SystemExit(3)

removed_ids = [mid for mid in local_ids if mid not in remote_set]
added_ids = [mid for mid in remote_ids if mid not in local_set]

kept_models = [copy.deepcopy(m) for m in local_models if str(m['id']) in remote_set]
new_models = kept_models[:]
for mid in added_ids:
    nm = copy.deepcopy(template)
    nm['id'] = mid
    if isinstance(nm.get('name'), str):
        nm['name'] = f'{target} / {mid}'
    new_models.append(nm)

if not new_models:
    print(f'❌ {target}: 同步后无可用模型，已中止写入')
    raise SystemExit(5)

expected_refs = {model_ref(target, str(m['id'])) for m in new_models if isinstance(m, dict) and m.get('id')}
local_refs = {model_ref(target, mid) for mid in local_ids}
removed_refs = local_refs - expected_refs
first_ref = model_ref(target, str(new_models[0]['id']))

changed = False
primary_ref = get_primary_ref(defaults)
if isinstance(primary_ref, str) and primary_ref in removed_refs:
    set_primary_ref(defaults, first_ref)
    changed = True
    print(f'🔁 默认模型已兜底替换: {primary_ref} -> {first_ref}')

for fk in ('modelFallback', 'imageModelFallback'):
    val = defaults.get(fk)
    if isinstance(val, str) and val in removed_refs:
        defaults[fk] = first_ref
        changed = True
        print(f'🔁 {fk} 已兜底替换: {val} -> {first_ref}')

stale_refs = [r for r in list(defaults_models.keys()) if r.startswith(target + '/') and r not in expected_refs]
for r in stale_refs:
    defaults_models.pop(r, None)
    changed = True

for r in sorted(expected_refs):
    if r not in defaults_models:
        defaults_models[r] = {}
        changed = True

if removed_ids or added_ids or len(local_models) != len(new_models):
    provider['models'] = new_models
    changed = True


if changed:
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(work, f, ensure_ascii=False, indent=2)
        f.write('\n')

print(f'✅ {target}: 新增 {len(added_ids)} 个，删除 {len(removed_ids)} 个，当前 {len(new_models)} 个')

if added_ids:
    print(f'➕ 新增模型({len(added_ids)}):')
    for mid in added_ids:
        print(f'  + {mid}')
if removed_ids:
    print(f'➖ 删除模型({len(removed_ids)}):')
    for mid in removed_ids:
        print(f'  - {mid}')

if changed:
    print('✅ 指定 provider 模型一致性同步完成并已写入配置')
else:
    print('ℹ️ 无需同步：该 provider 配置已与上游 /models 保持一致')
PY2
  local rc=$?
  case "$rc" in
    0)
      echo "✅ 同步执行完成"
      start_gateway
      ;;
    2)
      echo "❌ 同步失败：provider 不存在或未配置"
      ;;
    3)
      echo "❌ 同步失败：provider 配置不完整或类型不支持"
      ;;
    4)
      echo "❌ 同步失败：上游 /models 请求失败"
      ;;
    5)
      echo "❌ 同步失败：上游模型为空或同步后无可用模型"
      ;;
    *)
      echo "❌ 同步失败：请检查配置文件结构或日志输出"
      ;;
  esac

  break_end
}

openclaw_detect_api_protocol_by_provider() {
  # 协议探测逻辑已移除：脚本不再自动探测/判定 API 类型。
  # 保留函数以兼容菜单调用，但不做任何改写。
  echo "ℹ️ 已关闭协议探测：请手动在 ${HOME}/.openclaw/openclaw.json 中设置 provider.api 为 openai-completions 或 openai-responses"
  return 0
}

fix-openclaw-provider-protocol-interactive() {
  local config_file
  config_file=$(openclaw_get_config_file)
  send_stats "OpenClaw API协议切换"

  if [ ! -f "$config_file" ]; then
    echo "❌ 未找到配置文件: $config_file"
    break_end
    return 1
  fi

  read -erp "请输入要切换协议的 API 名称(provider): " provider_name
  if [ -z "$provider_name" ]; then
    echo "❌ provider 名称不能为空"
    break_end
    return 1
  fi

  echo "请选择要设置的 API 类型："
  echo "1. openai-completions"
  echo "2. openai-responses"
  read -erp "请输入你的选择 (1/2): " proto_choice

  local new_api=""
  case "$proto_choice" in
    1) new_api="openai-completions" ;;
    2) new_api="openai-responses" ;;
    *)
      echo "❌ 无效选择"
      break_end
      return 1
      ;;
  esac

  install python3 >/dev/null 2>&1

  python3 - "$config_file" "$provider_name" "$new_api" <<'PY'
import copy
import json
import sys

path = sys.argv[1]
name = sys.argv[2]
new_api = sys.argv[3]

SUPPORTED_APIS = {'openai-completions', 'openai-responses'}
if new_api not in SUPPORTED_APIS:
    print('❌ 非法协议值')
    raise SystemExit(3)

with open(path, 'r', encoding='utf-8') as f:
    obj = json.load(f)

work = copy.deepcopy(obj)
providers = ((work.get('models') or {}).get('providers') or {})
if not isinstance(providers, dict) or name not in providers or not isinstance(providers.get(name), dict):
    print(f'❌ 未找到 provider: {name}')
    raise SystemExit(2)

providers[name]['api'] = new_api

with open(path, 'w', encoding='utf-8') as f:
    json.dump(work, f, ensure_ascii=False, indent=2)
    f.write('\n')

print(f'✅ 已更新 provider {name} 协议为: {new_api}')
PY
  local rc=$?
  case "$rc" in
    0)
      start_gateway
      ;;
    2)
      echo "❌ 切换失败：provider 不存在或未配置"
      ;;
    3)
      echo "❌ 切换失败：协议值非法"
      ;;
    *)
      echo "❌ 切换失败：请检查配置文件结构或日志输出"
      ;;
  esac

  break_end
}

  delete-openclaw-provider-interactive() {
    local config_file
    config_file=$(openclaw_get_config_file)
    send_stats "OpenClaw API删除入口"

    if [ ! -f "$config_file" ]; then
      echo "❌ 未找到配置文件: $config_file"
      break_end
      return 1
    fi

    read -erp "请输入要删除的 API 名称(provider): " provider_name
    if [ -z "$provider_name" ]; then
      send_stats "OpenClaw API删除取消"
      echo "❌ provider 名称不能为空"
      break_end
      return 1
    fi

    python3 - "$config_file" "$provider_name" <<'PY'
import copy
import json
import sys

path = sys.argv[1]
name = sys.argv[2]

with open(path, 'r', encoding='utf-8') as f:
    obj = json.load(f)

work = copy.deepcopy(obj)
models_cfg = work.setdefault('models', {})
providers = models_cfg.get('providers', {})
if not isinstance(providers, dict) or name not in providers:
    print(f'❌ 未找到 provider: {name}')
    raise SystemExit(2)

agents = work.setdefault('agents', {})
defaults = agents.setdefault('defaults', {})
defaults_models_raw = defaults.get('models')
if isinstance(defaults_models_raw, dict):
    defaults_models = defaults_models_raw
elif isinstance(defaults_models_raw, list):
    defaults_models = {str(x): {} for x in defaults_models_raw if isinstance(x, str)}
else:
    defaults_models = {}
defaults['models'] = defaults_models


def model_ref(provider_name, model_id):
    return f"{provider_name}/{model_id}"


def ref_provider(ref):
    if not isinstance(ref, str) or '/' not in ref:
        return None
    return ref.split('/', 1)[0]


def get_primary_ref(defaults_obj):
    model_obj = defaults_obj.get('model')
    if isinstance(model_obj, str):
        return model_obj
    if isinstance(model_obj, dict):
        primary = model_obj.get('primary')
        if isinstance(primary, str):
            return primary
    return None


def set_primary_ref(defaults_obj, new_ref):
    model_obj = defaults_obj.get('model')
    if isinstance(model_obj, str):
        defaults_obj['model'] = new_ref
    elif isinstance(model_obj, dict):
        model_obj['primary'] = new_ref
    else:
        defaults_obj['model'] = {'primary': new_ref}


def collect_available_refs(exclude_provider=None):
    refs = []
    if not isinstance(providers, dict):
        return refs
    for pname, p in providers.items():
        if exclude_provider and pname == exclude_provider:
            continue
        if not isinstance(p, dict):
            continue
        for m in p.get('models', []) or []:
            if isinstance(m, dict) and m.get('id'):
                refs.append(model_ref(pname, str(m['id'])))
    return refs


replacement_candidates = collect_available_refs(exclude_provider=name)
replacement = replacement_candidates[0] if replacement_candidates else None

primary_ref = get_primary_ref(defaults)
if ref_provider(primary_ref) == name:
    if not replacement:
        print('❌ 删除中止：默认主模型指向该 provider，且无可用替代模型')
        raise SystemExit(3)
    set_primary_ref(defaults, replacement)
    print(f'🔁 默认主模型切换: {primary_ref} -> {replacement}')

for fk in ('modelFallback', 'imageModelFallback'):
    val = defaults.get(fk)
    if ref_provider(val) == name:
        if not replacement:
            print(f'❌ 删除中止：{fk} 指向该 provider，且无可用替代模型')
            raise SystemExit(3)
        defaults[fk] = replacement
        print(f'🔁 {fk} 切换: {val} -> {replacement}')

removed_refs = [r for r in list(defaults_models.keys()) if r.startswith(name + '/')]
for r in removed_refs:
    defaults_models.pop(r, None)

providers.pop(name, None)

with open(path, 'w', encoding='utf-8') as f:
    json.dump(work, f, ensure_ascii=False, indent=2)
    f.write('\n')

print(f'🗑️ 已删除 provider: {name}')
print(f'🧹 已清理 defaults.models 中 {len(removed_refs)} 个关联模型引用')
PY
    local rc=$?
    case "$rc" in
      0)
        send_stats "OpenClaw API删除确认"
        echo "✅ 删除完成"
        start_gateway
        ;;
      2)
        echo "❌ 删除失败：provider 不存在"
        ;;
      3)
        send_stats "OpenClaw API删除取消"
        echo "❌ 删除失败：无可用替代模型，已保持原配置"
        ;;
      *)
        echo "❌ 删除失败：请检查配置文件结构或日志输出"
        ;;
    esac

    break_end
  }

