  }

  openclaw_project_backup_import() {
    send_stats "OpenClaw项目还原"
    local config_file
    config_file=$(openclaw_get_config_file)
    local openclaw_root
    openclaw_root=$(dirname "$config_file")
    mkdir -p "$openclaw_root"

    skpl_ui_header "项目还原" "高风险操作"
    skpl_ui_alert "danger" "项目还原会覆盖 OpenClaw 配置与工作区内容。" "还原前会执行 manifest/sha256 校验、白名单恢复、gateway 停启与健康检查。"
    read -e -p "请输入确认词【我已知晓高风险并继续还原】后继续: " confirm_text
    if [ "$confirm_text" != "我已知晓高风险并继续还原" ]; then
      echo "❌ 确认词不匹配，已取消还原"
      break_end
      return 1
    fi

    local archive_path
    archive_path=$(openclaw_read_import_path "请输入 OpenClaw 项目备份包路径")
    [ -z "$archive_path" ] && { echo "❌ 未输入备份路径"; break_end; return 1; }

    local tmp_unpack
    tmp_unpack=$(mktemp -d) || return 1
    local pkg_dir
    pkg_dir=$(openclaw_prepare_import_archive "openclaw-project" "$archive_path" "$tmp_unpack") || { rm -rf "$tmp_unpack"; break_end; return 1; }

    local invalid=0
    local valid_list
    valid_list=$(mktemp)
    while IFS= read -r rel; do
      [ -z "$rel" ] && continue
      if ! openclaw_is_safe_relpath "$rel" || ! openclaw_restore_path_allowed project "$rel"; then
        echo "❌ 检测到非法或越权路径: $rel"
        invalid=1
        break
      fi
      echo "$rel" >> "$valid_list"
    done < "$pkg_dir/manifest.files"

    if [ "$invalid" -ne 0 ]; then
      rm -f "$valid_list"
      rm -rf "$tmp_unpack"
      echo "❌ 还原中止：存在不安全路径"
      break_end
      return 1
    fi


    if command -v openclaw >/dev/null 2>&1; then
      echo "⏸️ 还原前停止 OpenClaw gateway..."
      openclaw gateway stop >/dev/null 2>&1 || true
    fi

    while IFS= read -r rel; do
      if [ -d "$pkg_dir/payload/$rel" ]; then
        openclaw_replace_path_from_backup "$pkg_dir/payload/$rel" "$openclaw_root/$rel"
      else
        mkdir -p "$openclaw_root/$(dirname "$rel")"
        cp -a "$pkg_dir/payload/$rel" "$openclaw_root/$rel"
      fi
    done < "$valid_list"

    if command -v openclaw >/dev/null 2>&1; then
      echo "▶️ 还原后启动 OpenClaw gateway..."
      openclaw_gateway_clear_sensitive_period
      openclaw_maybe_start_gateway nosleep 5 >/dev/null 2>&1 || true
      sleep 2
      echo "🩺 gateway 健康检查："
      if openclaw_gateway_port_reachable || openclaw_gateway_process_running || openclaw_gateway_service_active; then
        echo "gateway 已启动"
      else
        echo "gateway 状态未就绪，请稍后手动检查"
      fi
    fi

    rm -f "$valid_list"
    rm -rf "$tmp_unpack"
    echo "✅ OpenClaw 项目还原完成"
    break_end
  }

  openclaw_backup_detect_type() {
    local file_name="$1"
    if [[ "$file_name" == openclaw-bundle-full-*.tar.gz ]]; then
      echo "统一全量备份文件"
    elif [[ "$file_name" == openclaw-memory-full-*.tar.gz ]]; then
      echo "记忆备份文件"
    elif [[ "$file_name" == openclaw-project-*.tar.gz ]]; then
      echo "项目备份文件"
    else
      echo "其他备份文件"
    fi
  }

  openclaw_backup_collect_files() {
    local backup_root
    backup_root=$(openclaw_backup_root)
    mkdir -p "$backup_root"
    mapfile -t OPENCLAW_BACKUP_FILES < <(find "$backup_root" -maxdepth 1 -type f -name '*.tar.gz' -printf '%f\n' | sort -r)
  }


  openclaw_backup_render_file_list() {
    local backup_root i file_name file_path file_type file_size file_time
    local has_bundle=0 has_memory=0 has_project=0 has_other=0
    backup_root=$(openclaw_backup_root)
    openclaw_backup_collect_files

    echo "备份目录: $backup_root"
    if [ ${#OPENCLAW_BACKUP_FILES[@]} -eq 0 ]; then
      echo "暂无备份文件"
      return 0
    fi

    for i in "${!OPENCLAW_BACKUP_FILES[@]}"; do
      file_type=$(openclaw_backup_detect_type "${OPENCLAW_BACKUP_FILES[$i]}")
      case "$file_type" in
        "统一全量备份文件") has_bundle=1 ;;
        "记忆备份文件") has_memory=1 ;;
        "项目备份文件") has_project=1 ;;
        "其他备份文件") has_other=1 ;;
      esac
    done

    if [ "$has_bundle" -eq 1 ]; then
      echo "统一全量备份文件"
      for i in "${!OPENCLAW_BACKUP_FILES[@]}"; do
        file_name="${OPENCLAW_BACKUP_FILES[$i]}"
        file_type=$(openclaw_backup_detect_type "$file_name")
        [ "$file_type" != "统一全量备份文件" ] && continue
        file_path="$backup_root/$file_name"
        file_size=$(ls -lh "$file_path" | awk '{print $5}')
        file_time=$(date -d "$(stat -c %y "$file_path")" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || stat -c %y "$file_path" | awk '{print $1" "$2}')
        printf "%s | %s | %s\n" "$file_name" "$file_size" "$file_time"
      done
    fi

    if [ "$has_memory" -eq 1 ]; then
      echo "记忆备份文件"
      for i in "${!OPENCLAW_BACKUP_FILES[@]}"; do
        file_name="${OPENCLAW_BACKUP_FILES[$i]}"
        file_type=$(openclaw_backup_detect_type "$file_name")
        [ "$file_type" != "记忆备份文件" ] && continue
        file_path="$backup_root/$file_name"
        file_size=$(ls -lh "$file_path" | awk '{print $5}')
        file_time=$(date -d "$(stat -c %y "$file_path")" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || stat -c %y "$file_path" | awk '{print $1" "$2}')
        printf "%s | %s | %s\n" "$file_name" "$file_size" "$file_time"
      done
    fi

    if [ "$has_project" -eq 1 ]; then
      echo "项目备份文件"
      for i in "${!OPENCLAW_BACKUP_FILES[@]}"; do
        file_name="${OPENCLAW_BACKUP_FILES[$i]}"
        file_type=$(openclaw_backup_detect_type "$file_name")
        [ "$file_type" != "项目备份文件" ] && continue
        file_path="$backup_root/$file_name"
        file_size=$(ls -lh "$file_path" | awk '{print $5}')
        file_time=$(date -d "$(stat -c %y "$file_path")" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || stat -c %y "$file_path" | awk '{print $1" "$2}')
        printf "%s | %s | %s\n" "$file_name" "$file_size" "$file_time"
      done
    fi

    if [ "$has_other" -eq 1 ]; then
      echo "其他备份文件"
      for i in "${!OPENCLAW_BACKUP_FILES[@]}"; do
        file_name="${OPENCLAW_BACKUP_FILES[$i]}"
        file_type=$(openclaw_backup_detect_type "$file_name")
        [ "$file_type" != "其他备份文件" ] && continue
        file_path="$backup_root/$file_name"
        file_size=$(ls -lh "$file_path" | awk '{print $5}')
        file_time=$(date -d "$(stat -c %y "$file_path")" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || stat -c %y "$file_path" | awk '{print $1" "$2}')
        printf "%s | %s | %s\n" "$file_name" "$file_size" "$file_time"
      done
    fi
  }

  openclaw_backup_file_exists_in_list() {
    local target_file="$1"
    local item
    for item in "${OPENCLAW_BACKUP_FILES[@]}"; do
      [ "$item" = "$target_file" ] && return 0
    done
    return 1
  }

  openclaw_backup_delete_file() {
    send_stats "OpenClaw删除备份文件"
    local backup_root backup_root_real user_input target_file target_path target_type
    backup_root=$(openclaw_backup_root)

    openclaw_backup_render_file_list
    if [ ${#OPENCLAW_BACKUP_FILES[@]} -eq 0 ]; then
      break_end
      return 0
    fi

    read -e -p "请输入要删除的文件名或完整路径（0 取消）: " user_input
    if [ "$user_input" = "0" ]; then
      echo "已取消删除。"
      break_end
      return 0
    fi
    if [ -z "$user_input" ]; then
      echo "❌ 输入不能为空。"
      break_end
      return 1
    fi

    backup_root_real=$(realpath -m "$backup_root")
    if [[ "$user_input" == /* ]]; then
      target_path=$(realpath -m "$user_input")
      case "$target_path" in
        "$backup_root_real"/*) ;;
        *)
          echo "❌ 路径越界：仅允许删除备份根目录内的文件。"
          break_end
          return 1
          ;;
      esac
      target_file=$(basename "$target_path")
    else
      target_file=$(basename -- "$user_input")
      target_path="$backup_root/$target_file"
    fi

    if [ ! -f "$target_path" ]; then
      echo "❌ 目标文件不存在: $target_path"
      break_end
      return 1
    fi

    if ! openclaw_backup_file_exists_in_list "$target_file"; then
      echo "❌ 目标文件不在当前备份列表中。"
      break_end
      return 1
    fi

    target_type=$(openclaw_backup_detect_type "$target_file")

    skpl_ui_alert "danger" "即将删除备份文件" "[$target_type] $target_path"
    read -e -p "第一次确认：输入 yes 确认继续: " confirm_step1
    if [ "$confirm_step1" != "yes" ]; then
      echo "已取消删除。"
      break_end
      return 0
    fi
    read -e -p "二次确认：输入 DELETE 执行删除: " confirm_step2
    if [ "$confirm_step2" != "DELETE" ]; then
      echo "已取消删除。"
      break_end
      return 0
    fi

    if rm -f -- "$target_path"; then
      echo "✅ 删除成功: $target_file"
    else
      echo "❌ 删除失败: $target_file"
    fi
    break_end
  }

  openclaw_backup_list_files() {
    openclaw_backup_render_file_list
    break_end
  }

  openclaw_memory_config_file() {
    local user_config="${HOME}/.openclaw/openclaw.json"
    local root_config="/root/.openclaw/openclaw.json"
    if [ -f "$user_config" ]; then
      echo "$user_config"
    elif [ "$HOME" = "/root" ] && [ -f "$root_config" ]; then
      echo "$root_config"
    else
      echo "$user_config"
    fi
  }

  openclaw_memory_config_get() {
    local key="$1"
    local default_value="${2:-}"
    # OpenClaw 2026.6+: memorySearch under agents.defaults
    local mapped_key="$key"
    case "$mapped_key" in
      memorySearch.*) mapped_key="agents.defaults.${mapped_key}" ;;
    esac
    local value
    value=$(timeout 5 openclaw config get "$mapped_key" 2>/dev/null | head -n 1 | sed -e 's/^"//' -e 's/"$//')
    if [ -z "$value" ] || [ "$value" = "null" ] || [ "$value" = "undefined" ]; then
      echo "$default_value"
      return 0
    fi
    echo "$value"
  }

  openclaw_memory_config_set() {
    local key="$1"
    shift
    local value="$1"
    # OpenClaw 2026.6+: memorySearch under agents.defaults, tools at root level
    local mapped_key="$key"
    local config_file tmp_json
    case "$mapped_key" in
      memorySearch.*) mapped_key="agents.defaults.${mapped_key}" ;;
    esac
    if timeout 5 openclaw config set "$mapped_key" "$@" >/dev/null 2>&1; then
      return 0
    fi
    # CLI failed → Python fallback with JSON5 pre-processing
    config_file=$(openclaw_get_config_file)
    tmp_json=$(mktemp /tmp/openclaw_cfg_XXXXXX.json)
    openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null || echo '{}' > "$tmp_json"
    python3 - "$config_file" "$tmp_json" "$key" "$value" <<'PY'
import json
import sys
from pathlib import Path

out_path = Path(sys.argv[1])   # original (write target)
cfg_path = Path(sys.argv[2]) # JSON5-safe temp (read source)
key = sys.argv[3]
value = sys.argv[4]

cfg = {}
if cfg_path.exists():
    try:
        cfg = json.loads(cfg_path.read_text(encoding='utf-8'))
    except Exception:
        cfg = {}

# memorySearch goes under agents.defaults, tools stays at root
if key.startswith('memorySearch.'):
    cfg.setdefault('agents', {}).setdefault('defaults', {})
    cur = cfg['agents']['defaults']
else:
    cur = cfg

parts = key.split('.')
for part in parts[:-1]:
    node = cur.get(part)
    if not isinstance(node, dict):
        node = {}
        cur[part] = node
    cur = node

if value == 'true':
    parsed = True
elif value == 'false':
    parsed = False
else:
    parsed = value

cur[parts[-1]] = parsed
# Clean up old root-level memorySearch if present
if key.startswith('memorySearch.') and 'memorySearch' in cfg:
    del cfg['memorySearch']
out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(cfg, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
PY
    rm -f "$tmp_json"
  }

openclaw_memory_config_unset() {
  local key="$1"
  openclaw config unset "$key" >/dev/null 2>&1
}

openclaw_memory_cache_fresh() {
  local cache_file="$1"
  local ttl="${2:-10}"
  [ -f "$cache_file" ] || return 1
  python3 - "$cache_file" "$ttl" <<'PY'
import os, sys, time
path = sys.argv[1]
ttl = int(sys.argv[2])
try:
    age = time.time() - os.path.getmtime(path)
except OSError:
    raise SystemExit(1)
raise SystemExit(0 if age <= ttl else 1)
PY
}

openclaw_memory_refresh_agents_cache() {
  local agents_json config_path
  if command -v openclaw >/dev/null 2>&1; then
    agents_json=$(timeout 6 openclaw agents list --json 2>/dev/null || true)
    if [ -n "$agents_json" ]; then
      python3 - "$agents_json" "$SKPL_MEMORY_AGENTS_CACHE_FILE" <<'PY'
import json, os, sys
raw, path = sys.argv[1:3]
try:
    data = json.loads(raw)
except Exception:
    raise SystemExit(1)
seen = set()
rows = []
if isinstance(data, list):
    for item in data:
        if not isinstance(item, dict):
            continue
        aid = item.get('id')
        if not aid or aid in seen:
            continue
        ws = item.get('workspace') or ('~/.openclaw/workspace' if aid == 'main' else f'~/.openclaw/workspace-{aid}')
        rows.append(f"{aid}\t{os.path.expanduser(ws)}")
        seen.add(aid)
if rows:
    with open(path, 'w', encoding='utf-8') as f:
        f.write('\n'.join(rows) + '\n')
    raise SystemExit(0)
raise SystemExit(1)
PY
      [ $? -eq 0 ] && return 0
    fi
  fi

  config_path=$(openclaw_memory_config_file)
  python3 - "$config_path" "$SKPL_MEMORY_AGENTS_CACHE_FILE" <<'PY'
import json, os, sys
config_path, out_path = sys.argv[1:3]
results = [("main", os.path.expanduser("~/.openclaw/workspace"))]
seen = {"main"}
try:
    if os.path.exists(config_path):
        with open(config_path, encoding='utf-8') as f:
            data = json.load(f)
        agents = data.get('agents', {}).get('list', [])
        if isinstance(agents, list):
            for item in agents:
                if not isinstance(item, dict):
                    continue
                aid = item.get('id')
                ws = item.get('workspace')
                if not aid or aid in seen:
                    continue
                if not ws:
                    ws = f"~/.openclaw/workspace-{aid}"
                results.append((aid, os.path.expanduser(ws)))
                seen.add(aid)
except Exception:
    pass
with open(out_path, 'w', encoding='utf-8') as f:
    for aid, ws in results:
        f.write(f"{aid}\t{ws}\n")
PY
}

openclaw_memory_refresh_status_cache() {
  local json_output
  openclaw_memory_cli_supported || return 1
  json_output=$(timeout 8 openclaw memory status --json 2>/dev/null || true)
  if [ -z "$json_output" ]; then
    return 1
  fi
  printf '%s' "$json_output" > "$SKPL_MEMORY_STATUS_CACHE_FILE"
}

openclaw_memory_cli_supported() {
  command -v openclaw >/dev/null 2>&1 || return 1
  # 同时检查 help 提及 memory 且 memory 子命令实际可用
  timeout 8 openclaw --help 2>/dev/null | grep -qE '(^|[[:space:]])memory([[:space:]]|$)' || return 1
  timeout 8 openclaw memory --help >/dev/null 2>&1
}

openclaw_memory_refresh_runtime_state() {
  echo "正在刷新记忆状态缓存..."
  openclaw_memory_refresh_agents_cache >/dev/null 2>&1 || true
  if openclaw_memory_refresh_status_cache; then
    echo "✅ 记忆状态已刷新"
    return 0
  fi
  echo "⚠️ 记忆状态刷新失败，将尝试显示缓存或基础信息。"
  return 1
}

openclaw_memory_cleanup_legacy_keys() {
  openclaw_memory_config_unset "memory.local"
}

openclaw_memory_list_agents() {
  if ! openclaw_memory_cache_fresh "$SKPL_MEMORY_AGENTS_CACHE_FILE" 30; then
    openclaw_memory_refresh_agents_cache >/dev/null 2>&1 || true
  fi
  if [ -s "$SKPL_MEMORY_AGENTS_CACHE_FILE" ]; then
    cat "$SKPL_MEMORY_AGENTS_CACHE_FILE"
    return 0
  fi
  printf 'main\t%s\n' "$HOME/.openclaw/workspace"
}

  openclaw_memory_status_value() {
    local key="$1"
    local agent_id="${2:-}"
    openclaw_memory_cli_supported || return 1
    if [ -n "$agent_id" ]; then
      timeout 5 openclaw memory status --agent "$agent_id" 2>/dev/null | awk -F': ' -v k="$key" '$1==k {print $2; exit}'
    else
      timeout 5 openclaw memory status 2>/dev/null | awk -F': ' -v k="$key" '$1==k {print $2; exit}'
    fi
  }

  openclaw_memory_expand_path() {
    local raw_path="$1"
    if [ -z "$raw_path" ]; then
      echo ""
      return 0
    fi
    raw_path=$(echo "$raw_path" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')
    if [[ "$raw_path" == ~* ]]; then
      echo "${raw_path/#\~/$HOME}"
    else
      echo "$raw_path"
    fi
  }

  openclaw_memory_rebuild_index_single() {
    local agent_id="${1:-main}"
    local store_raw store_file ts backup_file
    if ! openclaw_memory_cli_supported; then
      echo "ℹ️ 当前 OpenClaw 版本未提供 memory CLI，跳过索引重建。"
      return 0
    fi
    store_raw=$(openclaw_memory_status_value "Store" "$agent_id")
    store_file=$(openclaw_memory_expand_path "$store_raw")
    if [ -z "$store_file" ] || [ ! -f "$store_file" ]; then
      echo "⚠️ [$agent_id] 未找到索引库文件，可能为空或不存在。"
      echo "   Store 原始值: ${store_raw:-<空>}"
      echo "   仍将执行重建索引。"
    else
      ts=$(date +%Y%m%d_%H%M%S)
      backup_file="${store_file}.bak.${ts}"
      if mv "$store_file" "$backup_file"; then
        echo "✅ [$agent_id] 已备份索引: $backup_file"
      else
        echo "⚠️ [$agent_id] 索引备份失败，继续重建。"
      fi
    fi
    timeout 120 openclaw memory index --agent "$agent_id" --force 2>/dev/null || true
  }

  openclaw_memory_rebuild_index_safe() {
    local agent_id="${1:-main}"
    openclaw_memory_rebuild_index_single "$agent_id"
    openclaw_maybe_start_gateway nosleep 5 >/dev/null 2>&1 || true
    echo "✅ 索引已重建并自动重启网关"
    echo ""
    openclaw_memory_render_status
  }

  openclaw_memory_rebuild_index_all() {
    local count=0
    local agent_lines agent_id workspace
    agent_lines=$(openclaw_memory_list_agents)
    while IFS=$'\t' read -r agent_id workspace; do
      [ -z "$agent_id" ] && continue
      openclaw_memory_rebuild_index_single "$agent_id"
      count=$((count+1))
    done <<EOF
$agent_lines
EOF
    openclaw_maybe_start_gateway nosleep 5 >/dev/null 2>&1 || true
    echo "✅ 索引已重建并自动重启网关"
    echo "✅ 已为 ${count} 个智能体重建索引"
    echo ""
    openclaw_memory_render_status
  }

  openclaw_memory_prepare_workspace() {
    local agent_id="${1:-main}"
    local workspace memory_dir memory_file
    workspace=$(openclaw_memory_status_value "Workspace" "$agent_id")
    if [ -z "$workspace" ]; then
      workspace="$HOME/.openclaw/workspace"
      [ "$agent_id" != "main" ] && workspace="$HOME/.openclaw/workspace-$agent_id"
    fi
    memory_dir="$workspace/memory"
    memory_file="$workspace/MEMORY.md"
    if [ ! -d "$memory_dir" ]; then
      echo "🔧 [$agent_id] 记忆目录不存在，已自动创建: $memory_dir"
      mkdir -p "$memory_dir"
    fi
    if [ ! -f "$memory_file" ]; then
      cat > "$memory_file" <<'EOF'
# Identity Memory

- User name: 未记录
- Assistant name: Alberton

# Notes

- 当用户明确说“记住”某件事时，优先写入这份文件。
- 当问题与用户身份、偏好、称呼相关时，先读取这份文件再回答。
- 重要身份事实应同步写入长期记忆扩展组件。
EOF
      echo "🔧 [$agent_id] 已初始化默认记忆文件: $memory_file"
    fi
    return 0
  }

  openclaw_memory_prepare_workspace_all() {
    local count=0
    local agent_lines agent_id workspace
    agent_lines=$(openclaw_memory_list_agents)
    echo "检查并准备 $(printf '%s\n' "$agent_lines" | sed '/^\s*$/d' | wc -l | tr -d ' ') 个智能体工作区"
    while IFS=$'\t' read -r agent_id workspace; do
      [ -z "$agent_id" ] && continue
      openclaw_memory_prepare_workspace "$agent_id"
      count=$((count+1))
    done <<EOF
$agent_lines
EOF
    return 0
  }

openclaw_memory_render_basic_status() {
  local backend provider model_path model_status workspace
  backend=$(openclaw_memory_get_backend)
  provider="config-only"
  model_path=$(openclaw_default_memory_model_path)
  model_status=$(openclaw_memory_local_model_status "$model_path")
  workspace="$HOME/.openclaw/workspace"
  echo "当前显示为基础配置视图（尚未刷新运行时状态）"
  if ! openclaw_memory_cli_supported; then
    echo "当前版本未提供 openclaw memory 子命令，已切换为配置态视图"
  fi
  echo "Agent: main"
  echo "  底层方案: ${backend:--}"
  echo "  搜索提供方: ${provider:--}"
  case "$model_status" in
    ok) echo "  本地模型: 已就绪" ;;
    hf) echo "  本地模型: 来自远端下载源" ;;
    *) echo "  本地模型: 未就绪" ;;
  esac
  echo "  工作区: $workspace"
}

openclaw_memory_render_status() {
  local json_output cache_note=""
  if ! openclaw_has_command openclaw; then
    openclaw_memory_render_basic_status
    return 0
  fi
  if ! openclaw_memory_cache_fresh "$SKPL_MEMORY_STATUS_CACHE_FILE" 60; then
    openclaw_memory_refresh_status_cache >/dev/null 2>&1 || true
  fi
  if ! openclaw_memory_cache_fresh "$SKPL_MEMORY_STATUS_CACHE_FILE" 60 && [ -s "$SKPL_MEMORY_STATUS_CACHE_FILE" ]; then
    cache_note="当前显示缓存状态，可手动刷新获取最新结果。"
  fi
  json_output=$(cat "$SKPL_MEMORY_STATUS_CACHE_FILE" 2>/dev/null || true)
  if [ -z "$json_output" ]; then
    openclaw_memory_render_basic_status
    return 0
  fi
  [ -n "$cache_note" ] && echo "$cache_note"
  python3 - "$json_output" <<'PY'
import json, sys
raw = sys.argv[1]
try:
    data = json.loads(raw)
except Exception:
    print("获取记忆状态失败（JSON 解析错误）")
    raise SystemExit(1)
if not isinstance(data, list) or len(data) == 0:
    print("未检测到任何智能体记忆状态。")
    raise SystemExit(0)
first = True
for entry in data:
    if not isinstance(entry, dict):
        continue
    agent_id = entry.get("agentId", "?")
    s = entry.get("status", {})
    if not isinstance(s, dict):
        s = {}
    if not first:
        print("")
    first = False
    print("Agent: %s" % agent_id)
    backend = s.get("backend") or s.get("provider") or "-"
    print("  底层方案: %s" % backend)
    files = s.get("files", 0)
    chunks = s.get("chunks", 0)
    print("  已收录: %s 文件 / %s 块" % (files, chunks))
    dirty = s.get("dirty")
    dirty_str = "是" if dirty else "否"
    print("  待刷新: %s" % dirty_str)
    vec = s.get("vector", {})
    if isinstance(vec, dict) and vec.get("enabled"):
        vec_str = "就绪" if vec.get("available") else "已启用(不可用)"
        if not vec.get("available") and files == 0 and chunks == 0:
            vec_str += "（首次安装正常，写入记忆文件后自动激活）"
    else:
        vec_str = "未启用"
    print("  向量库: %s" % vec_str)
    ws = s.get("workspaceDir") or "-"
    print("  工作区: %s" % ws)
    db = s.get("dbPath") or "-"
    print("  索引库: %s" % db)
    scan = entry.get("scan", {})
    if isinstance(scan, dict):
        issues = scan.get("issues", [])
        if issues:
            for issue in issues[:3]:
                print("  ⚠️ %s" % issue)
PY
  }

  openclaw_memory_get_backend() {
    local backend
    backend=$(openclaw_memory_config_get "memory.backend")
    if [ "$backend" = "local" ]; then
      echo "builtin"
    else
      echo "$backend"
    fi
  }

  openclaw_memory_get_local_model_path() {
    openclaw_default_memory_model_path
  }

  openclaw_memory_local_model_status() {
    local model_path="$1"
    if [ -z "$model_path" ]; then
      echo "missing"
      return
    fi
    if [[ "$model_path" == hf:* ]]; then
      echo "hf"
      return
    fi
    if [ -f "$model_path" ]; then
      echo "ok"
    else
      echo "missing"
    fi
  }

  openclaw_memory_qmd_available() {
    if command -v qmd >/dev/null 2>&1; then
      echo "true"
      return
    fi
    local backend
    backend=$(openclaw_memory_config_get "memory.backend")
    if [ "$backend" = "qmd" ]; then
      echo "true"
      return
    fi
    echo "false"
  }

  openclaw_memory_probe_url() {
    local url="$1"
    if ! command -v curl >/dev/null 2>&1; then
      echo "unknown"
      return
    fi
    if [ -z "$url" ]; then
      echo "unknown"
      return
    fi
    if curl -I -m 2 -s "$url" >/dev/null 2>&1; then
      echo "ok"
    else
      echo "fail"
    fi
  }

  openclaw_memory_recommend() {
    local qmd_ok model_path model_status hf_ok mirror_ok
    qmd_ok=$(openclaw_memory_qmd_available)
    model_path=$(openclaw_memory_get_local_model_path)
    model_status=$(openclaw_memory_local_model_status "$model_path")
    hf_ok=$(openclaw_memory_probe_url "https://huggingface.co")
    mirror_ok=$(openclaw_memory_probe_url "https://hf-mirror.com")

    OPENCLAW_MEMORY_RECOMMEND_REASON=()
    if [ "$qmd_ok" = "true" ]; then
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("QMD 可用")
    else
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("未检测到 QMD")
    fi
    if [ -n "$model_path" ]; then
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("本地模型路径: $model_path")
    else
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("未配置本地模型路径")
    fi
    case "$model_status" in
      ok) OPENCLAW_MEMORY_RECOMMEND_REASON+=("本地模型文件存在") ;;
      hf) OPENCLAW_MEMORY_RECOMMEND_REASON+=("模型来自 HF 下载源（国内可能慢/失败）") ;;
      *) OPENCLAW_MEMORY_RECOMMEND_REASON+=("本地模型文件不存在或不可用") ;;
    esac
    if [ "$hf_ok" = "ok" ]; then
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("huggingface.co 可访问")
    elif [ "$mirror_ok" = "ok" ]; then
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("hf-mirror.com 可访问")
    else
      OPENCLAW_MEMORY_RECOMMEND_REASON+=("huggingface.co / hf-mirror.com 可能不可达（疑似国内/受限网络）")
    fi

    if [ "$qmd_ok" = "true" ]; then
      if [ "$model_status" = "ok" ]; then
        OPENCLAW_MEMORY_RECOMMEND="local"
      elif [ "$model_status" = "hf" ] && { [ "$hf_ok" = "ok" ] || [ "$mirror_ok" = "ok" ]; }; then
        OPENCLAW_MEMORY_RECOMMEND="local"
      elif [ "$model_status" = "hf" ] && [ "$hf_ok" = "fail" ] && [ "$mirror_ok" = "fail" ]; then
        OPENCLAW_MEMORY_RECOMMEND="qmd"
      else
        OPENCLAW_MEMORY_RECOMMEND="qmd"
      fi
    else
      if [ "$model_status" = "ok" ]; then
        OPENCLAW_MEMORY_RECOMMEND="local"
      else
        OPENCLAW_MEMORY_RECOMMEND="qmd"
      fi
    fi
  }


  openclaw_memory_detect_region() {
    OPENCLAW_MEMORY_COUNTRY="unknown"
    OPENCLAW_MEMORY_USE_MIRROR="false"
    if command -v curl >/dev/null 2>&1; then
      OPENCLAW_MEMORY_COUNTRY=$(curl -s -m 2 ipinfo.io/country | tr -d '
' | tr -d '
')
    fi
    case "$OPENCLAW_MEMORY_COUNTRY" in
      CN|HK)
        OPENCLAW_MEMORY_USE_MIRROR="true"
        ;;
    esac
  }

  openclaw_memory_select_sources() {
    local hf_ok mirror_ok
    hf_ok=$(openclaw_memory_probe_url "https://huggingface.co")
    mirror_ok=$(openclaw_memory_probe_url "https://hf-mirror.com")
    OPENCLAW_MEMORY_HF_OK="$hf_ok"
    OPENCLAW_MEMORY_MIRROR_OK="$mirror_ok"
    if [ "$OPENCLAW_MEMORY_USE_MIRROR" = "true" ]; then
      if [ "$mirror_ok" = "ok" ]; then
        OPENCLAW_MEMORY_HF_BASE="https://hf-mirror.com"
      elif [ "$hf_ok" = "ok" ]; then
        OPENCLAW_MEMORY_HF_BASE="https://huggingface.co"
      else
        OPENCLAW_MEMORY_HF_BASE="https://hf-mirror.com"
      fi
    else
      if [ "$hf_ok" = "ok" ]; then
        OPENCLAW_MEMORY_HF_BASE="https://huggingface.co"
      elif [ "$mirror_ok" = "ok" ]; then
        OPENCLAW_MEMORY_HF_BASE="https://hf-mirror.com"
      else
        OPENCLAW_MEMORY_HF_BASE="https://huggingface.co"
      fi
    fi
  }

openclaw_memory_download_file() {
  local url="$1"
  local dest="$2"
  mkdir -p "$(dirname "$dest")"
  if command -v curl >/dev/null 2>&1; then
      local curl_proxy_opts=""
      [ -n "${HTTPS_PROXY:-${https_proxy:-}}" ] && curl_proxy_opts="--proxy ${HTTPS_PROXY:-${https_proxy:-}}"
      [ -z "$curl_proxy_opts" ] && [ -n "${HTTP_PROXY:-${http_proxy:-}}" ] && curl_proxy_opts="--proxy ${HTTP_PROXY:-${http_proxy:-}}"
      [ -z "$curl_proxy_opts" ] && [ -n "${ALL_PROXY:-${all_proxy:-}}" ] && curl_proxy_opts="--proxy ${ALL_PROXY:-${all_proxy:-}}"
      curl -L --fail --retry 2 --connect-timeout 15 --max-time 1800 $curl_proxy_opts -o "$dest" "$url"
      return $?
  fi
  if command -v wget >/dev/null 2>&1; then
      local wget_proxy_opts=""
      [ -n "${HTTPS_PROXY:-${https_proxy:-}}" ] && wget_proxy_opts="-e use_proxy=yes -e https_proxy=${HTTPS_PROXY:-${https_proxy:-}}"
      [ -z "$wget_proxy_opts" ] && [ -n "${HTTP_PROXY:-${http_proxy:-}}" ] && wget_proxy_opts="-e use_proxy=yes -e http_proxy=${HTTP_PROXY:-${http_proxy:-}}"
      [ -z "$wget_proxy_opts" ] && [ -n "${ALL_PROXY:-${all_proxy:-}}" ] && wget_proxy_opts="-e use_proxy=yes -e https_proxy=${ALL_PROXY:-${all_proxy:-}}"
      wget --timeout=15 $wget_proxy_opts -O "$dest" "$url"
      return $?
  fi
    echo "❌ 未检测到 curl 或 wget，无法下载。"
    return 1
  }

  openclaw_memory_check_sqlite() {
    if ! command -v sqlite3 >/dev/null 2>&1; then
      echo "⚠️ 未检测到 sqlite3，QMD 可能无法正常运行。"
      return 1
    fi
    local ver
    ver=$(sqlite3 --version 2>/dev/null | awk '{print $1}')
    echo "✅ sqlite3 可用: ${ver:-unknown}"
    echo "ℹ️ sqlite 扩展支持无法可靠检测，将继续。"
    return 0
  }

  openclaw_memory_ensure_bun() {
    if [ -x "$HOME/.bun/bin/bun" ]; then
      export PATH="$HOME/.bun/bin:$PATH"
    fi
    if command -v bun >/dev/null 2>&1; then
      echo "✅ bun 已存在"
      return 0
    fi
    echo "⬇️ 安装 bun..."
    if command -v curl >/dev/null 2>&1; then
      curl -fsSL https://bun.sh/install | bash
    elif command -v wget >/dev/null 2>&1; then
      wget -qO- https://bun.sh/install | bash
    else
      echo "❌ 未检测到 curl 或 wget，无法安装 bun。"
      return 1
    fi
    if [ -d "$HOME/.bun/bin" ]; then
      export PATH="$HOME/.bun/bin:$PATH"
    fi
    if command -v bun >/dev/null 2>&1; then
      echo "✅ bun 安装完成"
      return 0
    fi
    echo "❌ bun 安装失败"
    return 1
  }

  openclaw_memory_ensure_qmd() {
    local qmd_path
    qmd_path=$(command -v qmd 2>/dev/null || true)
    if [ -n "$qmd_path" ]; then
      if qmd --version >/dev/null 2>&1; then
        echo "✅ qmd 已存在且可用: $qmd_path"
        OPENCLAW_MEMORY_QMD_PATH="$qmd_path"
        return 0
      else
        echo "⚠️ qmd 命令存在但模块损坏，重新安装..."
      fi
    fi
    echo "⬇️ 通过 npm 安装 qmd: @tobilu/qmd"
    npm install -g @tobilu/qmd
    qmd_path=$(command -v qmd 2>/dev/null || true)
    if [ -z "$qmd_path" ]; then
      echo "❌ qmd 安装失败"
      return 1
    fi
    if ! qmd --version >/dev/null 2>&1; then
      echo "❌ qmd 安装后仍无法运行"
      return 1
    fi
    OPENCLAW_MEMORY_QMD_PATH="$qmd_path"
    echo "✅ qmd 安装完成: $qmd_path"
    return 0
  }

  openclaw_memory_render_auto_summary() {
    skpl_ui_rule "$gl_hui" "─" 60
    echo "✅ 环境就绪"
    echo "方案: ${OPENCLAW_MEMORY_AUTO_SCHEME:-unknown}"
    if [ "$OPENCLAW_MEMORY_CONFIG_ONLY" = "true" ]; then
      echo "模式: 仅写配置（未安装/未下载）"
    fi
    if [ "$OPENCLAW_MEMORY_PREHEAT" = "true" ]; then
      echo "索引: 已执行"
    else
      echo "索引: 已跳过"
    fi
    if [ "$OPENCLAW_MEMORY_RESTARTED" = "true" ]; then
      echo "重启: 已执行"
    else
      echo "重启: 已跳过"
    fi
    if [ -n "$OPENCLAW_MEMORY_QMD_PATH" ]; then
      echo "qmd: $OPENCLAW_MEMORY_QMD_PATH"
    fi
    if [ -n "$OPENCLAW_MEMORY_MODEL_PATH" ]; then
      echo "模型: $OPENCLAW_MEMORY_MODEL_PATH"
    fi
    if [ -n "$OPENCLAW_MEMORY_COUNTRY" ]; then
      echo "地区: $OPENCLAW_MEMORY_COUNTRY"
    fi
    if [ -n "$OPENCLAW_MEMORY_HF_BASE" ]; then
      echo "下载源: $OPENCLAW_MEMORY_HF_BASE"
    fi
    echo "最终状态:"
    openclaw_memory_render_status
    skpl_ui_rule "$gl_hui" "─" 60
  }

  openclaw_memory_auto_confirm() {
    local scheme_label="$1"
    OPENCLAW_MEMORY_PREHEAT="true"
    OPENCLAW_MEMORY_RESTARTED="false"
    OPENCLAW_MEMORY_CONFIG_ONLY="false"
    echo "即将执行自动部署（详细模式）"
    echo "目标方案: $scheme_label"
    echo "地区: ${OPENCLAW_MEMORY_COUNTRY:-unknown}"
    echo "镜像源探测: huggingface.co=${OPENCLAW_MEMORY_HF_OK:-unknown} hf-mirror.com=${OPENCLAW_MEMORY_MIRROR_OK:-unknown}"
    echo "下载源: ${OPENCLAW_MEMORY_HF_BASE:-unknown}"
    if [ -n "$OPENCLAW_MEMORY_EXPECT_PATH" ]; then
      echo "预计下载路径: $OPENCLAW_MEMORY_EXPECT_PATH"
    fi
    if [ -n "$OPENCLAW_MEMORY_EXPECT_SIZE" ]; then
      echo "可能流量/磁盘占用: $OPENCLAW_MEMORY_EXPECT_SIZE"
    else
      echo "可能流量/磁盘占用: 视实际情况而定"
    fi
    echo "确认后将自动安装/下载、写入配置、构建索引并重启网关"
    echo "高级选项: 输入 config 仅写配置（不安装不下载、不索引、不重启）"
    read -e -p "输入 yes 确认继续（默认 N）: " confirm_step
    case "$confirm_step" in
      yes|YES)
        OPENCLAW_MEMORY_PREHEAT="true"
        ;;
      config|CONFIG)
        OPENCLAW_MEMORY_CONFIG_ONLY="true"
        OPENCLAW_MEMORY_PREHEAT="false"
        ;;
      *)
        echo "已取消自动部署。"
        return 1
        ;;
    esac
    if [ "$OPENCLAW_MEMORY_CONFIG_ONLY" = "true" ]; then
      echo "⚠️ 已选择仅写配置，不安装不下载"
    else
      echo "✅ 将自动构建索引并重启网关"
    fi
    return 0
  }

  openclaw_memory_auto_setup_qmd() {
    echo "🔍 检测 QMD 环境"
    openclaw_memory_cleanup_legacy_keys
    openclaw_memory_check_sqlite || true
    if [ "$OPENCLAW_MEMORY_CONFIG_ONLY" = "true" ]; then
      if command -v qmd >/dev/null 2>&1; then
        OPENCLAW_MEMORY_QMD_PATH=$(command -v qmd)
      else
        OPENCLAW_MEMORY_QMD_PATH="qmd"
      fi
    else
      openclaw_memory_ensure_qmd || return 1
    fi
    local backend
    backend=$(openclaw_memory_get_backend)
    if [ "$backend" = "qmd" ]; then
      echo "✅ memory.backend 已是 qmd"
    else
      openclaw_memory_config_set "memory.backend" "qmd"
      echo "✅ 已设置 memory.backend=qmd"
    fi
    local qmd_cmd
    qmd_cmd=$(openclaw_memory_config_get "memory.qmd.command")
    if [ -z "$qmd_cmd" ] || [[ "$qmd_cmd" != /* ]] || [ "$qmd_cmd" != "$OPENCLAW_MEMORY_QMD_PATH" ]; then
      openclaw_memory_config_set "memory.qmd.command" "$OPENCLAW_MEMORY_QMD_PATH"
      echo "✅ 已写入 memory.qmd.command: $OPENCLAW_MEMORY_QMD_PATH"
    else
      echo "✅ memory.qmd.command 已正确"
    fi
    if [ "$OPENCLAW_MEMORY_PREHEAT" = "true" ]; then
      echo "🔥 预热索引（可能下载模型）"
      openclaw_memory_prepare_workspace_all
      local preh_agent_lines preh_agent_id preh_workspace
      preh_agent_lines=$(openclaw_memory_list_agents)
      while IFS=$'\t' read -r preh_agent_id preh_workspace; do
        [ -z "$preh_agent_id" ] && continue
        timeout 120 openclaw memory index --agent "$preh_agent_id" --force 2>/dev/null || true
      done <<EOF
$preh_agent_lines
EOF
    else
      echo "⏭️ 已跳过预热"
    fi
    echo "✅ QMD 自动部署完成"
  }

openclaw_memory_auto_setup_local() {
    echo "🔍 检测 Local 环境"
    # 记忆检索依赖本地 Ollama 做 embedding，即使主模型是云端也必须安装
    openclaw_install_ollama_runtime || return 1
    openclaw_memory_cleanup_legacy_keys
    openclaw_safe_enable_global_tools
    openclaw_memory_prepare_workspace_all
    local backend
    backend=$(openclaw_memory_get_backend)
    if [ "$backend" = "builtin" ] || [ "$backend" = "local" ]; then
      echo "✅ memory.backend 已是 builtin"
    else
      openclaw_memory_config_set "memory.backend" "builtin"
      echo "✅ 已设置 memory.backend=builtin"
    fi
    echo "   正在检查记忆搜索配置..."
    openclaw_memory_config_set "memorySearch.provider" "ollama"
    echo "✅ 已设置 memorySearch.provider=ollama"
    echo "   正在读取记忆模型配置..."
    local memory_ollama_model
    memory_ollama_model=$(openclaw_memory_config_get "memorySearch.model")
    if [ -z "$memory_ollama_model" ]; then
      memory_ollama_model="qwen2.5:7b"
      openclaw_memory_config_set "memorySearch.model" "$memory_ollama_model"
      echo "✅ 已设置 memorySearch.model=$memory_ollama_model"
    else
      echo "✅ memorySearch.model 已存在: $memory_ollama_model"
    fi

    local model_path model_status
    model_path=$(openclaw_memory_get_local_model_path)
    model_path=$(openclaw_memory_expand_path "$model_path")
    model_status=$(openclaw_memory_local_model_status "$model_path")
    if [ "$model_status" = "ok" ]; then
      echo "✅ 模型文件已存在: $model_path"
      OPENCLAW_MEMORY_MODEL_PATH="$model_path"
    else
      local model_name="embeddinggemma-300M-Q8_0.gguf"
      local model_dir="$HOME/.openclaw/models/embedding"
      local model_dest="$model_dir/$model_name"
      local model_url="${OPENCLAW_MEMORY_HF_BASE}/ggml-org/embeddinggemma-300M-GGUF/resolve/main/$model_name"
      if [ "$OPENCLAW_MEMORY_CONFIG_ONLY" = "true" ]; then
        echo "ℹ️ 仅写配置模式：跳过模型下载"
        OPENCLAW_MEMORY_MODEL_PATH="$model_dest"
      else
        if [ -f "$model_dest" ]; then
          echo "✅ 已发现默认模型文件: $model_dest"
        else
          echo "⬇️ 下载模型: $model_url"
          echo "   模型大小约 300MB，根据网络情况可能需要几分钟..."
          openclaw_memory_download_file "$model_url" "$model_dest" || return 1
          echo "✅ 模型已下载: $model_dest"
        fi
        OPENCLAW_MEMORY_MODEL_PATH="$model_dest"
      fi
      echo "✅ 已发现默认模型文件: $model_dest"
    fi
    if [ "$OPENCLAW_MEMORY_PREHEAT" = "true" ]; then
      echo "🔥 预热索引（可能下载模型）"
      echo "   此步骤可能需要几分钟，请耐心等待..."
      openclaw_memory_prepare_workspace_all
      local preh_agent_lines preh_agent_id preh_workspace
      preh_agent_lines=$(openclaw_memory_list_agents)
      while IFS=$'\t' read -r preh_agent_id preh_workspace; do
        [ -z "$preh_agent_id" ] && continue
        echo "🧱 正在预热索引: $preh_agent_id (最多10分钟)..."
        timeout 600 openclaw memory index --agent "$preh_agent_id" --force 2>/dev/null || {
          echo "⚠️ 索引预热超时或失败: $preh_agent_id"
          return 1
        }
      done <<EOF
$preh_agent_lines
EOF
    else
      echo "⏭️ 已跳过预热"
    fi
    openclaw_validate_global_tools_runtime
    echo "✅ Local 自动部署完成"
  }

  openclaw_memory_auto_setup_run() {
    local scheme="$1"
    local scheme_label
    OPENCLAW_MEMORY_QMD_PATH=""
    OPENCLAW_MEMORY_MODEL_PATH=""
    OPENCLAW_MEMORY_EXPECT_PATH=""
    OPENCLAW_MEMORY_EXPECT_SIZE=""
    openclaw_memory_detect_region
    openclaw_memory_select_sources
    if [ "$scheme" = "auto" ]; then
      openclaw_memory_recommend
      scheme="$OPENCLAW_MEMORY_RECOMMEND"
    fi
    case "$scheme" in
      qmd)
        scheme_label="QMD"
        OPENCLAW_MEMORY_EXPECT_PATH="$HOME/.bun (qmd 安装目录)"
        OPENCLAW_MEMORY_EXPECT_SIZE="约 20-50MB"
        ;;
      local)
        scheme_label="Local"
        OPENCLAW_MEMORY_EXPECT_PATH="$HOME/.openclaw/models/embedding/embeddinggemma-300M-Q8_0.gguf"
        OPENCLAW_MEMORY_EXPECT_SIZE="约 350-600MB"
        ;;
      *)
        echo "❌ 未知方案: $scheme"
        return 1
        ;;
    esac
    OPENCLAW_MEMORY_AUTO_SCHEME="$scheme_label"
    openclaw_memory_auto_confirm "$scheme_label" || return 0
    case "$scheme" in
      qmd) openclaw_memory_auto_setup_qmd || return 1 ;;
      local) openclaw_memory_auto_setup_local || return 1 ;;
      *) return 1 ;;
    esac
    if [ "$OPENCLAW_MEMORY_CONFIG_ONLY" = "true" ]; then
      OPENCLAW_MEMORY_RESTARTED="false"
      openclaw_memory_render_auto_summary
      return 0
    fi
    echo "♻️ 重启 OpenClaw 网关"
    if declare -F start_gateway >/dev/null 2>&1; then
      start_gateway nosleep 5
    else
      openclaw gateway restart
    fi
    OPENCLAW_MEMORY_RESTARTED="true"
    openclaw_memory_render_auto_summary
    return 0
  }

  openclaw_memory_auto_setup_menu() {
    while true; do
      clear
      skpl_ui_header "记忆方案自动部署" "根据所选方案完成配置与依赖准备"
      skpl_ui_section "操作"
      skpl_ui_menu_item 1 "QMD" "轻量索引方案"
      skpl_ui_menu_item 2 "Local" "本地向量检索方案"
      skpl_ui_menu_item 3 "Auto" "自动选择推荐方案"
      skpl_ui_menu_item 4 "四层方案" "一键启用 官方文件记忆 + LanceDB + EvoMap + MemOS/EvoMap"
      skpl_ui_menu_item 5 "Local Q4_K_M" "本地量化 embedding 模型方案"
      skpl_ui_menu_item 0 "返回上一级"
      skpl_ui_footer_prompt "请输入你的选择: "
      read -e auto_choice
      case "$auto_choice" in
        1)
          openclaw_memory_auto_setup_run "qmd"
          break_end
          ;;
        2)
          openclaw_memory_auto_setup_run "local"
          break_end
          ;;
        3)
          openclaw_memory_auto_setup_run "auto"
          break_end
          ;;
        4)
          openclaw_memory_enable_four_layer_stack
          break_end
          ;;
        5)
          openclaw_memory_detect_region
          openclaw_memory_select_sources
          OPENCLAW_MEMORY_CONFIG_ONLY="false"
          OPENCLAW_MEMORY_PREHEAT="true"
          openclaw_memory_apply_local_q4km_model
          openclaw_maybe_start_gateway nosleep 5 >/dev/null 2>&1 || true
          break_end
          ;;
        0)
          return 0
          ;;
        *)
          echo "无效的选择，请重试。"
          sleep 1
          ;;
      esac
    done
  }

  openclaw_memory_apply_scheme() {
    local scheme="$1"
    openclaw_memory_cleanup_legacy_keys
    case "$scheme" in
      qmd)
        openclaw_memory_config_set "memory.backend" "qmd"
        if [ $? -ne 0 ]; then
          echo "❌ 写入配置失败"
          return 1
        fi
        openclaw_memory_config_set "memory.qmd.command" "qmd" >/dev/null 2>&1
        ;;
      local)
        openclaw_memory_config_set "memory.backend" "builtin"
        if [ $? -ne 0 ]; then
          echo "❌ 写入配置失败"
          return 1
        fi
        ;;
      *)
        echo "❌ 未知方案: $scheme"
        return 1
      esac
    echo "✅ 已更新记忆方案配置"
    return 0
  }

  openclaw_memory_offer_restart() {
    echo "配置已写入，需要重启 OpenClaw 网关后生效。"
    read -e -p "是否立即重启 OpenClaw 网关？(Y/n): " restart_choice
    if [[ "$restart_choice" =~ ^[Nn]$ ]]; then
      echo "已跳过重启，可稍后执行: openclaw gateway restart"
      return 0
    fi
    if declare -F start_gateway >/dev/null 2>&1; then
      start_gateway nosleep 5
    else
      openclaw gateway restart
    fi
  }

openclaw_memory_fix_index() {
    local backend include_dm
    backend=$(openclaw_memory_get_backend)
    if [ "$backend" = "qmd" ] && ! command -v qmd >/dev/null 2>&1; then
      echo "⚠️ 检测到当前方案为 QMD，但未安装 qmd 命令。"
      echo "   可切换 Local，或安装 bun + qmd 后再试。"
    fi
    include_dm=$(timeout 5 openclaw config get memory.qmd.includeDefaultMemory 2>/dev/null)
    skpl_ui_header "索引修复诊断" "检查 includeDefaultMemory 与索引重建路径"
    skpl_ui_kv "includeDefaultMemory" "${include_dm:-未设置}"
    echo ""
    if [ "$include_dm" = "false" ]; then
      echo "⚠️ 检测到 includeDefaultMemory=false"
      echo "   这会导致默认记忆文件（MEMORY.md + memory/*.md）不被索引"
      echo "   所以 Indexed 会一直显示 0/N"
      echo ""
      read -e -p "是否恢复为 true 并重建索引？(Y/n): " fix_choice
      if [[ ! "$fix_choice" =~ ^[Nn]$ ]]; then
        openclaw_memory_config_set "memory.qmd.includeDefaultMemory" true
        if [ $? -ne 0 ]; then
          echo "❌ 写入配置失败"
          break_end
          return 1
        fi
        echo "✅ 已恢复 includeDefaultMemory=true"
        openclaw_memory_rebuild_index_all
      else
        echo "已取消。"
      fi
    else
      echo "includeDefaultMemory 配置正常。"
      echo "将执行：清理旧索引 → 全量重建所有智能体索引"
      echo ""
      read -e -p "确认执行？(Y/n): " confirm_fix
      if [[ ! "$confirm_fix" =~ ^[Nn]$ ]]; then
        openclaw_memory_rebuild_index_all
      else
        echo "已取消。"
      fi
    fi
    break_end
  }

  openclaw_memory_legacy_compat_menu() {
    local recommended_scheme recommended_reason qmd_ok model_path model_status hf_ok mirror_ok
    while true; do
      clear
      openclaw_memory_detect_region
      openclaw_memory_select_sources
      openclaw_memory_recommend
      recommended_scheme="${OPENCLAW_MEMORY_RECOMMEND:-local}"
      qmd_ok=$(openclaw_memory_qmd_available)
      model_path=$(openclaw_memory_get_local_model_path)
      model_status=$(openclaw_memory_local_model_status "$model_path")
      hf_ok="${OPENCLAW_MEMORY_HF_OK:-unknown}"
      mirror_ok="${OPENCLAW_MEMORY_MIRROR_OK:-unknown}"
      recommended_reason=$(printf '%s；' "${OPENCLAW_MEMORY_RECOMMEND_REASON[@]}")
      recommended_reason="${recommended_reason%？}"
      recommended_reason="${recommended_reason%;}"

      skpl_ui_header "兼容增强工具" "保留旧记忆方案里的实用诊断与降级能力，不改变当前新方案默认运行链"
      skpl_ui_kv "当前推荐" "$recommended_scheme"
      skpl_ui_kv "QMD 可用" "$qmd_ok"
      skpl_ui_kv "本地模型" "${model_path:-未配置}"
      skpl_ui_kv "模型状态" "$model_status"
      skpl_ui_kv "HF 可达" "$hf_ok"
      skpl_ui_kv "镜像可达" "$mirror_ok"
      echo "推荐依据: ${recommended_reason:-未生成}"
      echo
      skpl_ui_section "操作"
      skpl_ui_menu_item 1 "自动选择兼容方案" "只在当前环境更适合时，调用旧方案的自动推荐与部署逻辑"
      skpl_ui_menu_item 2 "QMD 轻量兼容" "低资源或下载受限时，启用 QMD 轻量索引链路"
      skpl_ui_menu_item 3 "本地检索兼容" "调用旧方案的本地 embedding 自动部署逻辑"
      skpl_ui_menu_item 4 "索引修复诊断" "修复 includeDefaultMemory 和旧索引状态"
      skpl_ui_menu_item 5 "来源与网络诊断" "检查 HF 与镜像可达性，辅助判断下载路径"
      skpl_ui_menu_item 0 "返回上一级"
      skpl_ui_footer_prompt "请输入你的选择: "
      read -e legacy_choice
      case "$legacy_choice" in
        1) OPENCLAW_MEMORY_CONFIG_ONLY="false" openclaw_memory_auto_setup_run "auto"; break_end ;;
        2) OPENCLAW_MEMORY_CONFIG_ONLY="false" openclaw_memory_auto_setup_run "qmd"; break_end ;;
        3) OPENCLAW_MEMORY_CONFIG_ONLY="false" OPENCLAW_MEMORY_PREHEAT="${OPENCLAW_MEMORY_PREHEAT:-false}" openclaw_memory_auto_setup_run "local"; break_end ;;
        4) openclaw_memory_fix_index ;;
        5)
          echo "地区: ${OPENCLAW_MEMORY_COUNTRY:-unknown}"
          echo "当前下载源: ${OPENCLAW_MEMORY_HF_BASE:-unknown}"
          echo "huggingface.co: $hf_ok"
          echo "hf-mirror.com: $mirror_ok"
          break_end
          ;;
        0) return 0 ;;
        *) echo "无效的选择，请重试。"; sleep 1 ;;
      esac
    done
  }

  # ==========================================
# 🌌 OpenClaw 智能模型与能力路由 (Smart Router)
# ==========================================

# 管理 OpenClaw 模型配置，实现真正的按需分配
openclaw_model_manager() {
    local config_file
    config_file=$(openclaw_get_config_file)
    mkdir -p "$(dirname "$config_file")"
    [ ! -f "$config_file" ] && echo '{}' > "$config_file"

    openclaw_runtime_self_heal || true

    while true; do
        clear
        skpl_ui_header "智能模型管理器" "按任务类型分配最佳模型，极致省 Token"
        echo
        python3 - "$config_file" <<'PY'
import json, sys
from pathlib import Path

path = Path(sys.argv[1])
if not path.exists(): path.write_text('{}', encoding='utf-8')
cfg = json.loads(path.read_text(encoding='utf-8'))

agents = cfg.get('agents', {}).get('defaults', {})
primary = agents.get('model', {}).get('primary', '未配置')
image_primary = agents.get('imageModel', {}).get('primary', '未配置') if isinstance(agents.get('imageModel'), dict) else agents.get('imageModel', '未配置')
models = list(agents.get('models', {}).keys())

print(f"🧠 当前主模型 (日常/文本): {primary}")
print(f"👁️ 当前视觉模型: {image_primary}")
print(f"📂 已添加模型列表: {len(models)} 个")
for m in models:
    print(f"   - {m}")
PY
        openclaw_ollama_status
        echo
        skpl_ui_section "操作 (直接写入 OpenClaw 核心配置)"
        skpl_ui_menu_item 1 "设置文本模型" "日常对话/轻量任务 (推荐 Gemini-Flash/Claude-Haiku)"
        skpl_ui_menu_item 2 "设置视觉模型" "图片识别/多模态任务 (推荐 Gemini/GPT-4o)"
        skpl_ui_menu_item 3 "设置代码模型" "开发/复杂逻辑 (推荐 Claude-Opus/o1)"
        skpl_ui_menu_item 4 "设置自定义模型" "其他备用 API"
        skpl_ui_menu_item 5 "本地模型运行时" "安装 ollama 并拉取本地文本/代码模型"
        skpl_ui_menu_item 6 "一键推荐配置" "写入推荐的文本/视觉/代码模型组合"
        skpl_ui_menu_item 7 "安装后验收检查" "检查 openclaw、gateway、ollama、记忆索引状态"
        skpl_ui_menu_item 8 "一键完整本地落地" "安装 ollama、拉取推荐模型、启用本地检索并执行验收"
        skpl_ui_menu_item 9 "一键应用并重启" "保存配置并让 AI 立即生效"
        skpl_ui_menu_item 0 "返回上一级"
        skpl_ui_footer_prompt "请选择: "
        read -e model_choice
        
        case "$model_choice" in
            1) openclaw_set_model_slot "text" $config_file ;;
            2) openclaw_set_model_slot "image" $config_file ;;
            3) openclaw_set_model_slot "code" $config_file ;;
            4) openclaw_set_model_slot "custom" $config_file ;;
            5)
                openclaw_ollama_quick_setup_menu
                ;;
            6)
                openclaw_apply_recommended_model_profile
                break_end
                ;;
            7)
                openclaw_postinstall_acceptance_check
                break_end
                ;;
            8)
                openclaw_full_local_stack_setup
                break_end
                ;;
            9)
                openclaw_apply_and_restart
                break_end
                ;;
            0) return 0 ;;
        esac
    done
}

openclaw_set_model_slot() {
    local type="$1" config_file="$2"
    local model_name normalized_model provider_model tmp_json
    read -e -p "请输入 [$type] 模型 ID (格式: 提供商/模型名): " model_name
    [ -z "$model_name" ] && return 0

    normalized_model=$(python3 - "$model_name" <<'PY'
import sys

value = sys.argv[1].strip()
if ' (' in value and value.endswith(')'):
    value = value.split(' (', 1)[0].strip()
if '/' not in value and ':' in value and ' ' not in value:
    value = f'ollama/{value}'
print(value)
PY
)

    if [ -z "$normalized_model" ]; then
      echo "❌ 模型 ID 不能为空。"
      read -n 1 -s -r -p "按任意键继续..."
      return 1
    fi

    if [[ "$normalized_model" == ollama/* ]]; then
      provider_model="${normalized_model#ollama/}"
      openclaw_configure_local_ollama_provider "$provider_model" "$type" >/dev/null 2>&1 || {
        echo "❌ 本地 Ollama 模型配置写入失败: $normalized_model"
        read -n 1 -s -r -p "按任意键继续..."
        return 1
      }
    fi

    # JSON5 safe: pre-process config to temp JSON
    tmp_json=$(mktemp /tmp/openclaw_cfg_XXXXXX.json)
    openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null || echo '{}' > "$tmp_json"
    python3 - "$config_file" "$tmp_json" "$type" "$normalized_model" <<'PY'
import json, sys
from pathlib import Path

out_path = Path(sys.argv[1])   # original (write target)
cfg_path = Path(sys.argv[2]) # JSON5-safe temp (read source)
cfg_type = sys.argv[3]
model = sys.argv[4]
cfg = {}
if cfg_path.exists() and cfg_path.stat().st_size > 0:
    try:
        cfg = json.loads(cfg_path.read_text(encoding='utf-8'))
        if not isinstance(cfg, dict):
            cfg = {}
    except Exception:
        cfg = {}

# 初始化结构
if 'agents' not in cfg: cfg['agents'] = {}
if 'defaults' not in cfg['agents']: cfg['agents']['defaults'] = {}
if 'model' not in cfg['agents']['defaults']: cfg['agents']['defaults']['model'] = {}
models_obj = cfg['agents']['defaults'].get('models')
if not isinstance(models_obj, dict):
    if isinstance(models_obj, list):
        models_obj = {str(item): {} for item in models_obj if isinstance(item, str) and item.strip()}
    else:
        models_obj = {}
    cfg['agents']['defaults']['models'] = models_obj

# 添加模型到列表
cfg['agents']['defaults']['models'][model] = {}

# 设置对应类型
if cfg_type == 'text':
    cfg['agents']['defaults']['model']['primary'] = model
elif cfg_type == 'code':
    cfg['agents']['defaults']['models'].setdefault(model, {})['agentRuntime'] = {'id': 'auto'}
elif cfg_type == 'image':
    cfg['agents']['defaults']['imageModel'] = {'primary': model}
elif cfg_type == 'custom':
    cfg['agents']['defaults']['models'][model].setdefault('alias', 'custom')

out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(f"✅ 已将 {cfg_type} 模型设为: {model}")
PY
    rm -f "$tmp_json"
    read -n 1 -s -r -p "按任意键继续..."
}

openclaw_apply_and_restart() {
    echo "💾 正在保存配置并重启 OpenClaw..."
    openclaw_optimize_memory_and_skills || echo "⚠️ 配置优化跳过（非致命）"
    # 写入完成后先做配置验证
    if command -v openclaw >/dev/null 2>&1; then
      local validate_out
      validate_out=$(timeout 10 openclaw config validate 2>&1) || {
        echo "⚠️ 配置验证发现问题:"
        echo "$validate_out" | tail -5
        echo "   尝试自动修复..."
        timeout 20 openclaw doctor --fix >/dev/null 2>&1 || true
        timeout 10 openclaw config validate >/dev/null 2>&1 || echo "⚠️ 自动修复后仍有配置问题，请手动检查: openclaw config validate"
      }
    fi
    # 先停掉可能处于崩溃循环的网关
    systemctl --user stop openclaw-gateway.service 2>/dev/null || true
    sleep 2
    systemctl --user reset-failed openclaw-gateway.service 2>/dev/null || true
    start_gateway force 0 2>/dev/null || openclaw gateway restart 2>/dev/null || {
      echo "❌ 网关启动失败！请检查: systemctl --user status openclaw-gateway"
      return 1
    }
    echo "✅ 配置已生效！AI 将使用新分配的模型工作。"
}

openclaw_get_primary_text_model() {
    local config_file tmp_json
    config_file=$(openclaw_get_config_file)
    tmp_json=$(mktemp /tmp/openclaw_cfg_XXXXXX.json)
    openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null || echo '{}' > "$tmp_json"
    python3 - "$tmp_json" <<'PY'
import json, sys
from pathlib import Path
path = Path(sys.argv[1])
cfg = {}
if path.exists():
    try:
        cfg = json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        cfg = {}
value = cfg.get('agents', {}).get('defaults', {}).get('model', {})
if isinstance(value, dict):
    primary = value.get('primary', '')
    if isinstance(primary, str):
        print(primary)
PY
    rm -f "$tmp_json"
}

openclaw_memorysearch_loop_self_heal() {
    local primary_model memory_model
    echo "🩺 正在执行 memory_search 死循环自愈..."
    openclaw_safe_enable_global_tools
    openclaw_memory_config_set "memorySearch.provider" "ollama"
    primary_model=$(openclaw_get_primary_text_model)
    if [ -z "$primary_model" ]; then
      primary_model="ollama/qwen2.5:7b"
    fi
    if [[ "$primary_model" == ollama/* ]]; then
      memory_model="${primary_model#ollama/}"
      openclaw_configure_local_ollama_provider "$memory_model" "text" >/dev/null 2>&1 || true
      echo "✅ 已让记忆检索跟随当前主文本模型: $memory_model"
    else
      # 主模型是云端模型，嵌入必须用本地 Ollama 模型
      memory_model=$(openclaw_memory_config_get "memorySearch.model" 2>/dev/null || true)
      # 验证：如果读到的模型名包含 / 或看起来像云端模型，回退到本地
      if [ -z "$memory_model" ] || [ "$memory_model" = "null" ] || [[ "$memory_model" == */* ]] || [[ "$memory_model" == gemini* ]] || [[ "$memory_model" == gpt* ]] || [[ "$memory_model" == claude* ]]; then
        memory_model="qwen2.5:7b"
      fi
      echo "ℹ️ 当前主文本模型不是本地 Ollama（$primary_model），记忆检索引擎独立使用本地模型: $memory_model"
    fi
    openclaw_memory_config_set "memorySearch.model" "$memory_model"
    # 使用 tools.profile 切配置，避免 JSON5 文件被 json.loads 损坏
    openclaw config set tools.profile minimal >/dev/null 2>&1 || true
    echo "✅ 已执行 tools.profile=minimal 诊断切换"
    start_gateway force 0 >/dev/null 2>&1 || openclaw gateway restart >/dev/null 2>&1 || true
    openclaw config set tools.profile coding >/dev/null 2>&1 || true
    echo "✅ 已恢复 tools.profile=coding"
    openclaw_validate_global_tools_runtime
}

openclaw_optimize_memory_and_skills() {
    local config_file tmp_json bak_file original_bytes
    config_file=$(openclaw_get_config_file)
    mkdir -p "$HOME/.openclaw/workspace" "$HOME/.openclaw/workspace/skills" "$HOME/.openclaw/workspace/memory"

    # 防御：如果配置文件不存在或为空，不执行优化（等完整配置生成后再做）
    if [ ! -s "$config_file" ]; then
      echo "⚠️ openclaw.json 不存在或为空，跳过配置优化"
      return 0
    fi
    original_bytes=$(wc -c < "$config_file" 2>/dev/null || echo 0)
    if [ "$original_bytes" -lt 10 ]; then
      echo "⚠️ openclaw.json 内容过少 (${original_bytes}bytes)，跳过配置优化防止清空"
      return 0
    fi

    # 自动备份
    bak_file="${config_file}.bak.$(date +%Y%m%d_%H%M%S)"
    cp "$config_file" "$bak_file" 2>/dev/null || true

    # JSON5 safe: pre-process config to temp JSON
    tmp_json=$(mktemp /tmp/openclaw_cfg_XXXXXX.json)
    if ! openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null; then
      rm -f "$tmp_json"
      echo "⚠️ JSON5 预处理失败，跳过配置优化"
      return 0
    fi

    python3 - "$config_file" "$tmp_json" "$original_bytes" <<'PY'
import json, sys, os
from pathlib import Path

out_path = Path(sys.argv[1])   # original config file (write target)
cfg_path = Path(sys.argv[2])   # JSON5-safe temp copy (read source)
orig_bytes = int(sys.argv[3])  # original file size

cfg = {}
read_ok = False
if cfg_path.exists() and cfg_path.stat().st_size > 0:
    try:
        raw = cfg_path.read_text(encoding='utf-8')
        cfg = json.loads(raw)
        if isinstance(cfg, dict):
            read_ok = True
    except Exception:
        cfg = {}

# 防御：如果读取失败或配置为空，不覆盖原文件
if not read_ok or len(cfg) == 0:
    print("⚠️ 配置读取结果为空，跳过写入防止覆盖", file=sys.stderr)
    sys.exit(0)

# 记录修改前的关键字段数量（用于事后校验）
agents_before = len(cfg.get('agents', {}).get('list', []))
models_before = sum(1 for _ in cfg.get('models', {}).get('providers', {}).values() if isinstance(_, dict) and _.get('models'))

gateway = cfg.setdefault('gateway', {})
gateway.setdefault('mode', 'local')
gateway['bind'] = 'loopback'
gateway.setdefault('port', 18789)
for legacy_key in ('host', 'hostname', 'url', 'baseUrl'):
    gateway.pop(legacy_key, None)
gateway.setdefault('auth', {})['mode'] = 'token'
gateway.pop('controlUi', None)

# OpenClaw 2026.6+: tools.profile 替代了不存在的 tools.global.enabled
tools_cfg = cfg.setdefault('tools', {})
tools_cfg.pop('global', None)
tools_cfg.setdefault('profile', 'coding')

memory = cfg.setdefault('memory', {})
qmd = memory.setdefault('qmd', {})
qmd.setdefault('includeDefaultMemory', True)

agents = cfg.setdefault('agents', {})
defaults = agents.setdefault('defaults', {})
defaults.setdefault('workspace', '~/.openclaw/workspace')
models_obj = defaults.get('models')
if not isinstance(models_obj, dict):
    if isinstance(models_obj, list):
        models_obj = {str(item): {} for item in models_obj if isinstance(item, str) and item.strip()}
    else:
        models_obj = {}
    defaults['models'] = models_obj
defaults.pop('skills', None)

# 写回前最终防御：至少应该保留 agents.list 和 models.providers
agents_after = len(cfg.get('agents', {}).get('list', []))
if agents_before > 0 and agents_after == 0:
    print(f"⚠️ agents.list 被意外清空 ({agents_before}→0)，放弃写入", file=sys.stderr)
    sys.exit(0)

out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
PY
    rm -f "$tmp_json"

    # 清理旧备份（保留最近3个）
    ls -t "${config_file}.bak."* 2>/dev/null | tail -n +4 | xargs rm -f 2>/dev/null || true
}

openclaw_inject_skills() {
    local skills_dir="$HOME/.openclaw/workspace/skills"
    mkdir -p "$skills_dir"
    cat > "$skills_dir/auto-model-routing.md" <<'EOF'
# Auto Model Routing
- Use `agents.defaults.model.primary` for daily text turns.
- Prefer `ollama/qwen2.5:7b` for daily text turns.
- Use `agents.defaults.imageModel.primary` for image understanding.
- Use `ollama/qwen2.5-coder:1.5b` for code-heavy tasks.
- Prefer concise responses to reduce token usage.
- Respect hardware budget before escalating to larger experts.
- Keep memory injection under the configured context percentage limit.
EOF
    cat > "$skills_dir/token-saver.md" <<'EOF'
# Token Saver
- Answer directly.
- Keep outputs concise.
- Avoid unnecessary repetition.
- Reuse cached memory and stable facts before expanding context.
EOF
    cat > "$skills_dir/memory-first.md" <<'EOF'
# Memory First (Active Injection Mode)
- The system has ALREADY injected relevant memories into the context above.
- READ the [memory_context] section carefully before answering.
- Use injected memories to personalize your response.
- If memories contain user identity/preferences, acknowledge them naturally.
- When user explicitly says "remember", extract and persist the fact.
- Do NOT say "I don't have access to previous conversations" - memories are provided.
- If injected memories are insufficient, proceed with available context.
EOF
    cat > "$skills_dir/gateway-recovery.md" <<'EOF'
# Gateway Recovery
- Check `systemctl --user status openclaw-gateway.service` when the gateway is unavailable.
- Check whether port `18789` is listening before retrying dependent actions.
- Prefer `start_gateway force 0` after config changes that affect gateway startup.
EOF
    openclaw_optimize_memory_and_skills
    echo "✅ Skills 已写入: $skills_dir"
}

openclaw_evomap_real_ingest() {
    local title="$1" content="$2"
    local evomap_dir="$HOME/.openclaw/workspace/memory/evomap-ingest"
    mkdir -p "$evomap_dir"
    printf '%s\n\n%s\n' "$title" "$content" > "$evomap_dir/$(date +%s)-note.md"
    echo "✅ 经验已写入: $evomap_dir"
}

openclaw_configure_local_ollama_provider() {
    local config_file provider_model full_model model_role tmp_json
    config_file=$(openclaw_get_config_file)
    provider_model="${1:-qwen2.5:7b}"
    model_role="${2:-text}"
    full_model="ollama/${provider_model}"
    # JSON5 safe: pre-process config to temp JSON
    tmp_json=$(mktemp /tmp/openclaw_cfg_XXXXXX.json)
    openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null || echo '{}' > "$tmp_json"
    python3 - "$config_file" "$tmp_json" "$provider_model" "$full_model" "$model_role" "$(openclaw_resolve_ollama_bin 2>/dev/null || printf '%s' /usr/bin/ollama)" "$SKPL_AI_STACK_ACCEL_STATE_FILE" <<'PY'
import json, sys
from pathlib import Path
out_path = Path(sys.argv[1])   # original config file (write target)
cfg_path = Path(sys.argv[2])   # JSON5-safe temp copy (read source)
raw_model = sys.argv[3]
full_model = sys.argv[4]
role = sys.argv[5]
ollama_bin = sys.argv[6]
accel_state_path = Path(sys.argv[7])
cfg = {}
if cfg_path.exists():
    try:
        cfg = json.loads(cfg_path.read_text(encoding='utf-8'))
    except Exception:
        cfg = {}

accel = {}
if accel_state_path.exists():
    try:
        accel = json.loads(accel_state_path.read_text(encoding='utf-8'))
    except Exception:
        accel = {}

def build_entry(model_id: str, role_name: str):
    lower = model_id.lower()
    is_image = role_name == 'image' or any(token in lower for token in ('vl', 'vision', 'llava', 'minicpm-v'))
    is_code = role_name == 'code' or 'coder' in lower
    is_qwen = 'qwen' in lower
    is_deepseek = 'deepseek' in lower
    is_small_model = any(tag in lower for tag in ('0.3b', '0.5b', '1.5b', '1.8b', '3b'))
    is_large_model = any(tag in lower for tag in ('14b', '32b', '34b', '70b'))
    params = {'keep_alive': '15m'}
    if is_image:
        entry = {'id': model_id, 'name': model_id, 'input': ['text', 'image']}
        params['num_ctx'] = 4096
    elif is_code:
        entry = {'id': model_id, 'name': model_id, 'input': ['text'], 'reasoning': True}
        params['num_ctx'] = 16384 if any(tag in lower for tag in ('14b', '32b')) else 8192
        params['thinking'] = False
    else:
        entry = {'id': model_id, 'name': model_id, 'input': ['text']}
        params['num_ctx'] = 8192
        if is_qwen:
            params['thinking'] = False
    if is_qwen and not is_image:
        params['num_predict'] = max(int(params.get('num_predict', 0) or 0), 1024)
    if is_deepseek and is_code:
        params['num_ctx'] = max(int(params.get('num_ctx', 8192) or 8192), 16384)
        params['temperature'] = 0.2
    if is_small_model and not is_image:
        params['num_batch'] = max(int(params.get('num_batch', 0) or 0), 256)
        params['num_thread'] = max(4, int(params.get('num_thread', 0) or 0))
    if is_large_model and not is_image:
        params['num_batch'] = max(int(params.get('num_batch', 0) or 0), 1024)
        params['num_ctx'] = max(int(params.get('num_ctx', 8192) or 8192), 16384)
    flash_state = (accel.get('flashAttention2') or {}).get('status')
    kv_state = (accel.get('kvInt8') or {}).get('status')
    cpu_state = (accel.get('cpuAssist') or {}).get('status')
    trt_state = (accel.get('tensorRt') or {}).get('status')
    accel_hints = []
    if flash_state == 'available':
        accel_hints.append('flash-attn')
    if kv_state in ('candidate', 'available'):
        accel_hints.append('kv-int8')
    if cpu_state == 'active':
        accel_hints.append('cpu-assist')
    if trt_state == 'available':
        accel_hints.append('tensorrt')
    if accel_hints:
        entry['runtimeHints'] = accel_hints
        if 'flash-attn' in accel_hints and not is_image:
            params['num_batch'] = max(int(params.get('num_batch', 0) or 0), 512 if not is_large_model else 1024)
        if 'kv-int8' in accel_hints:
            params['num_ctx'] = max(int(params.get('num_ctx', 4096) or 4096), 16384 if not is_image else 8192)
        if 'cpu-assist' in accel_hints:
            params['num_thread'] = max(4, int(params.get('num_thread', 0) or 0))
        if 'tensorrt' in accel_hints:
            params['main_gpu'] = 0
            if is_image:
                params['num_batch'] = max(int(params.get('num_batch', 0) or 0), 64)
    entry['params'] = params
    return entry

cfg.setdefault('models', {}).setdefault('providers', {})
provider = cfg['models']['providers'].setdefault('ollama', {})
provider['baseUrl'] = provider.get('baseUrl') or 'http://127.0.0.1:11434'
provider['apiKey'] = provider.get('apiKey') or 'ollama-local'
provider['api'] = provider.get('api') or 'ollama'
provider['timeoutSeconds'] = max(int(provider.get('timeoutSeconds', 0) or 0), 300)
local_service = provider.get('localService')
if not isinstance(local_service, dict):
    local_service = {}
provider['localService'] = local_service
local_service.setdefault('command', ollama_bin)
local_service.setdefault('args', ['serve'])
local_service.setdefault('healthUrl', 'http://127.0.0.1:11434/api/tags')
local_service.setdefault('readyTimeoutMs', 180000)
local_service.setdefault('idleStopMs', 0)
models = provider.setdefault('models', [])
entry = build_entry(raw_model, role)
updated = False
for index, item in enumerate(models):
    if isinstance(item, dict) and item.get('id') == raw_model:
        merged = dict(item)
        merged.update(entry)
        if isinstance(item.get('params'), dict):
            params = dict(item['params'])
            params.update(entry['params'])
            merged['params'] = params
        models[index] = merged
        updated = True
        break
if not updated:
    models.append(entry)

cfg.setdefault('agents', {}).setdefault('defaults', {})
defs = cfg['agents']['defaults']
defs.setdefault('models', {})
defs['models'].setdefault(full_model, {})
# memorySearch 必须在 agents.defaults 内
memory_search = defs.get('memorySearch')
if not isinstance(memory_search, dict):
    memory_search = {}
    defs['memorySearch'] = memory_search
memory_search['provider'] = 'ollama'
memory_search['model'] = raw_model if '/' not in raw_model else raw_model.split('/', 1)[1]
# 迁移旧版 root-level memorySearch
if 'memorySearch' in cfg and cfg['memorySearch'] is not memory_search:
    del cfg['memorySearch']
if role == 'image':
    image_model_cfg = defs.get('imageModel')
    if not isinstance(image_model_cfg, dict):
        image_model_cfg = {}
        defs['imageModel'] = image_model_cfg
    image_model_cfg['primary'] = full_model
elif role == 'code':
    defs['models'][full_model].setdefault('agentRuntime', {'id': 'auto'})
    defs['models'][full_model].setdefault('params', {})
    defs['models'][full_model]['params'].setdefault('thinking', False)
else:
    model_cfg = defs.get('model')
    if not isinstance(model_cfg, dict):
        model_cfg = {}
        defs['model'] = model_cfg
    model_cfg['primary'] = full_model
out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
PY
    rm -f "$tmp_json"
    echo "✅ 已写入本地 Ollama provider 配置"
}

openclaw_memorysearch_config_supported() {
    # 快速检查，不再调用 openclaw doctor 避免卡住
    return 0
}

openclaw_safe_enable_global_tools() {
    # OpenClaw 2026.6+ 无 tools.global 字段，不用 python 注入；用 CLI profile 更安全
    if command -v openclaw >/dev/null 2>&1; then
      openclaw config set tools.profile coding >/dev/null 2>&1 || true
    fi
    echo "✅ 已设置 tools.profile=coding"
}

openclaw_validate_global_tools_runtime() {
    if ! openclaw_has_command openclaw; then
      echo "ℹ️ openclaw 命令未安装，已跳过 tools 验活"
      return 0
    fi
    if timeout 10 openclaw models status >/dev/null 2>&1; then
      echo "✅ tools 验活通过"
      return 0
    fi
    echo "⚠️ tools 验活未通过，请检查 openclaw gateway 是否正常运行"
    return 0
}

openclaw_apply_recommended_model_profile() {
    local text_model="${OPENCLAW_TEXT_MODEL_RESOLVED:-ollama/qwen2.5:7b}"
    local image_model="${OPENCLAW_IMAGE_MODEL_RESOLVED:-ollama/gemma3:4b}"
    local code_model="${OPENCLAW_CODE_MODEL_RESOLVED:-ollama/qwen2.5-coder:1.5b}"
    local config_file tmp_json
    config_file=$(openclaw_get_config_file)
    # JSON5 safe: pre-process config to temp JSON
    tmp_json=$(mktemp /tmp/openclaw_cfg_XXXXXX.json)
    openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null || echo '{}' > "$tmp_json"
    python3 - "$config_file" "$tmp_json" "$text_model" "$image_model" "$code_model" "$(openclaw_resolve_ollama_bin 2>/dev/null || printf '%s' /usr/bin/ollama)" "${OPENCLAW_FORCE_LOCAL_PROFILE:-0}" <<'PY'
import json, sys
from pathlib import Path
out_path = Path(sys.argv[1])   # original config file (write target)
cfg_path = Path(sys.argv[2])   # JSON5-safe temp copy (read source)
text_model, image_model, code_model, ollama_bin, force_flag = sys.argv[3:8]
force_local_profile = force_flag == '1'
cfg = {}
if cfg_path.exists():
    try:
        cfg = json.loads(cfg_path.read_text(encoding='utf-8'))
    except Exception:
        cfg = {}
cfg.setdefault('models', {}).setdefault('providers', {})

def ensure_model_entry(provider_models, entry):
    for index, item in enumerate(provider_models):
        if isinstance(item, dict) and item.get('id') == entry['id']:
            merged = dict(item)
            merged.update(entry)
            if isinstance(item.get('params'), dict) and isinstance(entry.get('params'), dict):
                params = dict(item['params'])
                params.update(entry['params'])
                merged['params'] = params
            provider_models[index] = merged
            return
    provider_models.append(entry)

provider = cfg['models']['providers'].setdefault('ollama', {})
provider['baseUrl'] = provider.get('baseUrl') or 'http://127.0.0.1:11434'
provider['apiKey'] = provider.get('apiKey') or 'ollama-local'
provider['api'] = provider.get('api') or 'ollama'
provider['timeoutSeconds'] = max(int(provider.get('timeoutSeconds', 0) or 0), 300)
local_service = provider.get('localService')
if not isinstance(local_service, dict):
    local_service = {}
    provider['localService'] = local_service
local_service.setdefault('command', ollama_bin)
local_service.setdefault('args', ['serve'])
local_service.setdefault('healthUrl', 'http://127.0.0.1:11434/api/tags')
local_service.setdefault('readyTimeoutMs', 180000)
local_service.setdefault('idleStopMs', 0)
provider_models = provider.setdefault('models', [])
if not isinstance(provider_models, list):
    provider_models = []
    provider['models'] = provider_models
ensure_model_entry(provider_models, {'id': 'qwen2.5:7b', 'name': 'qwen2.5:7b', 'input': ['text'], 'params': {'keep_alive': '15m', 'num_ctx': 8192}})
ensure_model_entry(provider_models, {'id': 'gemma3:4b', 'name': 'gemma3:4b', 'input': ['text', 'image'], 'params': {'keep_alive': '15m', 'num_ctx': 4096, 'thinking': False}})
ensure_model_entry(provider_models, {'id': 'qwen2.5-coder:1.5b', 'name': 'qwen2.5-coder:1.5b', 'input': ['text'], 'reasoning': True, 'params': {'keep_alive': '15m', 'num_ctx': 8192, 'thinking': False}})
# 动态注册当前实际使用的模型（避免 hardcode 遗漏）
for actual_model in (text_model, image_model, code_model):
    if actual_model.startswith('ollama/'):
        mid = actual_model.split('/', 1)[1]
        if mid:
            ensure_model_entry(provider_models, {'id': mid, 'name': mid, 'input': ['text']})

cfg.setdefault('agents', {}).setdefault('defaults', {})
defs = cfg['agents']['defaults']
defs.setdefault('models', {})
for model in (text_model, image_model, code_model):
    defs['models'].setdefault(model, {})
# 无论当前主模型是什么，都应用推荐本地模型组合
defs.setdefault('model', {})['primary'] = text_model
defs['imageModel'] = {'primary': image_model}
defs['models'][code_model].setdefault('agentRuntime', {'id': 'auto'})

# memorySearch 在 agents.defaults 下
memory_search = defs.get('memorySearch')
if not isinstance(memory_search, dict):
    memory_search = {}
    defs['memorySearch'] = memory_search
memory_search['provider'] = 'ollama'
memory_search['model'] = text_model.split('/', 1)[1] if '/' in text_model else text_model
if 'memorySearch' in cfg and cfg['memorySearch'] is not memory_search:
    del cfg['memorySearch']

out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
PY
    rm -f "$tmp_json"
    echo "✅ 推荐模型组合已写入"
    echo "   文本: $text_model"
    echo "   视觉: $image_model"
    echo "   代码: $code_model"
}

# ═══════════════════════════════════════════════════════════════════════
# 多Agent多模型架构 — 基于 OpenClaw 原生多 Agent + 子Agent 编排
# 取代旧的运行时智能路由管道（后者与 OpenClaw 架构不兼容）
# ═══════════════════════════════════════════════════════════════════════

# ── 硬件分级 → Agent 能力矩阵映射表 ──
# ─────────────────────────────────────────────────────────────────
#  V3 Supervisor Architecture: Capability Matrix
#  本地模型 = 控制流 (CPU) | 云端模型 = 计算流 (GPU)
# ─────────────────────────────────────────────────────────────────
openclaw_multi_agent_capability_matrix() {
  local tier="$1" cloud_model="${2:-}"
  python3 - "$tier" "$cloud_model" <<'PY'
import json, sys
tier = sys.argv[1]
cloud = sys.argv[2].strip() if len(sys.argv) > 2 else ''

# ═══════════════════════════════════════════════════
#  V3 架构: Supervisor + 4 本地Agent + 9 Cloud Expert
# ═══════════════════════════════════════════════════

# ── 按硬件分级选择本地模型 ──
if tier == 'golden-gpu':
    orch_model   = 'ollama/qwen3:1.8b'        # Supervisor（控制流）
    mem_model    = 'ollama/qwen3:0.6b'         # Memory Agent（检索）
    plan_model   = 'ollama/qwen2.5:7b'         # Planner Agent（拆解）
    tool_model   = 'ollama/qwen2.5:7b'         # Tool Agent（执行）
    vision_local = 'ollama/gemma3:12b'         # 本地多模态后备
elif tier in ('advanced-gpu','entry-gpu'):
    orch_model   = 'ollama/qwen3:1.8b'
    mem_model    = 'ollama/qwen3:0.6b'
    plan_model   = 'ollama/qwen3:1.8b'
    tool_model   = 'ollama/qwen2.5:7b'
    vision_local = 'ollama/gemma3:4b'
elif tier == 'advanced-cpu':
    orch_model   = 'ollama/qwen3:1.8b'
    mem_model    = 'ollama/qwen3:0.6b'
    plan_model   = 'ollama/qwen3:1.8b'
    tool_model   = 'ollama/qwen2.5:7b'
    vision_local = None
else:  # entry-cpu / fallback
    orch_model   = 'ollama/qwen3:0.6b'
    mem_model    = 'ollama/qwen3:0.6b'
    plan_model   = 'ollama/qwen3:0.6b'
    tool_model   = 'ollama/qwen3:0.6b'
    vision_local = None

# ── 本地Agent列表（控制流层） ──
local_agents = [
    {
        "id": "memory-agent", "model": mem_model,
        "label": "记忆管理Agent", "type": "local",
        "capabilities": ["记忆检索","记忆写入","记忆压缩","记忆评分","记忆淘汰"],
        "difficulty": "简单", "maxTokens": 1024,
    },
    {
        "id": "planner-agent", "model": plan_model,
        "label": "任务规划Agent", "type": "local",
        "capabilities": ["任务分解","步骤规划","依赖分析","风险预测"],
        "difficulty": "中等", "maxTokens": 2048,
    },
    {
        "id": "tool-agent", "model": tool_model,
        "label": "工具编排Agent", "type": "local",
        "capabilities": ["工具选择","工具编排","工具执行","工具重试","结果格式化"],
        "difficulty": "中等", "maxTokens": 2048,
    },
]

matrix = {
    "orchestrator": {"model": orch_model, "label": "Supervisor(调度者)"},
    "localAgents": local_agents,
    "cloudExperts": [],
    "memorySearch": {"provider": "ollama", "model": "qwen2.5:7b"},
    "toolsProfile": "coding",
    "architecture": "V3-Supervisor",
}

# ── Cloud Expert Pool（计算流层，9个专家） ──
# 策略：本地模型只做控制流（分类+路由），云端大模型处理真正复杂任务
if cloud and not cloud.startswith('ollama/'):
    cl = cloud.split('/', 1)[1] if '/' in cloud else cloud
    experts = [
        {"id":"expert-code",        "label":f"代码专家({cl})","role":"Code Expert",
         "capabilities":["复杂代码","算法实现","系统开发","代码审查","重构"],
         "binding":"code", "maxTokens":16384},
        {"id":"expert-arch",        "label":f"架构专家({cl})","role":"Architecture Expert",
         "capabilities":["系统设计","架构决策","技术选型","API设计","数据库设计"],
         "binding":"architecture", "maxTokens":8192},
        {"id":"expert-research",    "label":f"调研专家({cl})","role":"Research Expert",
         "capabilities":["资料调研","竞品分析","技术评估","行业报告"],
         "binding":"research", "maxTokens":8192},
        {"id":"expert-security",    "label":f"安全专家({cl})","role":"Security Expert",
         "capabilities":["安全审计","风险评估","漏洞分析","合规检查"],
         "binding":"security", "maxTokens":8192},
        {"id":"expert-verify",      "label":f"校验专家({cl})","role":"Verification Expert",
         "capabilities":["事实核查","结果验证","质量检查","信息校准"],
         "binding":"verification", "maxTokens":4096},
        {"id":"expert-writing",     "label":f"写作专家({cl})","role":"Writing Expert",
         "capabilities":["长文撰写","技术文档","文案优化","翻译校对"],
         "binding":"writing", "maxTokens":8192},
        {"id":"expert-reasoning",   "label":f"推理专家({cl})","role":"Reasoning Expert",
         "capabilities":["深度推理","逻辑分析","数学证明","策略推演"],
         "binding":"reasoning", "maxTokens":16384},
        {"id":"expert-data",        "label":f"数据专家({cl})","role":"Data Expert",
         "capabilities":["数据分析","SQL","ETL","可视化","统计建模"],
         "binding":"data", "maxTokens":8192},
    ]
    # 视觉专家（仅多模态capable tier）
    if vision_local is not None:
        experts.append({
            "id":"expert-vision",   "label":f"视觉专家({cl})","role":"Vision Expert",
            "capabilities":["复杂图像分析","图纸解读","场景理解","OCR"],
            "binding":"vision", "maxTokens":4096,
        })

    # 为不同云专家分配不同模型（按绑定类型区分，避免共用同一云端模型）
    # ── 重要说明 ──
    # 专家模型区分仅在路由型 provider（如 openrouter）下真正生效。
    # 若使用原生 API（如 anthropic、google 直连），模型名称可能无效，
    # 此时所有专家将回退使用 cloud 参数指定的模型。
    # 建议：使用 openrouter 作为 cloud provider，以获得最佳多模型路由体验。
    cloud_provider, cloud_base = (cloud.split('/', 1) if '/' in cloud else (None, None))
    expert_model_map = {
        "code": f"{cloud_provider}/deepseek-coder" if cloud_provider else cloud,
        "architecture": f"{cloud_provider}/claude-3.5-sonnet" if cloud_provider else cloud,
        "reasoning": f"{cloud_provider}/gemini-2.5-pro" if cloud_provider else cloud,
        "security": f"{cloud_provider}/meta-llama-3.3-70b-instruct" if cloud_provider else cloud,
        "verification": f"{cloud_provider}/gemini-2.5-flash" if cloud_provider else cloud,
        "research": f"{cloud_provider}/phi-3-medium-128k-instruct" if cloud_provider else cloud,
        "writing": cloud,
        "data": cloud,
        "vision": f"{cloud_provider}/gemini-2.5-pro" if cloud_provider else cloud,
    }
    # 记录使用的 provider 列表，用于后续配置写入时校验模型可用性
    used_providers = set()
    for e in experts:
        e["model"] = expert_model_map.get(e["binding"], cloud)
        e["type"] = "cloud"
        e["difficulty"] = "复杂"
        if '/' in str(e.get('model', '')):
            used_providers.add(str(e['model']).split('/')[0])
    matrix["cloudExperts"] = experts
    # 在日志中记录专家模型分配情况，便于排查问题
    expert_model_count = len(experts)
    used_providers_list = sorted(used_providers) if used_providers else ['(无)']

# ── 最终agents列表（orchestrator + 本地 + 云端） ──
agents = []
agents.append({"id": "main", "model": orch_model, "type": "local", "label": "Supervisor(调度者)"})
agents.extend(matrix["localAgents"])
agents.extend(matrix["cloudExperts"])
matrix["agents"] = agents

# ── 权限推导 ──
for a in matrix["agents"]:
    aid = a.get("id", "")
    atype = a.get("type", "")
    binding = a.get("binding", "")

    if aid == "main":
        a["tools"] = {"allow": ["sessions_spawn","read"]}
        a["subagents"] = {"delegationMode": "prefer", "maxSpawnDepth": 2}
    elif atype == "local" and "memory" in aid:
        a["tools"] = {"allow": ["read","memory_get","memory_search"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0}
    elif atype == "local" and "planner" in aid:
        a["tools"] = {"allow": ["read","write"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0}
    elif atype == "local" and "tool" in aid:
        a["tools"] = {"allow": ["read","write","exec","edit","apply_patch","process","browser"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0, "maxConcurrent": 4, "runTimeoutSeconds": 600}
    elif atype == "cloud" and binding == "code":
        a["tools"] = {"allow": ["read","write","exec","edit","apply_patch"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0, "maxConcurrent": 2, "runTimeoutSeconds": 1800}
    elif atype == "cloud" and binding == "architecture":
        a["tools"] = {"allow": ["read","write"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0, "maxConcurrent": 2, "runTimeoutSeconds": 1200}
    elif atype == "cloud" and binding in ("reasoning","research","writing","data"):
        a["tools"] = {"allow": ["read","write","exec"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0, "maxConcurrent": 2, "runTimeoutSeconds": 1200}
    elif atype == "cloud" and binding in ("security","verification"):
        a["tools"] = {"allow": ["read"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0, "runTimeoutSeconds": 900}
    elif atype == "cloud" and binding == "vision":
        a["tools"] = {"allow": ["read"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0, "runTimeoutSeconds": 600}
    else:
        a["tools"] = {"allow": ["read"]}
        a["subagents"] = {"delegationMode": "suggest", "maxSpawnDepth": 0}

matrix["_meta"] = {
    "expert_model_count": expert_model_count if 'expert_model_count' in dir() else 0,
    "used_providers": used_providers_list if 'used_providers_list' in dir() else [],
}
print(json.dumps(matrix, ensure_ascii=False))
PY
}

# ── 编排器 Agent System Prompt 模板 ──
# V3 架构: Supervisor Agent（本地控制流）
openclaw_orchestrator_system_prompt() {
  local agent_list_json="$1"  # JSON数组，{id, label, capabilities, difficulty, model}
  python3 - "$agent_list_json" <<'PY'
import json, sys
agents = json.loads(sys.argv[1])

# 分离本地Agent和云端Expert
local_agents = [a for a in agents if a.get('type') == 'local']
cloud_experts = [a for a in agents if a.get('type') == 'cloud']

prompt = """你是 **OpenClaw V3 Supervisor Agent**，你是整个系统的唯一调度者和控制中心。

## 架构原则（核心必须遵守）
- **本地模型 = 控制流**（你和3个本地Agent都是本地小模型，只做分类、路由、调度、决策）
- **云端模型 = 计算流**（所有复杂计算、推理、代码、设计都派发给云端专家处理）
- **你只做控制，不做计算** → 绝对不可以自己写代码、做复杂推理、长文本分析，必须派发给专业Agent

## 你的唯一职责
1. **意图识别**：分析用户问题类型
2. **任务分类**：判断简单/复杂，路由到本地还是云端
3. **Agent调度**：通过 sessions_spawn 派发任务给专业Agent
4. **记忆获取**：需要上下文时先派发给 Memory Agent
5. **结果汇总**：收集所有子Agent结果，整理后返回用户

## 分层架构
```
你 (Supervisor)
 ├── 本地控制层（3个本地Agent，全部本地CPU）
 │   ├─ memory-agent → 记忆检索/写入/压缩/淘汰
 │   ├─ planner-agent → 任务拆解/步骤规划/依赖分析
 │   └─ tool-agent → 工具选择/编排/执行/重试
 │
 └── 云端计算层（Cloud Expert Pool，云端GPU）
     ├─ expert-code → 复杂代码/算法开发/代码审查
     ├─ expert-arch → 系统架构设计/技术选型/API设计
     ├─ expert-reasoning → 深度推理/逻辑分析/数学证明
     ├─ expert-research → 资料调研/竞品分析/技术评估
     ├─ expert-security → 安全审计/风险评估/漏洞分析
     ├─ expert-verify → 事实核查/结果验证/质量检查
     ├─ expert-writing → 长文撰写/技术文档/文案优化
     ├─ expert-data → 数据分析/SQL/ETL/统计建模
     └─ expert-vision → 图像分析/图纸解读/OCR/场景理解
```

## 路由规则（严格遵守，节省Token）

### 第一层：分类任务难度
- **简单任务**（单步问答、闲聊、简短总结、日常对话）→ **你直接回答**，不派发任何子Agent
- **需要上下文** → 先派发 `memory-agent` 获取记忆
- **中等任务** → 本地Agent处理（planner-agent / tool-agent）
- **复杂/困难任务** → 云端专家处理（Cloud Expert Pool）

### 第二层：本地Agent路由
- 需要记忆（历史对话、过往信息检索）→ `memory-agent`
- 需要任务规划（多步骤项目、开发计划）→ `planner-agent`
- 需要工具调用（文件读写、浏览器访问、Shell执行）→ `tool-agent`

### 第三层：云端专家路由（复杂任务）
根据问题类型选择对应专家：
- **代码/编程/开发/重构** → `expert-code`
- **系统设计/架构选型/方案设计** → `expert-arch`
- **深度推理/逻辑分析/数学问题/策略推演** → `expert-reasoning`
- **资料调研/竞品分析/技术评估** → `expert-research`
- **安全审计/风险评估/漏洞检查** → `expert-security`
- **事实核查/结果验证/质量校验** → `expert-verify`
- **文档撰写/文案写作/翻译优化** → `expert-writing`
- **数据分析/SQL/统计/可视化** → `expert-data`
- **图片/OCR/图纸解读/视觉分析** → `expert-vision`

### 第四层：双阶段推理（提升质量）
对于重要设计任务，必须走「生成 → 审核 → 验证」流程：
1. 用户要求设计系统/架构 → `expert-arch` 生成方案
2. 方案生成后 → `expert-security` 做安全审核
3. 审核后 → `expert-verify` 做事实校验
4. 最后你汇总结果返回用户

## sessions_spawn 调用格式
```
sessions_spawn(agentId="<AgentID>", prompt="<精简任务描述>", context="separate")
```
- agentId: 从可用Agent列表选择
- prompt: 精简任务描述（≤200字），去掉冗余上下文
- context: "separate"（独立会话，节省Token）

## 输出格式
1. 先输出分类：**[类型: xxx | 路由: xxx → agentId]**
2. 每次决策输出一行日志：**[DECISION: intent=xxx, agent=agentId]** 以便调试追踪
3. 派发子Agent
4. 收集所有结果后汇总返回用户

## 性能优化
- 对于重复/相似的规划请求（如"再来一次类似的计划"），优先复用 `planner-agent` 上次的输出，避免重复消耗 token
- 如果 `planner-agent` 返回的方案与上次高度相似，直接使用缓存结果而不重新规划
- 规划结果可通过 `memory-agent` 持久化存储，下次类似任务直接检索

## 严格规则（必须遵守）
1. ✅ 你负责**控制流**：意图识别、分类、路由、调度、汇总
2. ✅ 简单问题（≤3句话能回答）→ 你直接回答，不派子Agent
3. ✅ 记忆获取 → 永远通过 `memory-agent`，不自己检索
4. ✅ 复杂任务 → 必须派发给对应云端专家，你不尝试自己做
5. ✅ 云端专家做好后，只做汇总，不重复生成内容
6. ❌ 禁止你自己写代码，必须派给 `expert-code`
7. ❌ 禁止你做复杂推理，必须派给 `expert-reasoning`
8. ❌ 禁止做架构设计，必须派给 `expert-arch`
9. ❌ 禁止多轮递归派发，所有专家都是一级子Agent，不可再派发

---

## 可用的本地Agent（控制层）
"""

# 输出本地Agent
for a in local_agents:
    caps = "、".join(a.get("capabilities", []))
    tools_cfg = a.get("tools", {})
    if isinstance(tools_cfg, dict):
        tools_str = "、".join(tools_cfg.get("allow", ["read"]))
    else:
        tools_str = "read"
    depth = a.get("subagents", {}).get("maxSpawnDepth", 0)
    spawn_tag = "可派发" if depth > 0 else "仅执行"
    prompt += f"- **{a['label']}** (`{a['id']}`)：模型={a['model']}，能力=[{caps}]，权限=[{tools_str}]，{spawn_tag}\n"

if cloud_experts:
    prompt += """
## 可用的云端专家（计算层，复杂任务用）
"""
    for a in cloud_experts:
        caps = "、".join(a.get("capabilities", []))
        prompt += f"- **{a['label']}** (`{a['id']}`)：{a.get('role','')} → 能力=[{caps}]\n"

prompt += """
## 总结
- 90%请求：你（本地小模型）直接回答或路由到本地Agent → 节省Token和成本
- 10%请求：复杂任务路由到云端专家 → GPU大模型处理计算
- 分工明确，各司其职 → 本地控流，云端计算
"""
print(prompt)
PY
}

# ── 生成多Agent OpenClaw配置并写入 ──
openclaw_write_multi_agent_config() {
  local tier="$1" cloud_model="${2:-}" force="${3:-false}"
  local config_file matrix_json agent_json orchestrator_model
  config_file=$(openclaw_get_config_file)

  echo "🧠 正在按硬件分级 [$tier] 生成多Agent多模型架构..."
  [ -n "$cloud_model" ] && echo "   ☁️ 云端增强: $cloud_model"

  matrix_json=$(openclaw_multi_agent_capability_matrix "$tier" "$cloud_model" 2>/dev/null)
  [ -z "$matrix_json" ] && matrix_json=$(openclaw_multi_agent_capability_matrix "entry-cpu" 2>/dev/null)

  orchestrator_model=$(echo "$matrix_json" | python3 -c "import json,sys; d=json.load(sys.stdin); print(d['orchestrator']['model'])")
  agent_json=$(echo "$matrix_json" | python3 -c "import json,sys; d=json.load(sys.stdin); print(json.dumps(d['agents'], ensure_ascii=False))")

  # ===== 增量安全写入（Python 重写，正则JSON5解析 + 增量合并 + 原子写入） =====
  python3 - "$config_file" "$matrix_json" "$agent_json" "$orchestrator_model" "$tier" "$force" "$cloud_model" <<'PY'
import json, re, sys, os, tempfile, shutil
from pathlib import Path

out_path = Path(sys.argv[1])
matrix = json.loads(sys.argv[2])
agent_list = json.loads(sys.argv[3])
orch_model = sys.argv[4]
tier = sys.argv[5]
force = sys.argv[6] == 'true'
cloud_model = sys.argv[7].strip()

# 1. 安全读取原配置（正则修复JSON5，绝不丢数据）
cfg = {}
if out_path.exists():
    raw = out_path.read_text(encoding='utf-8')
    raw = re.sub(r',\s*([}\]])', r'\1', raw)
    raw = re.sub(r'/\*.*?\*/', '', raw, flags=re.DOTALL)
    lines = []
    for line in raw.split('\n'):
        if '//' in line and not ('http://' in line or 'https://' in line):
            line = re.sub(r'//.*$', '', line)
        lines.append(line)
    raw = '\n'.join(lines)
    try:
        cfg = json.loads(raw) if raw.strip() else {}
    except Exception as e:
        print(f"⚠️ 原配置解析失败，将新建（危险！请检查备份）: {e}", file=sys.stderr)
        cfg = {}

if not isinstance(cfg, dict):
    cfg = {}

# 2. 初始化各层
gw = cfg.setdefault('gateway', {})
gw.setdefault('mode', 'local')
gw['bind'] = 'loopback'
gw.setdefault('port', 18789)
gw.setdefault('auth', {})['mode'] = 'token'
gw.pop('controlUi', None)

tools = cfg.setdefault('tools', {})
tools.pop('global', None)
tools.setdefault('profile', matrix.get('toolsProfile', 'coding'))

providers = cfg.setdefault('models', {}).setdefault('providers', {})
ollama_prov = providers.setdefault('ollama', {})
ollama_prov['baseUrl'] = ollama_prov.get('baseUrl') or 'http://127.0.0.1:11434'
ollama_prov['apiKey'] = ollama_prov.get('apiKey') or 'ollama-local'
ollama_prov['api'] = 'ollama'
ollama_prov.setdefault('timeoutSeconds', 300)

# 3. 补全缺失的云 Provider（防止验证报错，不覆盖已有真实配置）
if cloud_model and '/' in cloud_model and not cloud_model.startswith('ollama/'):
    p = cloud_model.split('/')[0]
    if p not in providers:
        providers[p] = {"baseUrl": "https://" + p + ".com/v1", "apiKey": "CHANGE_ME", "api": "openai-completions", "models": []}

# 4. 注册所有本地模型到 ollama provider
all_models = {orch_model}
for a in agent_list:
    all_models.add(a['model'])
existing_ids = {m['id'] if isinstance(m, dict) else m for m in ollama_prov.get('models', [])}
for m in all_models:
    if '/' not in m:  # ollama local
        if m not in existing_ids:
            ollama_prov.setdefault('models', []).append({'id': m, 'name': m, 'input': ['text']})
    else:
        p, mn = m.split('/', 1)
        if p != 'ollama' and p in providers:
            p_models = providers[p].setdefault('models', [])
            p_existing = {item['id'] if isinstance(item, dict) else item for item in p_models}
            if mn not in p_existing:
                p_models.append({'id': mn, 'name': mn, 'input': ['text']})

# 5. 构建 agents.defaults
defaults = cfg.setdefault('agents', {}).setdefault('defaults', {})
defaults.setdefault('model', {})['primary'] = orch_model
defaults.setdefault('workspace', '~/.openclaw/workspace')
sub = defaults.setdefault('subagents', {})
sub.update({'maxSpawnDepth': 2, 'maxChildrenPerAgent': 5, 'maxConcurrent': 8, 'runTimeoutSeconds': 900, 'delegationMode': 'prefer'})
ms = matrix.get('memorySearch', {})
defaults.setdefault('memorySearch', {}).update({'provider': ms.get('provider', 'ollama'), 'model': ms.get('model', 'qwen2.5:7b')})
allowlist = defaults.setdefault('models', {})
allowlist[orch_model] = {}
for a in agent_list:
    allowlist[a['model']] = {}

# imageModel: 使用第一个多模态Agent的模型
multimodal_agents = [a for a in agent_list if 'multimodal' in a.get('id', '')]
if multimodal_agents:
    defaults.setdefault('imageModel', {})['primary'] = multimodal_agents[0]['model']

# 6. 构建 agents.list（增量合并，保留原列表）
agent_configs = cfg.setdefault('agents', {}).setdefault('list', [])
existing_agent_ids = {a.get('id') for a in agent_configs if 'id' in a}

# 确保 main 存在
main_entry = next((a for a in agent_configs if a.get('id') == 'main'), None)
if not main_entry:
    main_entry = {'id': 'main', 'default': True}
    agent_configs.insert(0, main_entry)
main_entry['model'] = {'primary': orch_model}
main_entry['workspace'] = '~/.openclaw/workspace'
main_entry['default'] = True
main_entry['sandbox'] = {'mode': 'off'}
main_entry['tools'] = {'allow': ['sessions_spawn', 'read']}
main_entry['subagents'] = {'delegationMode': 'prefer', 'maxSpawnDepth': 2}

# 7. 添加/更新子Agent（仅当 force 或不存在时）
for a in agent_list:
    aid = a['id']
    if aid == 'main':
        continue
    if aid in existing_agent_ids and not force:
        continue
    entry = next((e for e in agent_configs if e.get('id') == aid), None)
    if not entry:
        entry = {'id': aid}
        agent_configs.append(entry)
    entry['model'] = {'primary': a['model']}
    entry['label'] = a.get('label', aid)
    entry['workspace'] = f'~/.openclaw/agents/{aid}/workspace'
    entry['tools'] = a.get('tools', {'allow': ['read']})
    entry.setdefault('subagents', {})['delegationMode'] = a.get('subagents', {}).get('delegationMode', 'suggest')

# 8. 原子写入（先写临时文件再替换，断电也不损坏原文件）
out_path.parent.mkdir(parents=True, exist_ok=True)
fd, tmp = tempfile.mkstemp(dir=str(out_path.parent), prefix='.openclaw_tmp_', suffix='.json')
try:
    with os.fdopen(fd, 'w', encoding='utf-8') as f:
        json.dump(cfg, f, indent=2, ensure_ascii=False)
        f.write('\n')
    # 备份旧配置
    if out_path.exists() and out_path.stat().st_size > 10:
        bak_path = Path(str(out_path) + '.pre-multi-agent.bak')
        shutil.copy2(out_path, bak_path)
    shutil.move(tmp, str(out_path))
    print(f"✅ 配置已安全写入: {out_path} ({out_path.stat().st_size} bytes)")
except Exception as e:
    try: os.unlink(tmp)
    except: pass
    print(f"❌ 写入失败: {e}", file=sys.stderr)
    sys.exit(1)

# 打印摘要
print(f"✅ 编排器Agent [main] → {orch_model} (可派发子Agent)")
for a in agent_list:
    tools_list = a.get('tools', {}).get('allow', ['read']) if isinstance(a.get('tools'), dict) else ['read']
    tools_str = '、'.join(tools_list)
    spawn_tag = '可派发' if a.get('subagents', {}).get('delegationMode') in ('prefer', 'always') else '仅执行'
    print(f"   专业Agent [{a['id']}] → {a['model']} ({a.get('label','')}, 权限:[{tools_str}], {spawn_tag})")
PY

  # 9. 写入各 Agent System Prompt（包含 Supervisor DAG 和通信协议）
  local orch_prompt_dir="$HOME/.openclaw/agents/main"
  mkdir -p "$orch_prompt_dir"
  cat > "$orch_prompt_dir/AGENTS.md" <<'EOF'
你是 **OpenClaw V3 Supervisor Agent**，唯一控制中心。

## 架构原则
- 本地模型 = 控制流（分类、路由、调度）
- 云端模型 = 计算流（复杂推理、代码生成）
- 你只做控制，不直接执行计算。

## 任务 DAG 生成规范（复杂任务必须执行）
对于复杂任务，第一步始终派发给 `planner-agent` 生成 Task DAG，格式如下：
```json
{
  "tasks": [
    {"id": "t1", "description": "...", "dependencies": [], "assignedAgent": "..."},
    {"id": "t2", "description": "...", "dependencies": ["t1"], "assignedAgent": "..."}
  ]
}
```
然后按依赖顺序派发任务。

## 通信协议（必须遵守）
派发子 Agent 时，通过 sessions_spawn 传递 JSON 结构：
```json
{
  "from": "supervisor",
  "to": "agent-id",
  "taskId": "t1",
  "action": "execute",
  "payload": {"description": "...", "context": "..."}
}
```
子 Agent 必须返回：
```json
{
  "from": "agent-id",
  "to": "supervisor",
  "taskId": "t1",
  "status": "done",
  "result": "..."
}
```

## Agent 生命周期
子 Agent 按 init → plan → act → reflect → report 流程响应。

## 可用 Agent
- **planner-agent**：生成 Task DAG
- **memory-agent**：检索/写入记忆
- **tool-agent**：执行工具
- **expert-code**：代码生成
- **expert-verify**：质量验证（Critic）
- 其他云端专家按需调用
EOF
  echo "✅ 编排器 System Prompt 已写入 ~/.openclaw/agents/main/AGENTS.md"

  # 10. 为其他子 Agent 写入默认 AGENTS.md（若不存在）
  python3 - "$HOME/.openclaw/agents" "$agent_json" <<'PY'
import json, sys, os
from pathlib import Path
base = Path(sys.argv[1])
agents = json.loads(sys.argv[2])
for a in agents:
    aid = a['id']
    if aid == 'main':
        continue
    adir = base / aid
    adir.mkdir(parents=True, exist_ok=True)
    prompt_file = adir / 'AGENTS.md'
    if not prompt_file.exists():
        prompt_file.write_text(f"# {a.get('label', aid)}\n\n你是 {a.get('label', aid)}，绑定模型 {a['model']}。\n\n只处理能力范围内的问题，返回结构化 JSON。\n", encoding='utf-8')
PY

  echo "✅ 多Agent配置已增量更新（原 API Key 已保留）"
}

# ── 一键多Agent部署入口 ──
openclaw_apply_multi_agent_architecture() {
  local tier force_flag="${1:-false}" cloud_model="" config_file tmp_json
  tier=$(openclaw_detect_hardware_tier 2>/dev/null || echo "entry-cpu")
  [ -z "$tier" ] && tier="entry-cpu"

  echo "🏗️ 正在部署多Agent多模型架构..."
  echo "   硬件分级: $tier"

  # 确保Ollama已安装
  openclaw_install_ollama_runtime || {
    echo "⚠️ Ollama 安装失败，多Agent架构需要本地模型"
    return 1
  }

  # 确保OpenClaw已安装
  if ! command -v openclaw >/dev/null 2>&1; then
    echo "⚠️ OpenClaw 未安装，无法部署多Agent架构"
    return 1
  fi

  # ── 检测是否有云端模型可用 ──
  config_file=$(openclaw_get_config_file)
  if [ -f "$config_file" ] && [ -s "$config_file" ]; then
    tmp_json=$(mktemp /tmp/openclaw_cloud_detect_XXXXXX.json)
    openclaw_json5_to_json "$config_file" "$tmp_json" 2>/dev/null || echo '{}' > "$tmp_json"
    cloud_model=$(python3 - "$tmp_json" 2>/dev/null <<'PY'
import json, sys
from pathlib import Path
cfg = {}
try: cfg = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
except: pass
# 检查 agents.defaults.model.primary
primary = (cfg.get('agents', {})).get('defaults', {}).get('model', {}).get('primary', '')
# 检查是否有非ollama的provider（云服务商）
providers = (cfg.get('models', {})).get('providers', {})
cloud_providers = [k for k in providers if k not in ('ollama',)]
if primary and not primary.startswith('ollama/'):
    print(primary)
elif cloud_providers:
    # 有云服务商但primary不是cloud的：尝试从provider提取首个模型
    for cp in cloud_providers:
        prov = providers.get(cp, {})
        models = prov.get('models', [])
        if models and isinstance(models, list):
            m = models[0]
            mid = m.get('id', '') if isinstance(m, dict) else str(m)
            if mid:
                print(f"{cp}/{mid}")
                break
PY
)
    rm -f "$tmp_json"
    if [ -n "$cloud_model" ]; then
      echo "   ☁️ 检测到云端模型: $cloud_model"
    fi
  fi

  # ── 自动拉取多Agent所需的本地模型 ──
  openclaw_multi_agent_pull_models "$tier" || echo "⚠️ 部分模型拉取失败，将使用已有模型继续"

  # ── 自动备份当前配置 ──
  if [ -f "$config_file" ] && [ -s "$config_file" ]; then
    local bak_file="$HOME/.openclaw/openclaw.json.bak.$(date +%s)"
    cp "$config_file" "$bak_file" 2>/dev/null && echo "✅ 已备份配置到 $bak_file"
  fi

  # ===== 预创建所有 Agent 工作区 =====
  echo "📁 创建 Agent 工作区目录..."
  local agent_ids=("main" "planner-agent" "memory-agent" "tool-agent" "expert-code" "expert-arch" "expert-reasoning" "expert-research" "expert-security" "expert-verify" "expert-writing" "expert-data" "expert-vision")
  for aid in "${agent_ids[@]}"; do
    local ws_dir="$HOME/.openclaw/agents/${aid}/workspace"
    mkdir -p "$ws_dir/memory"
    touch "$ws_dir/MEMORY.md"
    echo "   ✅ ${aid} 工作区已创建"
  done
  ln -sf "$HOME/.openclaw/workspace/skills" "$HOME/.openclaw/agents/main/workspace/skills" 2>/dev/null || true

  # 生成并写入多Agent配置
  openclaw_write_multi_agent_config "$tier" "$cloud_model" "$force_flag" || return 1

  # 重启网关使配置生效
  openclaw_apply_and_restart
}

# ── 多Agent所需模型自动拉取 ──
openclaw_multi_agent_pull_models() {
  local tier="$1"
  echo "⬇️ 正在拉取多Agent架构所需的本地模型..."
  echo "   硬件分级: $tier"

  openclaw_ensure_ollama_running >/dev/null 2>&1 || {
    echo "⚠️ Ollama 服务未就绪，跳过模型拉取"
    return 1
  }

  local pulled=0 failed=0 total_models=0

  _pull_if_needed() {
    local label="$1" model="$2" pull_timeout="${3:-600}"
    total_models=$((total_models + 1))
    if ollama list 2>/dev/null | grep -qF "$model"; then
      echo "   ✅ $label ($model) 已存在"
      return 0
    fi
    echo "   ⬇️ [$((pulled + failed + 1))] 拉取 $label ($model)... (超时=${pull_timeout}秒)"
    if timeout "$pull_timeout" ollama pull "$model" >/dev/null 2>&1; then
      echo "   ✅ $label 拉取成功"
      pulled=$((pulled + 1))
      return 0
    else
      local rc=$?
      if [ "$rc" -eq 124 ]; then
        echo "   ⚠️ $label 拉取超时(>$pull_timeout 秒)，跳过"
      else
        echo "   ⚠️ $label 拉取失败(exit=$rc)，跳过"
      fi
      failed=$((failed + 1))
      return 1
    fi
  }

  # 所有tier通用的基础模型
  _pull_if_needed "基础文本" "qwen3:0.6b"
  _pull_if_needed "基础代码" "qwen2.5-coder:1.5b"
  _pull_if_needed "记忆检索" "qwen2.5:7b"

  case "$tier" in
    golden-gpu)
      _pull_if_needed "编排器" "qwen3:1.8b"
      _pull_if_needed "高级文本" "qwen2.5:14b"
      _pull_if_needed "高级代码" "qwen2.5-coder:7b"
      _pull_if_needed "高级多模态" "gemma3:12b"
      ;;
    advanced-gpu|entry-gpu)
      _pull_if_needed "编排器" "qwen3:1.8b"
      _pull_if_needed "进阶文本" "qwen2.5:7b"
      _pull_if_needed "进阶代码" "qwen2.5-coder:7b"
      _pull_if_needed "基础多模态" "gemma3:4b"
      ;;
    advanced-cpu)
      _pull_if_needed "编排器" "qwen3:1.8b"
      _pull_if_needed "进阶文本" "qwen2.5:7b"
      _pull_if_needed "进阶代码" "qwen2.5-coder:7b"
      ;;
    entry-cpu|*)
      # entry-cpu 仅需基础模型（已在上面拉取）
      ;;
  esac

  echo "   模型拉取完成: $pulled 个成功, $failed 个失败 (共 $total_models 个)"
  if [ "$failed" -gt 0 ]; then
    echo "   ⚠️ 部分模型拉取失败不影响 Agent 创建，Agent 会使用已下载的模型"
    echo "   📌 后续可在「OpenClaw 面板 → 模型管理 → 拉取推荐模型」中手动重试"
  fi
  [ "$failed" -eq 0 ] && return 0 || return 1
}

# ── 获取硬件分级（安装时一次性运行）──
openclaw_detect_hardware_tier() {
  python3 <<'PY'
import subprocess, os, sys

# 检测GPU
has_gpu = False
gpu_mem_mb = 0
try:
    out = subprocess.check_output(
        ['nvidia-smi', '--query-gpu=memory.total', '--format=csv,noheader'],
        text=True, timeout=5, stderr=subprocess.DEVNULL
    ).strip()
    if out:
        gpu_mem_mb = int(out.replace('MiB','').replace('MB','').strip())
        has_gpu = True
except: pass

# 检测系统内存
mem_mb = 0
try:
    with open('/proc/meminfo') as f:
        for l in f:
            if l.startswith('MemTotal:'):
                mem_mb = int(l.split()[1]) // 1024
                break
except: pass

# 检测CPU核心数
cpu_cores = os.cpu_count() or 1

# WSL检测
is_wsl = False
try:
    with open('/proc/version') as f:
        if 'microsoft' in f.read().lower():
            is_wsl = True
except: pass

# 分级逻辑
if has_gpu and gpu_mem_mb >= 8000:
    tier = 'golden-gpu'
elif has_gpu and gpu_mem_mb >= 4000:
    tier = 'advanced-gpu'
elif has_gpu and gpu_mem_mb >= 2000:
    tier = 'entry-gpu'
elif mem_mb >= 16000 and cpu_cores >= 8:
    tier = 'advanced-cpu'
else:
    tier = 'entry-cpu'

if is_wsl:
    # WSL下GPU可能被误检测，保守处理
    if gpu_mem_mb < 4000 and tier.startswith('golden'):
        tier = 'advanced-gpu'

print(tier)
PY
}

openclaw_postinstall_acceptance_check() {
    echo "开始执行安装后验收检查..."
    if openclaw_has_command openclaw; then
      echo "✅ openclaw 命令存在"
    else
      echo "❌ openclaw 命令不存在"
    fi
    if openclaw_has_command ollama; then
      echo "✅ ollama 命令存在"
      openclaw_ensure_ollama_running >/dev/null 2>&1 && echo "✅ ollama 服务可访问" || echo "⚠️ ollama 已安装，但服务未就绪"
    else
      echo "⚠️ ollama 未安装"
    fi
    openclaw_memory_local_retrieval_status
    if openclaw_has_command openclaw; then
      if openclaw_memory_cli_supported; then
        echo "✅ OpenClaw memory CLI 可用"
      else
        echo "ℹ️ 当前 OpenClaw 版本未提供 memory CLI，记忆面板已降级为配置态视图"
      fi
      timeout 10 openclaw models status >/dev/null 2>&1 && echo "✅ OpenClaw 模型状态可读取" || echo "⚠️ OpenClaw 模型状态读取失败"
      timeout 10 openclaw models list --provider ollama >/dev/null 2>&1 && echo "✅ OpenClaw 可读取 Ollama 模型目录" || echo "⚠️ OpenClaw 无法读取 Ollama 模型目录"
      timeout 10 openclaw doctor >/dev/null 2>&1 && echo "✅ openclaw doctor 可执行" || echo "⚠️ openclaw doctor 返回异常"
    fi
}

openclaw_full_local_stack_setup() {
    echo "🚀 开始执行一键完整本地落地..."
    openclaw_runtime_self_heal || return 1
    openclaw_install_ollama_runtime || return 1
    openclaw_ollama_pull_recommended_model "text" || echo "⚠️ 文本模型安装跳过"
    openclaw_ollama_pull_recommended_model "image" || echo "⚠️ 视觉模型安装跳过"
    openclaw_ollama_pull_recommended_model "code" || echo "⚠️ 代码模型安装跳过"
    openclaw_apply_multi_agent_architecture "true" || return 1
    openclaw_memorysearch_loop_self_heal || return 1
    openclaw_inject_skills || return 1
    openclaw_optimize_memory_and_skills || return 1
    openclaw_memory_enable_local_retrieval || return 1
    openclaw_apply_and_restart || true
    openclaw_postinstall_acceptance_check || true
    echo "✅ 一键完整本地落地完成"
}

openclaw_memory_prepare_layered_local_models() {
    local profile_json tier text_model code_model vision_model want_vision is_wsl=false
    # 清除过期的拉取失败缓存，确保本次运行会重新尝试下载
    if [ -f "$SKPL_OLLAMA_PULL_CACHE_FILE" ]; then
      local cache_age
      cache_age=$(python3 - "$SKPL_OLLAMA_PULL_CACHE_FILE" <<'PY' 2>/dev/null || echo "99999"
import json, sys, time
from pathlib import Path
try:
    data = json.loads(Path(sys.argv[1]).read_text(encoding='utf-8'))
    newest = 0
    for role_data in (data.values() if isinstance(data, dict) else []):
        if isinstance(role_data, dict):
            for item in role_data.values():
                if isinstance(item, dict):
                    newest = max(newest, int(item.get('updatedAt',0) or 0))
    age = int(time.time()) - newest if newest > 0 else 99999
    print(age)
except Exception:
    print(99999)
PY
)
      if [ "${cache_age:-0}" -gt 300 ]; then
        echo "   🧹 模型拉取缓存已过期，清除后重新尝试..."
        rm -f "$SKPL_OLLAMA_PULL_CACHE_FILE"
      fi
    fi
    echo "   正在检测硬件配置..."
    # WSL环境快速通路：避免GPU检测卡顿
    if grep -qi "microsoft\|WSL" /proc/sys/kernel/osrelease 2>/dev/null || [ -n "$WSL_DISTRO_NAME" ]; then
      is_wsl=true
      echo "   ⚡ WSL环境检测: 使用快速CPU配置"
      profile_json='{"tier":"entry-cpu"}'
    else
      profile_json=$(openclaw_detect_hardware_profile_json 2>/dev/null) || profile_json='{"tier":"entry-cpu"}'
    fi
    tier=$(python3 - "$profile_json" <<'PY' 2>/dev/null || echo 'entry-cpu'
import json, sys
print((json.loads(sys.argv[1]) or {}).get('tier', 'entry-cpu'))
PY
)
    want_vision="${1:-false}"

    case "$tier" in
      server|workstation|flagship-gpu|golden-gpu)
        text_model="qwen2.5:14b"
        code_model="qwen2.5-coder:7b"
        vision_model="gemma3:12b"
        ;;
      advanced-gpu|advanced-cpu-plus|advanced-cpu)
        text_model="qwen2.5:7b"
        code_model="qwen2.5-coder:7b"
        vision_model="gemma3:4b"
        ;;
      entry-gpu|entry-cpu)
        text_model="qwen3:0.6b"
        code_model="qwen2.5-coder:1.5b"
        vision_model="gemma3:4b"
        ;;
      *)
        text_model="qwen3:0.6b"
        code_model="qwen2.5-coder:1.5b"
        vision_model="gemma3:4b"
        ;;
    esac

    # WSL低配环境：跳过大型视觉模型以加快启动，避免网络超时
    if $is_wsl; then
      echo "ℹ️ WSL环境: 跳过视觉模型下载以加快启动速度"
      echo "   (视觉模型可通过菜单手动下载: 模型管理 → 拉取推荐模型 → image)"
      want_vision=false
    fi

    echo "🧠 正在按硬件分级准备本地专家模型..."
    echo "   分级: $tier"
    echo "   文本模型: $text_model"
    echo "   代码模型: $code_model"
    [ "$want_vision" = "true" ] && echo "   视觉模型: $vision_model"

    openclaw_install_ollama_runtime || return 1
    # 根据硬件分级构建回退链：WSL/低配用更小模型，高配用更大模型
    local text_fallbacks code_fallbacks
    case "$tier" in
      server|workstation|flagship-gpu|golden-gpu)
        text_fallbacks=("qwen2.5:7b" "qwen3:4b" "qwen2.5:3b")
        code_fallbacks=("qwen2.5-coder:1.5b" "qwen2.5-coder:3b" "deepseek-coder:6.7b")
        ;;
      advanced-gpu|advanced-cpu-plus|advanced-cpu)
        text_fallbacks=("qwen3:4b" "qwen2.5:3b" "qwen2.5:1.5b")
        code_fallbacks=("qwen2.5-coder:3b" "qwen2.5-coder:1.5b" "deepseek-coder:1.3b")
        ;;
      entry-gpu|entry-cpu|*)
        text_fallbacks=("qwen2.5:1.5b" "llama3.2:1b" "qwen2.5:0.5b")
        code_fallbacks=("qwen2.5-coder:0.5b" "qwen2.5-coder:1.5b" "deepseek-coder:1.3b")
        ;;
    esac
    if openclaw_ollama_pull_first_available "text" "$text_model" "${text_fallbacks[@]}"; then
      text_model="${OPENCLAW_LAST_PULLED_MODEL:-$text_model}"
    else
      echo "⚠️ 文本模型拉取失败，将以无本地模型模式继续"
      $is_wsl && echo "   WSL环境请确保: ollama serve 已运行，网络可访问 registry.ollama.ai"
      text_model=""
    fi
    if [ "$code_model" != "$text_model" ] && [ -n "$code_model" ]; then
      if openclaw_ollama_pull_first_available "code" "$code_model" "${code_fallbacks[@]}"; then
        code_model="${OPENCLAW_LAST_PULLED_MODEL:-$code_model}"
      else
        echo "⚠️ 代码模型拉取失败，将以文本模型替代"
        code_model="$text_model"
      fi
    else
      code_model="$text_model"
    fi
    if [ "$want_vision" = "true" ]; then
      if openclaw_ollama_pull_first_available "image" "$vision_model" "llava:7b" "minicpm-v"; then
        vision_model="${OPENCLAW_LAST_PULLED_MODEL:-$vision_model}"
      else
        echo "⚠️ 视觉模型不可用，视觉功能将被禁用"
        vision_model=""
      fi
    fi

    python3 - "$(openclaw_get_config_file)" "$text_model" "$code_model" "$vision_model" "$want_vision" <<'PY'
import json, sys
from pathlib import Path

path = Path(sys.argv[1])
text_model, code_model, vision_model, want_vision = sys.argv[2:6]
cfg = {}
if path.exists():
    try:
        cfg = json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        cfg = {}

agents = cfg.setdefault('agents', {}).setdefault('defaults', {})
agents.setdefault('workspace', '~/.openclaw/workspace')
agents.setdefault('model', {})['primary'] = f'ollama/{text_model}'
agents.setdefault('models', {})
agents['models'].setdefault(f'ollama/{text_model}', {})
agents['models'].setdefault(f'ollama/{code_model}', {})
if want_vision == 'true':
    agents['imageModel'] = {'primary': f'ollama/{vision_model}'}
    agents['models'].setdefault(f'ollama/{vision_model}', {})

path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps(cfg, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
PY
    echo "✅ 本地分层专家模型已就绪"
}

openclaw_runtime_self_heal() {
    echo "🔧 正在检查 OpenClaw 运行依赖..."
    install curl ca-certificates jq sqlite3 python3 git tar zstd >/dev/null 2>&1
    ensure_node_runtime || return 1
    mkdir -p "$HOME/.openclaw" "$HOME/.openclaw/models/embedding" "$HOME/.openclaw/workspace/skills"
    echo "✅ 基础运行依赖已就绪"
}

openclaw_ollama_status() {
    if ! openclaw_has_command ollama; then
      echo "本地运行时: 未安装 ollama"
      return 0
    fi
    if ollama list >/dev/null 2>&1; then
      echo "本地运行时: ollama 已就绪"
    else
      echo "本地运行时: ollama 已安装，服务未就绪"
    fi
}

openclaw_ollama_endpoint_ready() {
    if ! openclaw_has_command curl; then
      return 1
    fi
    curl -fsS --connect-timeout 2 --max-time 5 http://127.0.0.1:11434/api/tags >/dev/null 2>&1
}

openclaw_detect_proxy_env() {
    # 检测系统代理配置，返回适合传递给子进程的代理环境变量
    # 优先级：HTTPS_PROXY > https_proxy > HTTP_PROXY > http_proxy > socks5_proxy > all_proxy
    local proxy_vars=""
    for var in HTTPS_PROXY https_proxy HTTP_PROXY http_proxy SOCKS5_PROXY socks5_proxy ALL_PROXY all_proxy; do
      if [ -n "${!var:-}" ]; then
        # 如果有代理但OLLAMA_PROXY未设置的话，确保不传给ollama本地调用
        # 但传给外网下载命令
        proxy_vars="${proxy_vars}export ${var}=${!var}; "
      fi
    done
    printf '%s' "$proxy_vars"
}

openclaw_resolve_ollama_bin() {
    if command -v ollama >/dev/null 2>&1; then
      command -v ollama
      return 0
    fi
    if [ -x /usr/local/bin/ollama ]; then
      printf '%s\n' /usr/local/bin/ollama
      return 0
    fi
    if [ -x /usr/bin/ollama ]; then
      printf '%s\n' /usr/bin/ollama
      return 0
    fi
    return 1
}

_openclaw_ollama_proxy_warn() {
    local user_proxy="${HTTP_PROXY:-${http_proxy:-}}${HTTPS_PROXY:-${https_proxy:-}}${ALL_PROXY:-${all_proxy:-}}"
    [ -z "$user_proxy" ] && return 0
    local ollama_pid
    ollama_pid=$(pgrep -f "ollama serve" 2>/dev/null | head -n 1)
    [ -z "$ollama_pid" ] && return 0
    local env_file="/proc/$ollama_pid/environ"
    [ -r "$env_file" ] || return 0
    if tr '\0' '\n' < "$env_file" 2>/dev/null | grep -qE '^(HTTP_PROXY|HTTPS_PROXY|ALL_PROXY)='; then
        return 0
    fi
    echo "⚠️ 已设置代理但运行中的 ollama serve (PID $ollama_pid) 未继承代理"
    echo "   模型下载速度可能受限。建议执行:"
    echo "   kill $ollama_pid && env HTTP_PROXY=$HTTP_PROXY HTTPS_PROXY=$HTTPS_PROXY ollama serve &"
}

# 检测代理是否存活：尝试 TCP 连接代理地址，3 秒超时
_openclaw_proxy_is_alive() {
    local proxy_url="${1:-}"
    [ -z "$proxy_url" ] && return 1
    # 提取 host:port，支持 http://127.0.0.1:7890 格式
    local host_port
    host_port=$(printf '%s' "$proxy_url" | sed -n 's|^https\?://||; s|/$||; s|^\[\(.*\)\]|\1|; p')
    [ -z "$host_port" ] && return 1
    local host="${host_port%:*}"
    local port="${host_port##*:}"
    [ -z "$port" ] || [ "$port" = "$host_port" ] && return 1
    timeout 3 bash -c "echo >/dev/tcp/$host/$port" 2>/dev/null
}

# 获取当前有效的代理环境变量（优先 HTTP_PROXY）
_openclaw_effective_proxy() {
    printf '%s' "${HTTP_PROXY:-${http_proxy:-${HTTPS_PROXY:-${https_proxy:-${ALL_PROXY:-${all_proxy:-}}}}}}"
}

openclaw_ensure_ollama_running() {
    local ollama_bin
    if openclaw_ollama_endpoint_ready; then
      echo "✅ ollama 服务已就绪"
      _openclaw_ollama_proxy_warn
      return 0
    fi

    ollama_bin=$(openclaw_resolve_ollama_bin 2>/dev/null || true)
    if [ -z "$ollama_bin" ]; then
      echo "⚠️ 未找到 ollama 可执行文件"
      return 1
    fi

    if command -v systemctl >/dev/null 2>&1; then
      systemctl enable ollama >/dev/null 2>&1 || true
      systemctl start ollama >/dev/null 2>&1 || true
      sleep 2
      if openclaw_ollama_endpoint_ready; then
        echo "✅ 已通过 systemd 启动 ollama"
        return 0
      fi
    fi

    if pgrep -f "ollama serve" >/dev/null 2>&1; then
      sleep 2
      if openclaw_ollama_endpoint_ready; then
        echo "✅ ollama serve 已在运行"
        _openclaw_ollama_proxy_warn
        return 0
      fi
    fi

    nohup env HTTP_PROXY="${HTTP_PROXY:-${http_proxy:-}}" HTTPS_PROXY="${HTTPS_PROXY:-${https_proxy:-}}" ALL_PROXY="${ALL_PROXY:-${all_proxy:-}}" "$ollama_bin" serve >/tmp/ollama-serve.log 2>&1 &
    disown 2>/dev/null || true
    sleep 3
    if openclaw_ollama_endpoint_ready; then
      echo "✅ 已启动 ollama serve"
      return 0
    fi

    echo "⚠️ ollama 服务尚未就绪，请检查 /tmp/ollama-serve.log，然后手动执行: $ollama_bin serve"
    return 1
}

openclaw_install_ollama_runtime() {
    if openclaw_has_command ollama; then
      echo "✅ ollama 已安装"
      openclaw_ensure_ollama_running || true
      return 0
    fi
    openclaw_ensure_ollama_install_tools || return 1

    # ── 代理检测 ──
    local _install_proxy _install_retry=0 _install_rc=0 _install_max_retry=2
    _install_proxy=$(_openclaw_effective_proxy)
    if [ -n "$_install_proxy" ] && _openclaw_proxy_is_alive "$_install_proxy"; then
      echo "🌐 检测到代理 $_install_proxy，将使用代理加速下载"
    elif [ -n "$_install_proxy" ]; then
      echo "⚠️ 代理 $_install_proxy 不可达，将直连下载（可能较慢）"
      _install_proxy=""
    else
      echo "💡 未检测到代理，直连 ollama.com 下载可能很慢"
      echo "   如需加速，请先设置代理: export HTTP_PROXY=http://127.0.0.1:7890 HTTPS_PROXY=http://127.0.0.1:7890"
      echo "   然后重新运行本脚本"
    fi
    echo ""

    # ── 带重试的下载安装 ──
    while [ "$_install_retry" -le "$_install_max_retry" ]; do
      if [ "$_install_retry" -gt 0 ]; then
        echo "🔄 第 $_install_retry 次重试安装 ollama..."
        sleep 3
      else
        echo "⬇️ 正在安装 ollama 本地模型运行时（二进制包约 1GB+，请耐心等待）..."
      fi

      if [ -n "$_install_proxy" ]; then
        if env HTTP_PROXY="$_install_proxy" HTTPS_PROXY="$_install_proxy" \
           curl -fsSL --max-time 120 https://ollama.com/install.sh | \
           env HTTP_PROXY="$_install_proxy" HTTPS_PROXY="$_install_proxy" sh; then
          _install_rc=0; break
        else
          _install_rc=$?
        fi
      else
        if curl -fsSL --max-time 120 https://ollama.com/install.sh | sh; then
          _install_rc=0; break
        else
          _install_rc=$?
        fi
      fi
      _install_retry=$((_install_retry + 1))
    done

    if [ "$_install_rc" -eq 0 ]; then
      echo "✅ ollama 安装完成"
      openclaw_ensure_ollama_running || true
    else
      echo "❌ ollama 安装失败 (exit=$_install_rc)"
      echo ""
      echo "💡 手动安装方案:"
      echo "   1. 设置代理后重试: export HTTP_PROXY=http://127.0.0.1:7890 && bash 本脚本"
      echo "   2. 手动下载安装: curl -fsSL https://ollama.com/install.sh | sh"
      echo "   3. 从 GitHub Releases 下载: https://github.com/ollama/ollama/releases"
      return 1
    fi
}

openclaw_ollama_pull_model() {
    local model_name="$1"
    [ -z "$model_name" ] && return 1
    if ! skpl_validate_model_name "$model_name"; then
      echo "❌ 非法模型名，已拒绝: $model_name" >&2
      return 1
    fi
    openclaw_install_ollama_runtime || return 1
    openclaw_ensure_ollama_running || return 1
    echo "⬇️ 正在拉取本地模型: $model_name"
    local _om_pull_retry=0 _om_pull_rc=0 _om_pull_err
    local _om_proxy=$(_openclaw_effective_proxy)
    local _om_proxy_bypass=false
    if [ -n "$_om_proxy" ] && ! _openclaw_proxy_is_alive "$_om_proxy"; then
      echo "⚠️ 代理 $_om_proxy 不可用，自动绕过直连下载"
      _om_proxy_bypass=true
    fi
    while [ "$_om_pull_retry" -le 2 ]; do
      if [ "$_om_proxy_bypass" = "true" ]; then
        _om_pull_err=$(timeout 600 env HTTP_PROXY="" HTTPS_PROXY="" ALL_PROXY="" ollama pull "$model_name" 2>&1)
      elif [ -n "$_om_proxy" ]; then
        _om_pull_err=$(timeout 600 env HTTP_PROXY="$_om_proxy" HTTPS_PROXY="$_om_proxy" ollama pull "$model_name" 2>&1)
      else
        _om_pull_err=$(timeout 600 ollama pull "$model_name" 2>&1)
      fi
      _om_pull_rc=$?
      [ "$_om_pull_rc" -eq 0 ] && break
      if printf '%s' "$_om_pull_err" | grep -qiE 'unexpected EOF|connection reset|timeout|broken pipe'; then
        _om_pull_retry=$((_om_pull_retry + 1))
        [ "$_om_pull_retry" -le 2 ] && { echo "🔄 网络瞬断，自动重试 ($_om_pull_retry/2)..."; sleep 3; }
      else
        break
      fi
    done
    [ "$_om_pull_rc" -ne 0 ] && return 1
    local model_role="text"
    case "$model_name" in
      *coder*) model_role="code" ;;
      *vl*|*vision*|*llava*|*minicpm-v*) model_role="image" ;;
    esac
    openclaw_configure_local_ollama_provider "$model_name" "$model_role" || true
    echo "✅ 本地模型已就绪: $model_name"
}

openclaw_ollama_cache_status_get() {
    local model_role="$1"
    local model_name="$2"
    local ttl="${3:-21600}"
    python3 - "$SKPL_OLLAMA_PULL_CACHE_FILE" "$model_role" "$model_name" "$ttl" <<'PY'
import json, sys, time
from pathlib import Path

path = Path(sys.argv[1])
role = sys.argv[2]
model = sys.argv[3]
ttl = int(sys.argv[4])
if not path.exists():
    raise SystemExit(1)
try:
    data = json.loads(path.read_text(encoding='utf-8'))
except Exception:
    raise SystemExit(1)
item = (((data.get(role) or {}) if isinstance(data, dict) else {}).get(model) or {})
updated_at = int(item.get('updatedAt', 0) or 0)
if not item or updated_at <= 0:
    raise SystemExit(1)
if int(time.time()) - updated_at > ttl:
    raise SystemExit(1)
print(f"{item.get('status', '')}\t{item.get('note', '')}")
PY
}

openclaw_ollama_cache_status_set() {
    local model_role="$1"
    local model_name="$2"
    local status_text="$3"
    local note_text="$4"
    python3 - "$SKPL_OLLAMA_PULL_CACHE_FILE" "$model_role" "$model_name" "$status_text" "$note_text" <<'PY'
import json, sys, time
from pathlib import Path

path = Path(sys.argv[1])
role, model, status, note = sys.argv[2:6]
data = {}
if path.exists():
    try:
        data = json.loads(path.read_text(encoding='utf-8'))
    except Exception:
        data = {}
if not isinstance(data, dict):
    data = {}
role_data = data.get(role)
if not isinstance(role_data, dict):
    role_data = {}
    data[role] = role_data
role_data[model] = {
    'status': status,
    'note': note,
    'updatedAt': int(time.time()),
}
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
PY
}

# ─── 模型显存安全检查 ───
# 估算模型显存需求（基于量化后大小，单位MB）
skpl_estimate_model_vram_mb() {
  local model_name="$1"
  local name_lower
  name_lower=$(echo "$model_name" | tr '[:upper:]' '[:lower:]')
  [ -z "$name_lower" ] && echo 4000 && return 1
  # 4-bit 量化模型显存估算 (参数B × ~500MB + KV缓存等开销)
  case "$name_lower" in
    *"70b"*|*"72b"*) echo 36000 ;;
    *"30b"*|*"32b"*) echo 17000 ;;
    *"16b"*|*"15b"*|*"14b"*|*"13b"*)  echo 7200 ;;
    *"11b"*|*"12b"*)  echo 6600 ;;
    *"8b"*)  echo 5530 ;;
    *"7b"*)  echo 5325 ;;
    *"6.7b"*)  echo 4100 ;;
    *"4.7b"*)  echo 3000 ;;
    *"4b"*)  echo 2600 ;;
    *"3.8b"*)  echo 2400 ;;
    *"3.2b"*)  echo 2100 ;;
    *"3b"*)  echo 1950 ;;
    *"2b"*)  echo 1300 ;;
    *"1.8b"*)  echo 1200 ;;
    *"1.5b"*)  echo 1000 ;;
    *"1.3b"*)  echo 900 ;;
    *"1b"*)  echo 750 ;;
    *"0.8b"*)  echo 600 ;;
    *"0.6b"*)  echo 500 ;;
    *"0.5b"*)  echo 420 ;;
    *"0.3b"*)  echo 310 ;;
    *)  echo 4000 ;;
  esac
}

# 检查模型是否适合当前显存 (使用配置中的reserveGpuMb)
skpl_check_model_vram_fit() {
  local model_name="$1"
  local need_mb reserve_mb available_mb
  need_mb=$(skpl_estimate_model_vram_mb "$model_name")
  reserve_mb=200  # 与budget.reserveGpuMb对齐，预留200MB给系统和KV缓存

  # 获取可用显存
  available_mb=$(python3 - <<'PY'
import subprocess, json, re, sys
try:
    out = subprocess.check_output(['nvidia-smi', '--query-gpu=memory.free', '--format=csv,noheader,nounits'], text=True, timeout=5).strip()
    free_mb = int(out.split()[0]) if out else 0
    print(free_mb)
except Exception:
    print(0)
PY
  )

  if [ "$available_mb" -eq 0 ]; then
    echo "⚠️ 警告: 无法检测 GPU 显存，模型可能无法运行"
    return 2  # 返回 2 表示无法确定
  fi

  if [ "$((available_mb - reserve_mb))" -lt "$need_mb" ]; then
    echo "⚠️ 显存不足: $model_name 需要约 ${need_mb}MB，当前可用 ${available_mb}MB（预留${reserve_mb}MB后仅 $((available_mb - reserve_mb))MB）"
    return 1
  fi
  return 0
}

# 用户确认下载
skpl_confirm_model_download() {
  local model_name="$1" model_role="$2"
  local need_mb need_gb
  need_mb=$(skpl_estimate_model_vram_mb "$model_name")
  need_gb=$(python3 -c "print(round($need_mb / 1024, 1))" 2>/dev/null || echo "?.?")

  echo ""
  echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
  echo "  模型下载确认"
  echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
  echo "  角色: $model_role"
  echo "  模型: $model_name"
  echo "  预计显存: 约 ${need_mb}MB (${need_gb}GB)"

  # 显示显存信息
  local available_mb
  available_mb=$(python3 - <<'PY'
import subprocess
try:
    out = subprocess.check_output(['nvidia-smi', '--query-gpu=memory.free', '--format=csv,noheader,nounits'], text=True, timeout=5).strip()
    print(out.split()[0] if out else '未知')
except Exception:
    print('未知')
PY
  )
  echo "  当前可用显存: ${available_mb}MB"

  # 检查是否匹配
  local vram_status
  vram_status=$(skpl_check_model_vram_fit "$model_name" 2>&1)
  if [ $? -ne 0 ]; then
    echo "$vram_status"
    echo ""
    echo "  ❌ 该模型可能无法在当前 GPU 上运行！"
    echo "  建议选择更小的模型。"
    echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
    echo ""
    read -e -p "  仍然要下载? (y/N): " confirm
    [[ "$confirm" == [yY] ]] && return 0
    return 1
  fi

  echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
  echo ""
  read -e -p "  确认下载 $model_name? (y/N): " confirm
  [ -z "$confirm" ] && confirm="n"
  [[ "$confirm" != [yY] ]] && return 1
  return 0
}

openclaw_ollama_model_exists_local() {
    local model_name="$1"
    [ -z "$model_name" ] && return 1
    openclaw_has_command ollama || return 1
    timeout 10 ollama list 2>/dev/null | awk 'NR>1 {print $1}' | grep -Fx "$model_name" >/dev/null 2>&1
}

openclaw_ollama_runtime_hint() {
    local version_text
    version_text=$(timeout 8 ollama --version 2>/dev/null | head -n 1)
    [ -n "$version_text" ] && echo "ℹ️ 当前 Ollama 版本: $version_text"
    # 代理与下载速度提示
    local user_proxy="${HTTP_PROXY:-${http_proxy:-}}${HTTPS_PROXY:-${https_proxy:-}}${ALL_PROXY:-${all_proxy:-}}"
    if [ -z "$user_proxy" ]; then
        echo "💡 下载慢？设置代理可加速: export HTTP_PROXY=http://127.0.0.1:7890 HTTPS_PROXY=http://127.0.0.1:7890"
        echo "   （端口号请根据实际代理工具调整：Clash=7890, v2ray=10809）"
    else
        echo "🌐 已检测到代理设置: ${HTTP_PROXY:-$https_proxy}"
        local ollama_pid
        ollama_pid=$(pgrep -f "ollama serve" 2>/dev/null | head -n 1)
        if [ -n "$ollama_pid" ] && [ -r "/proc/$ollama_pid/environ" ]; then
            if ! tr '\0' '\n' < "/proc/$ollama_pid/environ" 2>/dev/null | grep -qE '^(HTTP_PROXY|HTTPS_PROXY)='; then
                echo "⚠️ 代理已设置但 ollama serve 未继承，下载将不走代理！"
                echo "   请重启 ollama: kill $ollama_pid && env HTTP_PROXY=$HTTP_PROXY ollama serve &"
            fi
        fi
    fi
}

openclaw_ollama_pull_first_available() {
    local model_role="$1"
    shift
    local model_name="" cached_status cached_note cache_line pull_timeout=600 max_attempts=3 attempts=0
    OPENCLAW_LAST_PULLED_MODEL=""
    # WSL环境：延长超时适应国内网络，增加可尝试的备选模型数
    if grep -qi "microsoft\|WSL" /proc/sys/kernel/osrelease 2>/dev/null || [ -n "$WSL_DISTRO_NAME" ]; then
      pull_timeout=900
      max_attempts=5
    fi
    openclaw_install_ollama_runtime || return 1
    openclaw_ensure_ollama_running || return 1
    openclaw_ollama_runtime_hint || true
    for model_name in "$@"; do
      [ -z "$model_name" ] && continue
      attempts=$((attempts + 1))
      if [ "$attempts" -gt "$max_attempts" ]; then
        echo "⚠️ 已达到最大尝试次数($max_attempts)，跳过剩余备选模型"
        break
      fi
      if openclaw_ollama_model_exists_local "$model_name"; then
        OPENCLAW_LAST_PULLED_MODEL="$model_name"
        openclaw_ollama_cache_status_set "$model_role" "$model_name" "local" "模型已存在于本地"
        openclaw_configure_local_ollama_provider "$model_name" "$model_role" || true
        echo "✅ 已复用本地$model_role模型: $model_name"
        return 0
      fi
      cache_line=$(openclaw_ollama_cache_status_get "$model_role" "$model_name" 300 2>/dev/null || true)
      cached_status=$(printf '%s' "$cache_line" | awk -F '\t' '{print $1}')
      cached_note=$(printf '%s' "$cache_line" | awk -F '\t' '{print $2}')
      if [ "$cached_status" = "failed" ]; then
        echo "⏭️ 跳过最近失败的$model_role模型: $model_name ${cached_note:+($cached_note)}"
        continue
      fi
      echo "⬇️ 尝试拉取本地$model_role模型: $model_name"
      echo "   模型下载可能需要几分钟，请耐心等待..."
      if ! skpl_confirm_model_download "$model_name" "$model_role"; then
        echo "⏭️ 用户取消下载: $model_name"
        openclaw_ollama_cache_status_set "$model_role" "$model_name" "skipped" "用户取消"
        continue
      fi
      # --- 代理检测与自适应绕过 ---
      local pull_proxy_effective proxy_bypass=false
      pull_proxy_effective=$(_openclaw_effective_proxy)
      if [ -n "$pull_proxy_effective" ]; then
        if _openclaw_proxy_is_alive "$pull_proxy_effective"; then
          echo "🌐 代理 $pull_proxy_effective 已连接，将通过代理下载"
        else
          echo "⚠️ 检测到代理 $pull_proxy_effective 但无法连接（connection refused）"
          echo "   自动绕过代理直连下载（速度可能较慢但可用）"
          proxy_bypass=true
        fi
      fi
      # --- 拉取 + 断点续传重试（针对 unexpected EOF） ---
      local pull_retry=0 pull_max_retry=2 pull_err pull_rc=0
      while [ "$pull_retry" -le "$pull_max_retry" ]; do
        if [ "$proxy_bypass" = "true" ]; then
          pull_err=$(timeout "$pull_timeout" env HTTP_PROXY="" HTTPS_PROXY="" ALL_PROXY="" ollama pull "$model_name" 2>&1)
        elif [ -n "$pull_proxy_effective" ]; then
          pull_err=$(timeout "$pull_timeout" env HTTP_PROXY="$pull_proxy_effective" HTTPS_PROXY="$pull_proxy_effective" ollama pull "$model_name" 2>&1)
        else
          pull_err=$(timeout "$pull_timeout" ollama pull "$model_name" 2>&1)
        fi
        pull_rc=$?
        # 判断是否为可恢复的网络瞬断（断点续传场景）
        if printf '%s' "$pull_err" | grep -qiE 'unexpected EOF|connection reset|timeout|broken pipe'; then
          pull_retry=$((pull_retry + 1))
          if [ "$pull_retry" -le "$pull_max_retry" ]; then
            echo "🔄 检测到网络瞬断（已下载部分将保留），自动重试 ($pull_retry/$pull_max_retry)..."
            sleep 3
          fi
        else
          break
        fi
      done
      if [ "$pull_rc" -eq 0 ]; then
        OPENCLAW_LAST_PULLED_MODEL="$model_name"
        openclaw_ollama_cache_status_set "$model_role" "$model_name" "ok" "拉取成功"
        openclaw_configure_local_ollama_provider "$model_name" "$model_role" || true
        echo "✅ 已选定本地$model_role模型: $model_name"
        return 0
      fi
      # 如果是代理错误且尚未尝试绕过，标记为可能是代理问题
      if printf '%s' "$pull_err" | grep -qiE 'proxyconnect|connection refused.*127\\.0\\.0\\.1|no such host'; then
        openclaw_ollama_cache_status_set "$model_role" "$model_name" "failed" "代理不通，建议 unset HTTP_PROXY 后重试"
        echo "❌ 代理不通导致下载失败，请检查代理或执行: unset HTTP_PROXY HTTPS_PROXY"
        # 不继续尝试下一个模型——代理不通的话全都会失败
        return 1
      fi
      openclaw_ollama_cache_status_set "$model_role" "$model_name" "failed" "当前运行时未成功拉取"
      echo "⚠️ 当前模型不可用，继续尝试下一个: $model_name"
    done
    echo "❌ 未找到可用的本地$model_role模型"
    return 1
}

openclaw_ollama_pull_recommended_model() {
    local role="$1"
    local profile_json tier selected_model
    profile_json=$(openclaw_detect_hardware_profile_json)
    tier=$(python3 - "$profile_json" <<'PY'
import json, sys
print((json.loads(sys.argv[1]) or {}).get('tier', 'entry-cpu'))
PY
)
    case "$role" in
      text)
        case "$tier" in
          server|workstation|flagship-gpu|golden-gpu)
            openclaw_ollama_pull_first_available "text" "qwen3:8b" "qwen2.5:7b" "llama3.1:8b"
            ;;
          advanced-gpu|advanced-cpu-plus|advanced-cpu)
            openclaw_ollama_pull_first_available "text" "qwen2.5:3b" "qwen3:4b" "llama3.2:3b"
            ;;
          entry-gpu|entry-cpu)
            openclaw_ollama_pull_first_available "text" "qwen3:0.6b" "qwen2.5:1.5b" "llama3.2:1b"
            ;;
          *)
            openclaw_ollama_pull_first_available "text" "qwen3:0.6b" "llama3.2:1b"
            ;;
        esac
        selected_model="$OPENCLAW_LAST_PULLED_MODEL"
        [ -n "$selected_model" ] && OPENCLAW_TEXT_MODEL_RESOLVED="ollama/$selected_model"
        ;;
      code)
        case "$tier" in
          server|workstation)
            openclaw_ollama_pull_first_available "code" "qwen2.5-coder:1.5b" "deepseek-coder-v2:16b" "qwen2.5-coder:7b"
            ;;
          flagship-gpu)
            openclaw_ollama_pull_first_available "code" "qwen2.5-coder:1.5b" "qwen2.5-coder:7b" "deepseek-coder:6.7b"
            ;;
          golden-gpu)
            openclaw_ollama_pull_first_available "code" "qwen2.5-coder:7b" "deepseek-coder:6.7b" "qwen2.5-coder:1.5b"
            ;;
          advanced-gpu|advanced-cpu-plus|advanced-cpu)
            openclaw_ollama_pull_first_available "code" "qwen2.5-coder:1.5b" "deepseek-coder:1.3b"
            ;;
          *)
            openclaw_ollama_pull_first_available "code" "qwen2.5-coder:1.5b" "deepseek-coder:1.3b"
            ;;
        esac
        selected_model="$OPENCLAW_LAST_PULLED_MODEL"
        [ -n "$selected_model" ] && OPENCLAW_CODE_MODEL_RESOLVED="ollama/$selected_model"
        ;;
      image)
        openclaw_ollama_pull_first_available "image" "gemma3:4b" "llava:7b" "minicpm-v"
        selected_model="$OPENCLAW_LAST_PULLED_MODEL"
        [ -n "$selected_model" ] && OPENCLAW_IMAGE_MODEL_RESOLVED="ollama/$selected_model"
        ;;
      *)
        echo "❌ 未知模型角色: $role"
        return 1
        ;;
    esac
}

openclaw_ollama_quick_setup_menu() {
    while true; do
      clear
      skpl_ui_header "本地模型运行时" "安装 ollama 并准备本地文本/代码模型"
      openclaw_ollama_status
      echo
      skpl_ui_section "推荐模型"
      skpl_ui_menu_item 1 "qwen2.5:7b" "稳妥的本地通用文本模型，适合大多数设备"
      skpl_ui_menu_item 2 "qwen2.5-coder:1.5b" "本地代码模型，优先用于开发辅助"
      skpl_ui_menu_item 3 "qwen2.5-coder:7b" "备用代码模型，适合兼容旧配置"
      skpl_ui_menu_item 4 "mistral:7b" "通用备选模型"
      skpl_ui_menu_item 5 "自定义模型" "手动输入任意 ollama 模型名"
      skpl_ui_menu_item 6 "仅安装运行时" "只安装 ollama，不拉取模型"
      skpl_ui_menu_item 0 "返回上一级"
      skpl_ui_footer_prompt "请选择: "
      read -e ollama_choice
      case "$ollama_choice" in
        1)
          openclaw_ollama_pull_recommended_model "text"
          break_end
          ;;
        2)
          openclaw_ollama_pull_recommended_model "code"
          break_end
          ;;
        3)
          openclaw_ollama_pull_model "qwen2.5-coder:7b"
          break_end
          ;;
        4)
          openclaw_ollama_pull_model "mistral:7b"
          break_end
          ;;
        5)
          read -e -p "请输入 ollama 模型名: " custom_ollama_model
          [ -n "$custom_ollama_model" ] && openclaw_ollama_pull_model "$custom_ollama_model"
          break_end
          ;;
        6)
          openclaw_install_ollama_runtime
          break_end
          ;;
        0)
          return 0
          ;;
        *)
          echo "无效的选择，请重试。"
          sleep 1
          ;;
      esac
    done
}

  openclaw_memory_local_retrieval_status() {
    local provider model_path model_status backend
    backend=$(openclaw_memory_get_backend)
    provider="config-only"
    model_path=$(openclaw_memory_expand_path "$(openclaw_memory_get_local_model_path)")
    model_status=$(openclaw_memory_local_model_status "$model_path")
    echo "记忆后端: ${backend:-unknown}"
    echo "检索提供者: ${provider:-unset}"
    echo "本地向量模型: ${model_path:-未配置}"
    case "$model_status" in
      ok) echo "模型状态: 已就绪" ;;
      hf) echo "模型状态: 使用远端 hf: 引用" ;;
      *) echo "模型状态: 未就绪" ;;
    esac
  }

