  openclaw_memory_file_collect() {
    OPENCLAW_MEMORY_FILES=()
    OPENCLAW_MEMORY_FILE_LABELS=()
    local agent_lines agent_id base_dir memory_dir memory_file rel
    agent_lines=$(openclaw_memory_list_agents)
    while IFS=$'\t' read -r agent_id base_dir; do
      [ -z "$agent_id" ] && continue
      memory_dir="$base_dir/memory"
      memory_file="$base_dir/MEMORY.md"
      if [ -f "$memory_file" ]; then
        OPENCLAW_MEMORY_FILES+=("$memory_file")
        OPENCLAW_MEMORY_FILE_LABELS+=("$agent_id/MEMORY.md")
      fi
      if [ -d "$memory_dir" ]; then
        while IFS= read -r file; do
          [ -f "$file" ] || continue
          rel="${file#$base_dir/}"
          OPENCLAW_MEMORY_FILES+=("$file")
          OPENCLAW_MEMORY_FILE_LABELS+=("$agent_id/$rel")
        done < <(find "$memory_dir" -type f -name '*.md' | sort)
      fi
    done <<EOF
$agent_lines
EOF
  }

  openclaw_memory_file_render_list() {
    openclaw_memory_file_collect
    if [ ${#OPENCLAW_MEMORY_FILES[@]} -eq 0 ]; then
      skpl_ui_alert "info" "未找到记忆文件" "当前工作区下没有可浏览的 MEMORY.md 或 memory/*.md 文件。"
      return 0
    fi
    skpl_ui_section "文件清单"
    echo "编号 | 归属 | 大小 | 修改时间"
    skpl_ui_rule "$gl_hui" "─" 60
    local i file rel size mtime
    for i in "${!OPENCLAW_MEMORY_FILES[@]}"; do
      file="${OPENCLAW_MEMORY_FILES[$i]}"
      rel="${OPENCLAW_MEMORY_FILE_LABELS[$i]}"
      size=$(ls -lh "$file" | awk '{print $5}')
      mtime=$(date -d "$(stat -c %y "$file")" '+%Y-%m-%d %H:%M:%S' 2>/dev/null || stat -c %y "$file" | awk '{print $1" "$2}')
      printf "%s | %s | %s | %s\\n" "$((i+1))" "$rel" "$size" "$mtime"
    done
  }

  openclaw_memory_view_file() {
    local file="$1"
    [ -f "$file" ] || {
      echo "❌ 文件不存在: $file"
      return 1
    }
    local total_lines
    total_lines=$(wc -l < "$file" 2>/dev/null || echo 0)
    local default_lines=120
    local start_line count
    skpl_ui_header "记忆文件预览" "按行号抽样查看文件内容"
    skpl_ui_kv "文件" "$file"
    skpl_ui_kv "总行数" "$total_lines"
    read -e -p "请输入起始行（回车默认末尾 $default_lines 行）: " start_line
    read -e -p "请输入显示行数（回车默认 $default_lines）: " count
    [ -z "$count" ] && count=$default_lines
    if [ -z "$start_line" ]; then
      if [ "$total_lines" -le "$count" ]; then
        start_line=1
      else
        start_line=$((total_lines - count + 1))
      fi
    fi
    if ! [[ "$start_line" =~ ^[0-9]+$ ]] || ! [[ "$count" =~ ^[0-9]+$ ]]; then
      echo "❌ 请输入有效的数字。"
      return 1
    fi
    if [ "$start_line" -lt 1 ]; then
      start_line=1
    fi
    if [ "$count" -le 0 ]; then
      echo "❌ 行数必须大于 0。"
      return 1
    fi
    local end_line=$((start_line + count - 1))
    if [ "$end_line" -gt "$total_lines" ]; then
      end_line=$total_lines
    fi
    if [ "$total_lines" -eq 0 ]; then
      echo "(空文件)"
      return 0
    fi
    echo
    skpl_ui_section "内容"
    skpl_ui_rule "$gl_hui" "─" 60
    sed -n "${start_line},${end_line}p" "$file"
    skpl_ui_rule "$gl_hui" "─" 60
  }

  openclaw_memory_files_menu() {
    while true; do
      clear
      skpl_ui_header "记忆文件" "浏览 MEMORY.md 与 memory 目录内的 Markdown 内容"
      openclaw_memory_file_render_list
      echo
      skpl_ui_footer_prompt "请输入文件编号查看（0 返回）: "
      read -e file_choice
      if [ "$file_choice" = "0" ]; then
        return 0
      fi
      if ! [[ "$file_choice" =~ ^[0-9]+$ ]]; then
        skpl_ui_alert "warn" "无效的选择" "请输入列表中的数字编号。"
        sleep 1
        continue
      fi
      openclaw_memory_file_collect
      if [ ${#OPENCLAW_MEMORY_FILES[@]} -eq 0 ]; then
        read -p "未找到记忆文件，按回车返回..."
        return 0
      fi
      local idx=$((file_choice-1))
      if [ "$idx" -lt 0 ] || [ "$idx" -ge ${#OPENCLAW_MEMORY_FILES[@]} ]; then
        skpl_ui_alert "warn" "编号超出范围" "请从当前文件列表中重新选择。"
        sleep 1
        continue
      fi
      openclaw_memory_view_file "${OPENCLAW_MEMORY_FILES[$idx]}"
      read -p "按回车返回列表..."
      done
  }


openclaw_memory_search_test() {
  read -e -p "输入搜索关键词: " query
  if [ -z "$query" ]; then
    echo "关键词不能为空。"
    return 1
    fi
  echo "正在搜索记忆..."
  timeout 30 openclaw memory search "$query" --max-results 5 2>/dev/null || true
}

# Unified memory search - combines official OpenClaw memory and SKPL extension memory
openclaw_memory_unified_search() {
  local query="$1" max_results="${2:-5}"
  [ -z "$query" ] && return 1
  
  local native_raw hybrid_raw ext_raw
  # Search official OpenClaw memory
  native_raw=$(openclaw memory search "$query" --max-results "$max_results" 2>/dev/null || true)
  # Search hybrid memory (LanceDB + FTS5)
  hybrid_raw=$(hybrid_memory_search_raw_json "$query" 2>/dev/null || echo "[]")
  # Search extension memory (SQLite)
  ext_raw=$(memory_extension_search_json "$query" "$max_results" 2>/dev/null || echo "[]")
  
  python3 - "$query" "$native_raw" "$hybrid_raw" "$ext_raw" "$max_results" <<'PY'
import json
import sys
import re
from collections import defaultdict

query, native_raw, hybrid_raw, ext_raw, max_results = sys.argv[1:6]
max_results = int(max_results)

def normalize_text(text):
    """Normalize text for deduplication"""
    return re.sub(r'\s+', ' ', text.lower().strip())[:100]

# Parse native results (official OpenClaw memory)
native_results = []
for line in native_raw.splitlines():
    line = line.strip()
    if line and not line.startswith('['):
        native_results.append({
            'source': 'official',
            'type': 'native',
            'content': line,
            'normalized': normalize_text(line),
            'score': 1.0
        })

# Parse hybrid results
hybrid_results = []
try:
    hybrid_data = json.loads(hybrid_raw)
    for item in hybrid_data[:max_results]:
        content = item.get('summary', '') or item.get('content', '')
        if content:
            hybrid_results.append({
                'source': 'hybrid',
                'type': item.get('source', 'unknown'),
                'content': content,
                'normalized': normalize_text(content),
                'score': item.get('score', 0.5),
                'channels': item.get('channels', [])
            })
except Exception:
    pass

# Parse extension results
ext_results = []
try:
    ext_data = json.loads(ext_raw)
    for item in ext_data[:max_results]:
        content = f"{item.get('title', '')}: {item.get('content', '')}"
        if content.strip() != ':':
            ext_results.append({
                'source': 'extension',
                'type': item.get('category', 'memory'),
                'content': content,
                'normalized': normalize_text(content),
                'score': item.get('score', 0.5) / 100  # Normalize to 0-1
            })
except Exception:
    pass

# Deduplicate and merge results
seen = set()
merged = []

for result in native_results + hybrid_results + ext_results:
    norm = result['normalized']
    if norm and norm not in seen:
        seen.add(norm)
        merged.append(result)

# Sort by score (descending)
merged.sort(key=lambda x: x['score'], reverse=True)

# Output unified results
output = merged[:max_results]
print(json.dumps({
    'query': query,
    'total_found': len(merged),
    'returned': len(output),
    'sources': list(set(r['source'] for r in output)),
    'results': output
}, ensure_ascii=False))
PY
}

openclaw_memory_compare_search_test() {
  local query
  read -e -p "输入检索对照关键词: " query
  if [ -z "$query" ]; then
    echo "关键词不能为空。"
    return 1
  fi
  echo "正在执行统一记忆搜索..."
  local unified_result
  unified_result=$(openclaw_memory_unified_search "$query" 5)
  
  python3 - "$unified_result" <<'PY'
import json
import sys

data = json.loads(sys.argv[1])

print('===== 统一记忆检索结果 =====')
print(f"查询: {data.get('query')}")
print(f"总计命中: {data.get('total_found')} | 返回: {data.get('returned')}")
print(f"来源: {', '.join(data.get('sources', []))}")
print('')

results = data.get('results', [])
if not results:
    print('未命中任何记忆。')
else:
    for idx, item in enumerate(results, start=1):
        print(f"{idx}. [{item.get('source', '-')}/{item.get('type', '-')}] score={item.get('score', 0):.3f}")
        print(f"   {item.get('content', '-')[:120]}...")
        if item.get('channels'):
            print(f"   channels: {','.join(item['channels'])}")
        print('')
PY
}

