import sqlite3
import sys
import datetime

conn = sqlite3.connect(sys.argv[1])
row = conn.execute('select id, category, title, content, tags, sensitive, created_at, updated_at from memory_entries where deleted = 0 and id = ? limit 1', (sys.argv[2],)).fetchone()
