  openclaw_find_webui_domain() {
    local cache_ttl="30"

    if [ -s "$SKPL_WEBUI_DOMAIN_CACHE_FILE" ] && openclaw_memory_cache_fresh "$SKPL_WEBUI_DOMAIN_CACHE_FILE" "$cache_ttl"; then
      cat "$SKPL_WEBUI_DOMAIN_CACHE_FILE"
      return 0
    fi

    if [ -s "$SKPL_WEBUI_DOMAIN_CACHE_FILE" ]; then
      cat "$SKPL_WEBUI_DOMAIN_CACHE_FILE"
    fi
  }

  openclaw_webui_extract_token() {
    python3 - <<'PY'
import re
import sys

text = sys.stdin.read()
patterns = [
    r'[#&?]token=([^\s"\'"'"'&>]+)',
    r'\btoken\s*[:=]\s*([^\s"\'"'"'&>]+)',
]

for pattern in patterns:
    match = re.search(pattern, text, re.IGNORECASE)
    if match:
        print(match.group(1))
        raise SystemExit(0)

raise SystemExit(1)
PY
  }

  openclaw_webui_scheme() {
    local config_file
    config_file=$(openclaw_get_config_file)
    python3 - "$config_file" <<'PY'
import json
import os
import sys

path = sys.argv[1]
scheme = 'http'
try:
    if path and os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if isinstance(data, dict) and data.get('gateway', {}).get('tls', {}).get('enabled') is True:
            scheme = 'https'
except Exception:
    pass
print(scheme)
PY
  }

  openclaw_webui_token_from_config() {
    local config_file
    config_file=$(openclaw_get_config_file)
    python3 - "$config_file" <<'PY'
import json
import os
import sys
from pathlib import Path

path = sys.argv[1]
home = Path.home()

def emit(value):
    if isinstance(value, str):
        value = value.strip()
        if value and not value.startswith('${'):
            print(value)
            raise SystemExit(0)

for env_name in ('OPENCLAW_GATEWAY_TOKEN', 'OPENCLAW_WEBUI_TOKEN', 'GATEWAY_AUTH_TOKEN'):
    emit(os.environ.get(env_name, ''))

config_candidates = []
if path:
    config_candidates.append(Path(path))
config_candidates.extend([
    home / '.openclaw' / 'openclaw.json',
    Path('/root/.openclaw/openclaw.json'),
])

seen = set()
for candidate in config_candidates:
    candidate = candidate.expanduser()
    if str(candidate) in seen or not candidate.exists():
        continue
    seen.add(str(candidate))
    try:
        data = json.loads(candidate.read_text(encoding='utf-8'))
    except Exception:
        continue
    if not isinstance(data, dict):
        continue
    gateway = data.get('gateway', {})
    auth = gateway.get('auth', {}) if isinstance(gateway, dict) else {}
    for value in (
        auth.get('token') if isinstance(auth, dict) else None,
        auth.get('accessToken') if isinstance(auth, dict) else None,
        gateway.get('token') if isinstance(gateway, dict) else None,
    ):
        emit(value)

for candidate in (
    home / '.openclaw' / 'gateway.token',
    home / '.openclaw' / 'gateway-auth-token',
    home / '.openclaw' / 'workspace' / '.gateway-token',
    Path('/root/.openclaw/gateway.token'),
    Path('/root/.openclaw/gateway-auth-token'),
):
    if candidate.exists():
        try:
            emit(candidate.read_text(encoding='utf-8'))
        except Exception:
            continue

raise SystemExit(1)
PY
  }

openclaw_webui_refresh_token_cache() {
    local dashboard_output token

    token=$(openclaw_webui_token_from_config 2>/dev/null || true)
    if [ -n "$token" ]; then
      printf '%s' "$token" > "$SKPL_WEBUI_TOKEN_CACHE_FILE"
      echo "$token"
      return 0
    fi

    dashboard_output=$(timeout 12 openclaw dashboard --no-open 2>/dev/null || true)
    if [ -n "$dashboard_output" ]; then
      token=$(printf '%s\n' "$dashboard_output" | openclaw_webui_extract_token 2>/dev/null || true)
      if [ -n "$token" ]; then
        printf '%s' "$token" > "$SKPL_WEBUI_TOKEN_CACHE_FILE"
        echo "$token"
        return 0
      fi
    fi

    return 1
  }

openclaw_webui_ensure_origins() {
    return 0
  }

  openclaw_webui_ensure_local_origins() {
    return 0
  }

  openclaw_webui_get_cached_token() {
    if [ -s "$SKPL_WEBUI_TOKEN_CACHE_FILE" ]; then
      cat "$SKPL_WEBUI_TOKEN_CACHE_FILE"
      return 0
    fi
    return 1
  }

  openclaw_webui_reset_local_cache() {
    : > "$SKPL_WEBUI_TOKEN_CACHE_FILE" 2>/dev/null || true
    : > "$SKPL_WEBUI_DOMAIN_CACHE_FILE" 2>/dev/null || true
  }



  openclaw_show_webui_addr() {
    local local_ip token domains scheme port

    skpl_ui_header "WebUI 入口与待审批请求" "本机访问优先，可记录已有域名入口"
    local_ip="127.0.0.1"
    scheme=$(openclaw_webui_scheme)
    port=$(openclaw_gateway_port)

    token=$(openclaw_webui_token_from_config 2>/dev/null || openclaw_webui_get_cached_token 2>/dev/null || true)
    skpl_ui_section "本机地址"
    if [ -n "$token" ]; then
      echo "${scheme}://${local_ip}:${port}/#token=${token}"
    else
      echo "${scheme}://${local_ip}:${port}/"
      echo "当前使用无 token 的本地入口，可在菜单中按需手动刷新 token。"
    fi

    domains=$(openclaw_find_webui_domain)
    if [ -n "$domains" ]; then
      echo
      skpl_ui_section "域名地址"
      while IFS= read -r d; do
        [ -z "$d" ] && continue
        if [ -n "$token" ]; then
          echo "${d}/#token=${token}"
        else
          echo "${d}/"
        fi
      done <<EOF
$domains
EOF
    fi

    echo
    skpl_ui_section "待处理设备授权"
    echo "当前面板提供待处理请求查看。批准请在 root 终端手动执行官方命令。"
  }



  openclaw_webui_normalize_domain_entry() {
    local raw="$1"
    raw="${raw#http://}"
    raw="${raw#https://}"
    raw="${raw%%/*}"
    raw="${raw%%#*}"
    raw="${raw%%\?*}"
    printf '%s' "$raw"
  }

  # 添加域名入口记录
  openclaw_domain_webui() {
    local raw_domain domain_entry scheme token

    scheme=$(openclaw_webui_scheme)
    read -e -p "请输入已存在的 WebUI 域名或 URL: " raw_domain
    [ -z "$raw_domain" ] && { echo "❌ 未输入域名或 URL"; return 1; }

    domain_entry=$(openclaw_webui_normalize_domain_entry "$raw_domain")
    [ -z "$domain_entry" ] && { echo "❌ 域名格式无效"; return 1; }

    mkdir -p "$(dirname "$SKPL_WEBUI_DOMAIN_CACHE_FILE")"
    printf '%s\n' "${scheme}://${domain_entry}" >> "$SKPL_WEBUI_DOMAIN_CACHE_FILE"
    python3 - "$SKPL_WEBUI_DOMAIN_CACHE_FILE" <<'PY'
import sys
from pathlib import Path

path = Path(sys.argv[1])
path.parent.mkdir(parents=True, exist_ok=True)
if not path.exists():
    path.write_text('', encoding='utf-8')
items = []
seen = set()
for raw in path.read_text(encoding='utf-8', errors='ignore').splitlines():
    item = raw.strip()
    if not item or item in seen:
        continue
    seen.add(item)
    items.append(item)
path.write_text('\n'.join(items) + ('\n' if items else ''), encoding='utf-8')
PY
    echo -e "${gl_kjlan}已记录域名 ${domain_entry} 的 WebUI 入口${gl_bai}"

    : > "$SKPL_DEVICES_LIST_CACHE_FILE" 2>/dev/null || true
    if ! openclaw_devices_list_safe; then
      echo "❌ 设备列表加载超时或失败，请确认网关已就绪后重试。"
      return 1
    fi

    token=$(openclaw_webui_token_from_config 2>/dev/null || openclaw_webui_get_cached_token 2>/dev/null || true)
    echo
    echo "访问地址:"
    if [ -n "$token" ]; then
      echo "${scheme}://${domain_entry}/#token=${token}"
    else
      echo "${scheme}://${domain_entry}/"
    fi
    echo "请在 root 终端手动执行官方命令进行审批。"
    echo "建议步骤："
    echo "1. 复制上面 devices list 中当前有效的 requestId"
    echo "2. 手动执行: openclaw devices approve <requestId>"
    return 0

  }

  # 删除域名
  openclaw_remove_domain() {
    local domains target domain_entry found=0

    domains=$(openclaw_find_webui_domain)
    if [ -z "$domains" ]; then
      echo "当前没有已记录的域名入口。"
      return 0
    fi

    echo "已记录的域名入口:"
    printf '%s\n' "$domains"
    read -e -p "请输入要移除的域名或完整 URL: " target
    [ -z "$target" ] && { echo "❌ 未输入域名或 URL"; return 1; }

    domain_entry=$(openclaw_webui_normalize_domain_entry "$target")
    python3 - "$SKPL_WEBUI_DOMAIN_CACHE_FILE" "$domain_entry" <<'PY'
import sys
from pathlib import Path

path = Path(sys.argv[1])
target = sys.argv[2].strip()
if not path.exists():
    raise SystemExit(1)

items = []
removed = False
for raw in path.read_text(encoding='utf-8', errors='ignore').splitlines():
    item = raw.strip()
    if not item:
        continue
    normalized = item.removeprefix('http://').removeprefix('https://').split('/', 1)[0]
    if normalized == target:
        removed = True
        continue
    items.append(item)

path.write_text('\n'.join(items) + ('\n' if items else ''), encoding='utf-8')
raise SystemExit(0 if removed else 1)
PY
    found=$?
    if [ "$found" -eq 0 ]; then
      echo "✅ 已移除域名入口: $domain_entry"
    else
      echo "❌ 未找到对应的已记录域名入口: $domain_entry"
      return 1
    fi
  }

  # 主菜单
  openclaw_webui_menu() {

    send_stats "WebUI访问与设置"
    while true; do
      clear
      openclaw_show_webui_addr
      echo
      skpl_ui_section "操作"
      skpl_ui_menu_item 1 "重载访问 Token" "读取本地持久 token"
      skpl_ui_menu_item 2 "记录已有域名入口" "保存已存在的 WebUI 域名地址"
      skpl_ui_menu_item_tone 3 "移除域名入口" "删除已记录的域名地址" "danger"
      skpl_ui_menu_item 4 "查看待处理请求" "显示 devices list 原始输出"
      skpl_ui_menu_item 0 "返回上一级"
      skpl_ui_footer_prompt "请选择: "
      read -e choice

      case "$choice" in
        1)
          if openclaw_webui_refresh_token_cache >/dev/null 2>&1; then
            echo "✅ WebUI Token 已重载"
          else
            echo "⚠️ Token 读取失败"
            openclaw_webui_token_status_hint
          fi
          echo
          read -p "按回车返回菜单..."
          ;;
        2)
          openclaw_domain_webui
          echo
          read -p "按回车返回菜单..."
          ;;
        3)
          openclaw_remove_domain
          read -p "按回车返回菜单..."
          ;;
        4)
          echo
          : > "$SKPL_DEVICES_LIST_CACHE_FILE" 2>/dev/null || true
          openclaw_devices_list_safe
          echo
          read -p "按回车返回菜单..."
          ;;
        0)
          break
          ;;
        *)
          echo "无效选项"
          sleep 1
          ;;
      esac
    done
  }



  # 主循环
  while true; do
    show_menu
    read -r choice
    case $choice in
      1) install_openclaw_panel ;;
      2) start_bot ;;
      3) stop_bot ;;
      4) view_logs ;;
      5) change_model ;;
      6) openclaw_api_manage_menu ;;
      7) change_tg_bot_code ;;
      8) install_plugin ;;
      9) install_skill ;;
      10) nano_openclaw_json ;;
      11) send_stats "初始化配置向导"
        openclaw_run_onboard_wizard
        break_end
        ;;
      12) send_stats "健康检测与修复"
        timeout 15 openclaw doctor --fix 2>/dev/null || true
        send_stats "OpenClaw API同步触发"
        if sync_openclaw_api_models; then
          openclaw_ensure_gateway_ready || start_gateway
        else
          echo "❌ API 模型同步失败，已中止重启网关。请检查 provider /models 返回后重试。"
        fi
        break_end
        ;;
      13) openclaw_webui_menu ;;
      14) send_stats "TUI命令行对话"
        openclaw tui
        break_end
        ;;
      15) openclaw_memory_menu ;;
      16) openclaw_permission_menu ;;
      17) openclaw_multiagent_menu ;;
      18) openclaw_backup_restore_menu ;;
      19) update_openclaw_panel ;;
      20) uninstall_openclaw_panel ;;
      0) return 0 ;;
      *) echo "无效的选择，请重试。"; sleep 1 ;;
    esac
  done

}

OPENCLAW_PANEL_EOF
)"
}

openclaw_enable_local_memory_auto() {
  local model_path bootstrap_log
  if declare -F openclaw_memory_prepare_prefetch >/dev/null 2>&1; then
    model_path="$(openclaw_memory_prepare_prefetch)"
  elif declare -F openclaw_default_memory_model_path >/dev/null 2>&1; then
    model_path="$(openclaw_default_memory_model_path)"
  else
    model_path="$HOME/.openclaw/models/embedding/embeddinggemma-300M-Q8_0.gguf"
    mkdir -p "$(dirname "$model_path")"
  fi

  if [ -f "${model_path}" ]; then
    echo "记忆模型已存在，安装阶段跳过后台预热。"
    return 0
  fi

  if declare -F openclaw_memory_prefetch_bootstrap >/dev/null 2>&1; then
    bootstrap_log="$(openclaw_memory_prefetch_bootstrap "$model_path")"
    echo "记忆模型将在后台预热下载，不阻塞安装流程。"
    echo "安装阶段不会提前切换到 Local 记忆方案。"
    echo "后台日志: ${bootstrap_log}"
  else
    echo "⚠️ 记忆预热函数不可用，已跳过后台预热。"
  fi
}

  install_openclaw_direct() {
  echo "开始直装 OpenClaw..."
  install git jq
  install_node_and_tools

  echo "正在安装 OpenClaw CLI..."
  install_openclaw_global
  if ! ensure_openclaw_cli_on_path >/dev/null 2>&1; then
    echo "OpenClaw CLI 安装失败：未检测到 openclaw 命令。"
    return 1
  fi

  if declare -F openclaw_onboard_if_needed >/dev/null 2>&1; then
    openclaw_onboard_if_needed
  else
    echo "⚠️ 未检测到 openclaw_onboard_if_needed，跳过首次引导。"
  fi
  openclaw_ensure_local_gateway_config >/dev/null 2>&1 || true
  if declare -F openclaw_webui_reset_local_cache >/dev/null 2>&1; then
    openclaw_webui_reset_local_cache
  else
    echo "⚠️ 未检测到 openclaw_webui_reset_local_cache，跳过 WebUI 本地缓存重置。"
  fi
  refresh_openclaw_gateway_service >/dev/null 2>&1 || true
  echo "提示：WebUI 首次浏览器访问可能需要设备审批。"
  echo "提示：WhatsApp 官方扫码登录完成后，请先执行 openclaw channels status 确认绑定状态。"

  if [ "${SKPL_BATCH_MODE:-0}" = "1" ]; then
    echo "批量安装模式：跳过第 2 步网关启动，交由下一步网络优化统一接管。"
    return 0
  fi

  if ! openclaw_ensure_gateway_ready; then
    echo "OpenClaw 网关启动校验未通过。"
    return 1
  fi

  return 0
}

run_openclaw_install_step() {
  prewarm_openclaw_dependencies
  ensure_openclaw_cli_on_path >/dev/null 2>&1 || true
  if ! command -v openclaw >/dev/null 2>&1 || ! openclaw --version >/dev/null 2>&1; then
    install_openclaw_direct
  fi

  ensure_openclaw_cli_on_path >/dev/null 2>&1 || true
  if ! command -v openclaw >/dev/null 2>&1; then
    echo "OpenClaw CLI 安装失败：未检测到 openclaw 命令。"
    return 1
  fi

  if declare -F openclaw_onboard_if_needed >/dev/null 2>&1; then
    openclaw_onboard_if_needed || true
  fi

  if command -v openclaw >/dev/null 2>&1; then
    openclaw config validate >/dev/null 2>&1 || openclaw_ensure_local_gateway_config >/dev/null 2>&1 || true
  fi

  refresh_runtime_proxy_env
  refresh_openclaw_gateway_service >/dev/null 2>&1 || true
  if ! openclaw_gateway_is_running; then
    openclaw_ensure_gateway_ready || true
  fi
}

run_openclaw2_network_optimization() {
  set +e
  echo "执行 openclaw2 网络优化（稳定模式）..."

  local openclaw_js
  refresh_runtime_proxy_env
  openclaw_js=$(resolve_openclaw_js_entry 2>/dev/null || true)

  if [ ! -f "$openclaw_js" ]; then
    npm_try_with_registries install -g openclaw@latest --no-fund --no-audit --loglevel=error --prefer-online --fetch-retries=2 --fetch-timeout=300000 >/dev/null 2>&1 || true
    openclaw_js=$(resolve_openclaw_js_entry 2>/dev/null || true)
  fi

  mkdir -p /root/.config/systemd/user
  mkdir -p /root/.openclaw/credentials /root/.openclaw/logs /root/.openclaw/agents
  chmod 700 /root/.openclaw 2>/dev/null || true

  openclaw_ensure_local_gateway_config >/dev/null 2>&1 || true

  loginctl enable-linger root >/dev/null 2>&1 || true
  openclaw_ensure_gateway_ready >/dev/null 2>&1 || true
  set -e
}

evomap_print_status() {
  local hybrid_json
  skpl_ui_kv "EvoMap 目录" "$EVOMAP_DIR"
  if [ -d "$EVOMAP_DIR" ]; then
    skpl_ui_kv "状态" "已安装"
    if evomap_is_running; then
      skpl_ui_kv "运行状态" "运行中（低优先级）"
    else
      skpl_ui_kv "运行状态" "未运行"
    fi
  else
    skpl_ui_kv "状态" "未安装"
  fi
  skpl_ui_kv "记忆目录" "$EVOMAP_MEMORY_DIR"
  skpl_ui_kv "同步根目录" "$SKPL_HYBRID_MEMORY_ROOT"
  hybrid_json=$(hybrid_memory_status_json 2>/dev/null || echo '{"objects":0}')
  skpl_ui_kv "知识对象" "$(python3 - <<'PY' "$hybrid_json"
import json, sys
try:
    data = json.loads(sys.argv[1])
    print(data.get('objects', 0))
except Exception:
    print(0)
PY
)"
  skpl_ui_kv "备份目录" "$EVOMAP_BACKUP_DIR"
}

hybrid_memory_search_test() {
  local query
  read -e -p "输入混合检索关键词: " query
  if [ -z "$query" ]; then
    echo "关键词不能为空。"
    return 1
  fi
  echo "正在执行混合检索..."
  hybrid_memory_search "$query"
}

evomap_backup_current() {
  mkdir -p "$EVOMAP_BACKUP_DIR"
  if [ -d "$EVOMAP_DIR" ]; then
    local backup_path
    backup_path="$EVOMAP_BACKUP_DIR/evolver.$(date +%Y%m%d%H%M%S).tgz"
    tar -czf "$backup_path" -C /root/.openclaw evolver
    echo "已备份 EvoMap: $backup_path"
  fi
}

evomap_is_running() {
  pgrep -f "node .*${EVOMAP_DIR}/index\.js --loop" >/dev/null 2>&1
}

evomap_stop_loop() {
  pkill -f "node .*${EVOMAP_DIR}/index\.js --loop" >/dev/null 2>&1 || true
}

evomap_start_loop() {
  local low_priority_prefix
  low_priority_prefix="$(skpl_low_priority_prefix)"
  evomap_stop_loop
  nohup bash -lc '
    set -e
    evomap_dir="$1"
    low_priority_prefix="$2"
    cd "$evomap_dir"
    exec ${low_priority_prefix}node "$evomap_dir/index.js" --loop
  ' _ "$EVOMAP_DIR" "$low_priority_prefix" > "$EVOMAP_DIR/nohup.out" 2>&1 &
  disown 2>/dev/null || true
}

evomap_refresh_gateway_if_needed() {
  if openclaw_gateway_is_running; then
    echo "OpenClaw 网关已运行，EvoMap 安装不主动重启网关，避免打断回复。"
  else
    echo "OpenClaw 网关未就绪，正在尝试启动。"
    start_gateway
  fi
}

evomap_install() {
  local node_id last_saved_node_id
  install git curl
  install sqlite3 python3 >/dev/null 2>&1
  mkdir -p /root/.openclaw

  if ! declare -F hybrid_memory_install_stack >/dev/null 2>&1; then
    echo "⚠️ 混合记忆栈函数不可用，跳过 EvoMap 安装。"
    return 0
  fi

  last_saved_node_id="$(state_get EVOMAP_NODE_ID)"
  if ! node_id="$(prompt_evomap_node_id "" "$last_saved_node_id")"; then
    return 1
  fi
  state_set EVOMAP_NODE_ID "$node_id"

  evomap_backup_current

  if [ -d "$EVOMAP_DIR" ]; then
    mv "$EVOMAP_DIR" "${EVOMAP_DIR}.old.$(date +%Y%m%d%H%M%S)"
  fi

  if ! timeout 180 git clone --depth 1 https://github.com/EvoMap/evolver.git "$EVOMAP_DIR" >/dev/null 2>&1; then
    echo "EvoMap 浅克隆失败，正在尝试一次受限完整克隆..."
    timeout 180 git clone https://github.com/EvoMap/evolver.git "$EVOMAP_DIR"
  fi
  cd "$EVOMAP_DIR"
  install_evomap_dependencies
  hybrid_memory_install_stack
  mkdir -p skills assets/gep memory "$SKPL_HYBRID_MEMORY_KNOWLEDGE_DIR/core"

  cat > .env <<EOF_ENV
MEMORY_DIR=${EVOMAP_MEMORY_DIR}
A2A_HUB_URL=https://evomap.ai
A2A_NODE_ID=${node_id}
EVOLVE_STRATEGY=balanced
HYBRID_MEMORY_ROOT=${SKPL_HYBRID_MEMORY_ROOT}
HYBRID_MEMORY_DB=${SKPL_HYBRID_MEMORY_DB}
EOF_ENV

  cat > assets/gep/openclaw-core-genes.json <<'EOF_GENE'
{"genes":[{"id":"openclaw-log-parser","name":"OpenClaw日志解析基因","version":"1.0.0","signals":["openclaw","gateway","session","learning","error","crash","timeout"],"directives":["优先解析OpenClaw日志","提取网关和会话错误信号","过滤无效内容并保留结构化数据"],"validation":[],"priority":100}]}
EOF_GENE

  cat > assets/gep/core-repair-capsules.json <<'EOF_CAP'
{"capsules":[{"id":"core-repair-kit","name":"核心修复胶囊","version":"1.0.0","targets":["agent-loop","execution-failure","stagnation"],"steps":["识别循环停滞并输出修复建议","识别执行错误并输出标准方案","生成可审计修复记录"]}]}
EOF_CAP

  if declare -F hybrid_memory_enqueue_event >/dev/null 2>&1; then
    hybrid_memory_enqueue_event "evomap-install" "EvoMap 与混合记忆栈安装完成"
  fi
  if declare -F hybrid_memory_sync_once >/dev/null 2>&1; then
    hybrid_memory_sync_once >/dev/null 2>&1 || true
  fi
  evomap_start_loop
  sleep 2
  evomap_refresh_gateway_if_needed

  echo "EvoMap 与混合记忆栈安装完成。"
}

evomap_uninstall() {
  evomap_stop_loop
  if [ -d "$EVOMAP_DIR" ]; then
    evomap_backup_current
    mv "$EVOMAP_DIR" "${EVOMAP_DIR}.removed.$(date +%Y%m%d%H%M%S)"
  fi
  echo "EvoMap 已卸载（目录已改名保留备份）。"
}

evomap_update() {
  if [ ! -d "$EVOMAP_DIR/.git" ]; then
    echo "EvoMap 未安装，先执行安装。"
    return 1
  fi
  if ! declare -F hybrid_memory_install_stack >/dev/null 2>&1; then
    echo "⚠️ 混合记忆栈函数不可用，跳过 EvoMap 更新。"
    return 0
  fi
  evomap_backup_current
  cd "$EVOMAP_DIR"
  git pull --rebase
  install_evomap_dependencies
  hybrid_memory_install_stack
  if declare -F hybrid_memory_enqueue_event >/dev/null 2>&1; then
    hybrid_memory_enqueue_event "evomap-update" "EvoMap 与混合记忆栈已更新"
  fi
  if declare -F hybrid_memory_sync_once >/dev/null 2>&1; then
    hybrid_memory_sync_once >/dev/null 2>&1 || true
  fi
  evomap_start_loop
  evomap_refresh_gateway_if_needed
  echo "EvoMap 与混合记忆栈更新完成。"
}

evomap_memory_menu() {
  while true; do
    clear
    skpl_ui_header "EvoMap 记忆管理" "查看学习目录、同步根目录与备份归档"
    evomap_print_status
    echo
    skpl_ui_section "操作"
    skpl_ui_menu_item 1 "立即备份 EvoMap"
    skpl_ui_menu_item 2 "查看记忆目录"
    skpl_ui_menu_item 3 "查看备份目录"
      skpl_ui_menu_item 4 "查看同步根目录"
    skpl_ui_menu_item 5 "查看同步日志"
    skpl_ui_menu_item 0 "返回上一级"
    skpl_ui_footer_prompt "请输入你的选择: "
    read -r evo_mem_choice
    case "$evo_mem_choice" in
      1) evomap_backup_current; break_end ;;
      2) ls -la "$EVOMAP_MEMORY_DIR" 2>/dev/null || echo "记忆目录不存在。"; break_end ;;
      3) ls -la "$EVOMAP_BACKUP_DIR" 2>/dev/null || echo "备份目录不存在。"; break_end ;;
      4) ls -la "$SKPL_HYBRID_MEMORY_ROOT" 2>/dev/null || echo "融合根目录不存在。"; break_end ;;
      5) hybrid_memory_show_sync_log; break_end ;;
      0) return 0 ;;
      *) echo "无效的选择，请重试。"; sleep 1 ;;
    esac
  done
}

run_evomap_install_step() {
  evomap_install
}

run_full_pipeline_once() {
  save_self_to_skpl
  init_skpl_runtime

  local SKPL_BATCH_MODE=1
  local step
  step=$(state_get STEP)
  [ -z "$step" ] && step=1

  if [ "$step" -le 1 ]; then
    echo "[1/5] 执行 wslwin 代理同步..."
    if ! run_step_guard "step1_wslwin" run_wslwin_proxy_sync; then
      print_failure_hint
      return 1
    fi
    state_set STEP 2
  fi

  step=$(state_get STEP)
  [ -z "$step" ] && step=2
  if [ "$step" -le 2 ]; then
    echo "[2/5] 安装 OpenClaw，并后台预热记忆模型资源..."
    if ! run_step_guard "step2_openclaw" run_openclaw_install_step; then
      print_failure_hint
      return 1
    fi
    state_set STEP 3
  fi

  step=$(state_get STEP)
  [ -z "$step" ] && step=3
  if [ "$step" -le 3 ]; then
    echo "[3/5] 执行 openclaw2 网络优化..."
    if ! run_step_guard "step3_openclaw2" run_openclaw2_network_optimization; then
      print_failure_hint
      return 1
    fi
    run_step_guard "step3_memory_fix" openclaw_enable_local_memory_auto || true
    state_set STEP 4
  fi

  step=$(state_get STEP)
  [ -z "$step" ] && step=4
  if [ "$step" -le 4 ]; then
    echo "[4/5] 初始化混合记忆栈..."
    if declare -F hybrid_memory_install_stack >/dev/null 2>&1; then
      if ! run_step_guard "step4_hybrid_memory" hybrid_memory_install_stack; then
        print_failure_hint
        return 1
      fi
      if declare -F hybrid_memory_enqueue_event >/dev/null 2>&1; then
        hybrid_memory_enqueue_event "install-pipeline" "OpenClaw 安装流程已完成混合记忆栈初始化"
      fi
      if declare -F hybrid_memory_sync_once >/dev/null 2>&1; then
        hybrid_memory_sync_once >/dev/null 2>&1 || true
      fi
    else
      echo "⚠️ 未检测到 hybrid_memory_install_stack，跳过混合记忆栈初始化。"
    fi
    state_set STEP 5
  fi

  step=$(state_get STEP)
  [ -z "$step" ] && step=5
  if [ "$step" -le 5 ]; then
    if [ "${SKPL_SKIP_EVOMAP:-0}" = "1" ]; then
      echo "[5/5] 已按 SKPL_SKIP_EVOMAP=1 跳过 EvoMap 安装。"
    else
      echo "[5/5] 安装 EvoMap 与融合学习能力..."
      if ! run_step_guard "step5_evomap" run_evomap_install_step; then
        print_failure_hint
        return 1
      fi
    fi
    state_set STEP 6
  fi

  echo "全部步骤执行完成。可使用 skpl 打开面板。"
}

rerun_full_pipeline_from_start() {
  state_reset_for_full_rerun
  run_full_pipeline_once
}

skpl_update_panel() {
  clear
  skpl_ui_header "面板更新"
  skpl_ui_kv "更新来源" "GitHub main"
  skpl_ui_kv "远程脚本" "$SKPL_REMOTE_SCRIPT_URL"
  echo
  if ! skpl_sync_remote_panel; then
    break_end
    return 1
  fi
  echo
  echo "正在重新载入最新面板..."
  export SKPL_SKIP_SELF_SAVE=1
  exec bash "${SKPL_SCRIPT_PATH}" panel
}

skpl_sync_workspace_panel_to_runtime() {
  if [ -f "/workspace/openclaw.json" ]; then
    install -m 755 "/workspace/openclaw.json" "${SKPL_SCRIPT_PATH}"
    echo "✅ 已将工作区脚本同步到运行时面板: ${SKPL_SCRIPT_PATH}"
  fi
}

skpl_update_system() {
  echo "开始更新系统软件包..."

  if command -v apt >/dev/null 2>&1; then
    DEBIAN_FRONTEND=noninteractive apt update -y >/dev/null 2>&1 || return 1
    DEBIAN_FRONTEND=noninteractive apt upgrade -y >/dev/null 2>&1 || return 1
    DEBIAN_FRONTEND=noninteractive apt autoremove -y >/dev/null 2>&1 || true
    echo "APT 系统更新完成。"
    return 0
  fi

  if command -v dnf >/dev/null 2>&1; then
    dnf upgrade -y >/dev/null 2>&1 || return 1
    echo "DNF 系统更新完成。"
    return 0
  fi

  if command -v yum >/dev/null 2>&1; then
    yum update -y >/dev/null 2>&1 || return 1
    echo "YUM 系统更新完成。"
    return 0
  fi

  echo "未识别的包管理器，无法自动更新系统。"
  return 1
}

skpl_wslwin_and_update_system() {
  if ! run_wslwin_proxy_sync; then
    return 1
  fi

  skpl_update_system
}

# ── Supervisor 架构切换 ──
# 获取当前架构状态显示字符串
skpl_supervisor_arch_status() {
    local cur
    cur=$(state_get OPENCLAW_USE_SUPERVISOR_ARCH 2>/dev/null || printf '0')
    if [ "$cur" = "1" ]; then
        printf 'Supervisor 新架构 (已激活)'
    else
        printf '智能路由旧架构 (默认)'
    fi
}

toggle_supervisor_arch() {
    local cur
    if ! command -v openclaw >/dev/null 2>&1; then
        echo "⚠️ OpenClaw 未安装，无法切换架构"
        echo "请先安装 OpenClaw 后再操作"
        break_end
        return 0
    fi
    cur=$(state_get OPENCLAW_USE_SUPERVISOR_ARCH)
    if [ "$cur" = "1" ]; then
        state_set OPENCLAW_USE_SUPERVISOR_ARCH 0
        echo "已切换回旧架构（智能路由）"
        echo "正在重启网关..."
    else
        # 检查多Agent架构是否已部署
        if [ ! -f "$HOME/.openclaw/agents/main/AGENTS.md" ]; then
            echo "⚠️ 未检测到多Agent架构部署"
            echo "Supervisor 架构需要先部署多Agent配置，请在 OpenClaw 面板中执行「多智能体管理 → 一键部署多Agent架构」"
            echo "路径: 主菜单 1 → 选项 17 → 选项 11"
            break_end
            return 0
        fi
        state_set OPENCLAW_USE_SUPERVISOR_ARCH 1
        echo "已切换为 Supervisor 新架构"
        echo "路由将完全由 Supervisor Agent 负责，正在重启网关..."
    fi
    openclaw gateway restart >/dev/null 2>&1 || true
    break_end
}

# ── 主面板 ──
skpl_main_panel() {
  while true; do
    clear
    skpl_ui_header "SKPL-OpenClaw管理面板"
    skpl_ui_section "概览"
    skpl_ui_kv "运行脚本" "$SKPL_SCRIPT_PATH"
    skpl_ui_kv "更新来源" "GitHub main"
    skpl_ui_kv "路由架构" "$(skpl_supervisor_arch_status)"
    skpl_ui_kv "多Agent" "$(if [ -f "$HOME/.openclaw/agents/main/AGENTS.md" ]; then printf '已部署(%s个)' "$(ls -1 "$HOME/.openclaw/agents/" 2>/dev/null | wc -l)"; else printf '未部署'; fi)"

    echo
    skpl_ui_section "核心入口"
    skpl_ui_menu_item 1 "OpenClaw 面板" "进入 OpenClaw 主控制台"
    skpl_ui_menu_item 2 "EvoMap 管理" "管理记忆、进化与同步"

    echo
    skpl_ui_section "架构控制"
    skpl_ui_menu_item 9 "切换 Supervisor 架构" "新旧路由架构切换，需重启网关"

    echo
    skpl_ui_section "安装与维护"
    skpl_ui_menu_item 3 "重新执行完整安装流程" "重置状态后从头运行"
    skpl_ui_menu_item 7 "从中断点继续安装" "按当前步骤续跑"
    skpl_ui_menu_item 4 "SKPL 面板更新" "从 GitHub 拉取最新脚本，并同步刷新当前入口"
    skpl_ui_menu_item 6 "查看最近日志" "读取安装与运行日志"
    skpl_ui_menu_item 8 "WSL 代理同步并更新系统" "执行 wslwin 与系统更新"
    skpl_ui_menu_item 5 "SKPL 面板卸载" "仅移除 SKPL 入口"

    echo
    skpl_ui_section "退出"
    skpl_ui_menu_item 0 "退出"
    skpl_ui_footer_prompt "请输入你的选择: "
    read -r skpl_choice
    case "$skpl_choice" in
      1) openclaw_panel_menu ;;
      2) openclaw_evomap_menu ;;
      3) rerun_full_pipeline_from_start; break_end ;;
      4) skpl_update_panel; break_end ;;
      5) remove_skpl_panel_only; break_end ;;
      6) show_recent_log; break_end ;;
      7) run_full_pipeline_once; break_end ;;
      8) skpl_wslwin_and_update_system; break_end ;;
      9) toggle_supervisor_arch ;;
      0) exit 0 ;;
      *) echo "无效的选择，请重试。"; sleep 1 ;;
    esac
  done
}

main() {
  ensure_root "$@"
  init_skpl_runtime
  skpl_sync_workspace_panel_to_runtime
  save_self_to_skpl

  case "${1:-install}" in
    install)
      run_full_pipeline_once
      load_openclaw_panel
      skpl_main_panel
      ;;
    panel)
      save_self_to_skpl
      load_openclaw_panel
      if [ "${2:-}" = "__internal_start_gateway" ]; then
        shift 2
        start_gateway "$@"
        return 0
      fi
      skpl_main_panel
      ;;
    openclaw)
      save_self_to_skpl
      load_openclaw_panel
      openclaw_panel_menu
      ;;
    evomap)
      save_self_to_skpl
      load_openclaw_panel
      openclaw_evomap_menu
      ;;
    *)
      echo "用法: bash $0 [install|panel|openclaw|evomap]"
      exit 1
      ;;
  esac
}


# ─── PATCH 1: Cross-Device Sync Engine (跨设备同步执行函数) ───

openclaw_cross_device_sync_state_file() {
  echo "${SKPL_AI_STACK_STATE_DIR}/cross-device-sync.json"
}

openclaw_cross_device_sync_execute() {
  openclaw_ai_stack_prepare
  local config_file="$SKPL_AI_STACK_ROOT/config.json"
  local state_file
  state_file=$(openclaw_cross_device_sync_state_file)

  python3 - "$config_file" "$state_file" "$SKPL_DEVICES_LIST_CACHE_FILE" "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_AI_STACK_EVOLVE_STATE_FILE" <<'PY'
import json
import sys
import time
import hashlib
from pathlib import Path

config_path = Path(sys.argv[1])
state_path = Path(sys.argv[2])
devices_path = Path(sys.argv[3])
db_path = Path(sys.argv[4])
evolve_path = Path(sys.argv[5])

cfg = json.loads(config_path.read_text(encoding='utf-8')) if config_path.exists() else {}
frontend = cfg.get('frontend', {})
sync_mode = str(frontend.get('crossDeviceSync', 'optional') or 'optional')

if sync_mode == 'disabled':
    print('跨设备同步已禁用，跳过执行。')
    raise SystemExit(0)

# Collect local state
memory_count = 0
if db_path.exists():
    try:
        import sqlite3
        conn = sqlite3.connect(db_path)
        memory_count = conn.execute('select count(*) from memory_entries where deleted = 0').fetchone()[0]
        conn.close()
    except Exception:
        memory_count = 0

config_hash = hashlib.md5(config_path.read_bytes()).hexdigest()[:12] if config_path.exists() else 'none'

evolve_hash = 'none'
if evolve_path.exists():
    try:
        evolve_hash = hashlib.md5(evolve_path.read_bytes()).hexdigest()[:12]
    except Exception:
        pass

local_state = {
    'memoryCount': memory_count,
    'configHash': config_hash,
    'evolveStateHash': evolve_hash,
    'timestamp': int(time.time()),
}

# Read device list
devices = []
if devices_path.exists():
    try:
        content = devices_path.read_text(encoding='utf-8').strip()
        for line in content.splitlines():
            line = line.strip()
            if line:
                devices.append(line)
    except Exception:
        pass

# Generate sync manifest
manifest = {
    'localState': local_state,
    'devices': devices,
    'syncMode': sync_mode,
}

# Load or create sync state
state = {
    'lastSyncAt': 0,
    'lastSyncResult': 'never',
    'deviceStates': {},
    'syncCount': 0,
    'conflicts': [],
}
if state_path.exists():
    try:
        current = json.loads(state_path.read_text(encoding='utf-8'))
        if isinstance(current, dict):
            state.update(current)
    except Exception:
        pass

# Update state
state['lastSyncAt'] = int(time.time())
state['syncCount'] = int(state.get('syncCount', 0) or 0) + 1
state['deviceStates']['local'] = local_state

for dev in devices:
    dev_key = hashlib.md5(dev.encode('utf-8')).hexdigest()[:8]
    if dev_key not in state.get('deviceStates', {}):
        state.setdefault('deviceStates', {})[dev_key] = {'name': dev, 'lastSeen': 0, 'syncStatus': 'pending'}

state['lastSyncResult'] = 'success'
state['manifest'] = manifest

state_path.parent.mkdir(parents=True, exist_ok=True)
state_path.write_text(json.dumps(state, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

print(f'跨设备同步完成 (模式: {sync_mode})')
print(f'  本地记忆条目: {memory_count}')
print(f'  配置哈希: {config_hash}')
print(f'  进化状态哈希: {evolve_hash}')
print(f'  已知设备数: {len(devices)}')
print(f'  累计同步次数: {state["syncCount"]}')
print(f'  (注: 实际设备间传输需要网络基础设施支持)')
PY
}

openclaw_cross_device_sync_status() {
  local state_file
  state_file=$(openclaw_cross_device_sync_state_file)
  if [ ! -f "$state_file" ]; then
    echo "跨设备同步状态: 未初始化"
    return 0
  fi
  python3 - "$state_file" <<'PY'
import json
import sys
import time
from pathlib import Path

path = Path(sys.argv[1])
data = json.loads(path.read_text(encoding='utf-8'))
last_sync = int(data.get('lastSyncAt', 0) or 0)
sync_count = int(data.get('syncCount', 0) or 0)
result = str(data.get('lastSyncResult', 'never') or 'never')
devices = data.get('deviceStates', {})
conflicts = data.get('conflicts', [])

if last_sync > 0:
    ts_str = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(last_sync))
else:
    ts_str = '从未'

print(f'上次同步: {ts_str}')
print(f'同步结果: {result}')
print(f'累计同步: {sync_count} 次')
print(f'已知设备: {len(devices)} 个')
if conflicts:
    print(f'冲突数: {len(conflicts)}')
for dev_key, dev_info in list(devices.items())[:5]:
    name = dev_info.get('name', dev_key)
    status = dev_info.get('syncStatus', 'unknown')
    print(f'  - {name}: {status}')
PY
}

openclaw_cross_device_sync_menu() {
  while true; do
    clear
    skpl_ui_header "跨设备同步管理" "手动触发同步、查看同步状态与设备列表"
    echo
    skpl_ui_section "同步状态"
    openclaw_cross_device_sync_status
    echo
    skpl_ui_section "操作"
    skpl_ui_menu_item 1 "执行同步" "手动触发一次跨设备同步"
    skpl_ui_menu_item 2 "刷新状态" "重新查看同步状态"
    skpl_ui_menu_item 0 "返回上一级"
    skpl_ui_footer_prompt "请输入你的选择: "
    read -e choice
    case "$choice" in
      1) openclaw_cross_device_sync_execute; break_end ;;
      2) continue ;;
      0) return 0 ;;
      *) echo "无效的选择，请重试。"; sleep 1 ;;
    esac
  done
}


# ─── PATCH 2: User Model Preference Independent Config (用户模型偏好独立配置) ───

openclaw_user_model_preference_file() {
  echo "${SKPL_AI_STACK_STATE_DIR}/user-model-preferences.json"
}

openclaw_user_model_preference_load() {
  local state_file
  state_file=$(openclaw_user_model_preference_file)
  if [ ! -f "$state_file" ]; then
    echo '{"updatedAt":0,"preferences":{"defaultTextModel":"","defaultCodeModel":"","defaultVisionModel":"","preferredCloudProvider":"","costPriority":"balanced"}}'
    return 0
  fi
  cat "$state_file"
}

openclaw_user_model_preference_save() {
  local data="$1"
  local state_file
  state_file=$(openclaw_user_model_preference_file)
  openclaw_ai_stack_prepare
  python3 - "$state_file" "$data" <<'PY'
import json
import sys
import time
from pathlib import Path

state_path = Path(sys.argv[1])
data = json.loads(sys.argv[2])
state = {
    'updatedAt': int(time.time()),
    'preferences': {
        'defaultTextModel': '',
        'defaultCodeModel': '',
        'defaultVisionModel': '',
        'preferredCloudProvider': '',
        'costPriority': 'balanced',
    },
}
if state_path.exists():
    try:
        current = json.loads(state_path.read_text(encoding='utf-8'))
        if isinstance(current, dict):
            state.update(current)
    except Exception:
        pass
if 'preferences' in data and isinstance(data['preferences'], dict):
    state['preferences'].update(data['preferences'])
state['updatedAt'] = int(time.time())
state_path.parent.mkdir(parents=True, exist_ok=True)
state_path.write_text(json.dumps(state, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print('偏好已保存。')
PY
}

openclaw_user_model_preference_set() {
  local key="$1"
  local value="$2"
  local current_json new_json
  current_json=$(openclaw_user_model_preference_load)
  new_json=$(python3 - "$current_json" "$key" "$value" <<'PY'
import json
import sys

data = json.loads(sys.argv[1])
key = sys.argv[2]
value = sys.argv[3]
data['preferences'][key] = value
print(json.dumps(data, ensure_ascii=False))
PY
)
  openclaw_user_model_preference_save "$new_json"
}

openclaw_user_model_preference_get() {
  local key="$1"
  local current_json
  current_json=$(openclaw_user_model_preference_load)
  python3 - "$current_json" "$key" <<'PY'
import json
import sys

data = json.loads(sys.argv[1])
key = sys.argv[2]
print(data.get('preferences', {}).get(key, ''))
PY
}

openclaw_user_model_preference_menu() {
  while true; do
    clear
    skpl_ui_header "用户模型偏好配置" "独立配置默认文本、代码、视觉模型与成本优先级"
    echo
    skpl_ui_section "当前偏好"
    local pref_json
    pref_json=$(openclaw_user_model_preference_load)
    python3 - "$pref_json" <<'PY'
import json
import sys
import time
from pathlib import Path

data = json.loads(sys.argv[1])
prefs = data.get('preferences', {})
updated = int(data.get('updatedAt', 0) or 0)
if updated > 0:
    ts_str = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(updated))
else:
    ts_str = '从未更新'
print(f'最后更新: {ts_str}')
print(f'默认文本模型: {prefs.get("defaultTextModel", "(未设置)")}')
print(f'默认代码模型: {prefs.get("defaultCodeModel", "(未设置)")}')
print(f'默认视觉模型: {prefs.get("defaultVisionModel", "(未设置)")}')
print(f'首选云提供商: {prefs.get("preferredCloudProvider", "(未设置)")}')
print(f'成本优先级: {prefs.get("costPriority", "balanced")}')
PY
    echo
    skpl_ui_section "操作"
    skpl_ui_menu_item 1 "设置默认文本模型" "如 ollama/qwen2.5:7b"
    skpl_ui_menu_item 2 "设置默认代码模型" "如 ollama/qwen2.5-coder:1.5b"
    skpl_ui_menu_item 3 "设置默认视觉模型" "如 google/gemini-2.5-pro"
    skpl_ui_menu_item 4 "设置首选云提供商" "如 google, openai, anthropic"
    skpl_ui_menu_item 5 "设置成本优先级" "cost-first / balanced / quality-first"
    skpl_ui_menu_item 6 "应用到路由配置" "将偏好写入 ai-stack 路由配置"
    skpl_ui_menu_item 0 "返回上一级"
    skpl_ui_footer_prompt "请输入你的选择: "
    read -e choice
    case "$choice" in
      1) read -e -p "输入默认文本模型: " v; [ -n "$v" ] && openclaw_user_model_preference_set "defaultTextModel" "$v"; break_end ;;
      2) read -e -p "输入默认代码模型: " v; [ -n "$v" ] && openclaw_user_model_preference_set "defaultCodeModel" "$v"; break_end ;;
      3) read -e -p "输入默认视觉模型: " v; [ -n "$v" ] && openclaw_user_model_preference_set "defaultVisionModel" "$v"; break_end ;;
      4) read -e -p "输入首选云提供商: " v; [ -n "$v" ] && openclaw_user_model_preference_set "preferredCloudProvider" "$v"; break_end ;;
      5) read -e -p "输入成本优先级 (cost-first/balanced/quality-first): " v; [ -n "$v" ] && openclaw_user_model_preference_set "costPriority" "$v"; break_end ;;
      6) openclaw_user_model_preference_apply_to_route; break_end ;;
      0) return 0 ;;
      *) echo "无效的选择，请重试。"; sleep 1 ;;
    esac
  done
}

openclaw_user_model_preference_apply_to_route() {
  openclaw_ai_stack_prepare
  local pref_json="$SKPL_AI_STACK_ROOT/config.json"
  local user_prefs
  user_prefs=$(openclaw_user_model_preference_load)
  python3 - "$pref_json" "$user_prefs" <<'PY'
import json
import sys
from pathlib import Path

config_path = Path(sys.argv[1])
user_prefs = json.loads(sys.argv[2])
prefs = user_prefs.get('preferences', {})

cfg = json.loads(config_path.read_text(encoding='utf-8')) if config_path.exists() else {}
routing = cfg.setdefault('routing', {})

updated = []
if prefs.get('defaultTextModel'):
    routing['defaultTextModel'] = prefs['defaultTextModel']
    updated.append(f'文本模型 -> {prefs["defaultTextModel"]}')
if prefs.get('defaultCodeModel'):
    routing['defaultCodeModel'] = prefs['defaultCodeModel']
    updated.append(f'代码模型 -> {prefs["defaultCodeModel"]}')
if prefs.get('defaultVisionModel'):
    routing['defaultVisionModel'] = prefs['defaultVisionModel']
    updated.append(f'视觉模型 -> {prefs["defaultVisionModel"]}')
if prefs.get('costPriority'):
    cloud = cfg.setdefault('cloud', {})
    cloud['costQualityMode'] = prefs['costPriority']
    updated.append(f'成本优先级 -> {prefs["costPriority"]}')

config_path.write_text(json.dumps(cfg, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
if updated:
    print('已应用以下偏好到路由配置:')
    for item in updated:
        print(f'  - {item}')
else:
    print('没有需要应用的偏好设置。')
PY
}


# ─── PATCH 3: Structured Data Retrieval (结构化数据检索) ───

openclaw_structured_data_search() {
  local query="$1"
  if [ "$(openclaw_memory_feature_enabled all 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    printf '%s\n' '[]'
    return 0
  fi
  if [ "$(openclaw_memory_feature_enabled longTerm 2>/dev/null || printf '%s' 'true')" != "true" ]; then
    printf '%s\n' '[]'
    return 0
  fi
  memory_extension_prepare
  python3 - "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_MEMORY_EXTENSION_CONFIG" "$query" <<'PY'
import json
import sqlite3
import sys
import re

db_path = sys.argv[1]
config_path = sys.argv[2]
query = (sys.argv[3] or '').strip().lower()

conn = sqlite3.connect(db_path)
rows = conn.execute('select id, category, title, content, tags, updated_at from memory_entries where deleted = 0 order by updated_at desc limit 200').fetchall()
conn.close()

structured_categories = ['structured', 'config', 'setting', 'api', 'json']
results = []

for row in rows:
    _id, category, title, content, tags_raw, updated_at = row
    cat_lower = (category or '').lower()
    title_lower = (title or '').lower()
    content_text = content or ''

    is_structured = False
    for sc in structured_categories:
        if sc in cat_lower:
            is_structured = True
            break

    json_blocks = re.findall(r'\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}', content_text)
    kv_patterns = re.findall(r'["\']?(\w+)["\']?\s*[:=]\s*["\']?([^"\'\n,]+)["\']?', content_text)

    if is_structured or json_blocks or kv_patterns:
        score = 0.0
        reasons = []
        if is_structured:
            score += 2.0
            reasons.append('结构化分类')
        if json_blocks:
            score += 1.5
            reasons.append(f'含{len(json_blocks)}个JSON块')
        if kv_patterns:
            score += 1.0
            reasons.append(f'含{len(kv_patterns)}个键值对')

        if query:
            if query in title_lower:
                score += 2.0
                reasons.append('标题命中')
            if query in content_text.lower():
                score += 1.0
                reasons.append('内容命中')
            tokens = [t for t in query.split() if t]
            for token in tokens:
                if token in (title_lower + ' ' + content_text.lower()):
                    score += 0.3

        if score > 0:
            tags = []
            try:
                tags = json.loads(tags_raw or '[]')
            except Exception:
                tags = []
            results.append({
                'id': _id,
                'source': 'structured-data',
                'summary': title,
                'score': score,
                'category': category,
                'jsonBlocks': len(json_blocks),
                'kvPairs': len(kv_patterns),
                'isStructuredCategory': is_structured,
                'tags': tags,
                'updatedAt': updated_at,
                'explain': ' / '.join(reasons[:3]) if reasons else '结构化数据',
            })

results.sort(key=lambda x: (x['score'], x['updatedAt']), reverse=True)
print(json.dumps(results[:5], ensure_ascii=False))
PY
}

openclaw_structured_data_extract() {
  local text="$1"
  python3 - "$text" <<'PY'
import json
import re
import sys

text = sys.argv[1] or ''

json_blocks = re.findall(r'\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}', text)
kv_pairs = re.findall(r'["\']?(\w+)["\']?\s*[:=]\s*["\']?([^"\'\n,]+)["\']?', text)

result = {
    'jsonBlocks': json_blocks,
    'keyValuePairs': [{'key': k, 'value': v} for k, v in kv_pairs],
    'totalJsonBlocks': len(json_blocks),
    'totalKvPairs': len(kv_pairs),
}

print(json.dumps(result, ensure_ascii=False, indent=2))
PY
}

openclaw_structured_data_index_entry() {
  local title="$1"
  local content="$2"
  local tags="${3:-[]}"
  [ -z "$title" ] && { echo "标题不能为空"; return 1; }
  [ -z "$content" ] && { echo "内容不能为空"; return 1; }
  memory_extension_upsert_entry "structured" "$title" "$content" "$tags" 0
  echo "结构化数据条目已索引。"
}


# ─── PATCH 4: Code Vector Retrieval (代码向量检索) ───

openclaw_code_semantic_search() {
  local query="$1"
  openclaw_ai_stack_prepare
  python3 - "$SKPL_AI_STACK_CODE_CACHE_DIR" "$SKPL_MEMORY_EXTENSION_DB" "$SKPL_MEMORY_EXTENSION_CONFIG" "$query" <<'PY'
import json
import sqlite3
import sys
import os
import re
from pathlib import Path

code_cache_dir = Path(sys.argv[1])
db_path = Path(sys.argv[2])
config_path = sys.argv[3]
query = (sys.argv[4] or '').strip().lower()

results = []

# Search code cache files
if code_cache_dir.exists():
    for cache_file in sorted(code_cache_dir.glob('*.json')):
        try:
            data = json.loads(cache_file.read_text(encoding='utf-8'))
            payload = data.get('payload', data)
            if not isinstance(payload, dict):
                continue
            code_text = str(payload.get('code', '') or '')
            desc = str(payload.get('description', '') or '')
            lang = str(payload.get('language', '') or '')
            tags = payload.get('tags', [])
            if not isinstance(tags, list):
                tags = []

            searchable = ' '.join([code_text, desc, lang, ' '.join(str(t) for t in tags)]).lower()
            score = 0.0
            reasons = []

            if query:
                if query in searchable:
                    score += 2.0
                    reasons.append('代码缓存命中')
                tokens = [t for t in query.split() if len(t) > 1]
                for token in tokens:
                    if token in searchable:
                        score += 0.4
                if score > 0:
                    reasons.append(f'语言: {lang}' if lang else '')
            else:
                score = 0.1

            if score > 0:
                results.append({
                    'source': 'code-cache',
                    'summary': desc or f'{lang} snippet',
                    'score': score,
                    'language': lang,
                    'tags': tags,
                    'explain': ' / '.join(r for r in reasons if r) or '代码缓存',
                })
        except Exception:
            continue

# Search memory entries with code category
if db_path.exists():
    try:
        conn = sqlite3.connect(db_path)
        rows = conn.execute("select id, category, title, content, tags, updated_at from memory_entries where deleted = 0 and (category = 'code' or tags like '%code%') order by updated_at desc limit 50").fetchall()
        conn.close()

        for row in rows:
            _id, category, title, content, tags_raw, updated_at = row
            text = ' '.join([title or '', content or '', tags_raw or '']).lower()
            score = 0.0
            reasons = []
            if query:
                if query in text:
                    score += 2.5
                    reasons.append('记忆代码命中')
                tokens = [t for t in query.split() if len(t) > 1]
                for token in tokens:
                    if token in text:
                        score += 0.5
            else:
                score = 0.15

            if score > 0:
                tags = []
                try:
                    tags = json.loads(tags_raw or '[]')
                except Exception:
                    tags = []
                results.append({
                    'id': _id,
                    'source': 'memory-code',
                    'summary': title,
                    'score': score,
                    'category': category,
                    'tags': tags,
                    'updatedAt': updated_at,
                    'explain': ' / '.join(reasons[:3]) if reasons else '代码记忆',
                })
    except Exception:
        pass

results.sort(key=lambda x: x['score'], reverse=True)
print(json.dumps(results[:5], ensure_ascii=False))
PY
}

