print(f'最后更新: {ts_str}')
print(f'上次缺口检测: {det_str}')
print(f'已检测缺口: {len(gaps)} 个')
print(f'已记录洞察: {insights} 条')
print(f'自动学习: {"开启" if auto_learn else "关闭"}')
PY
}

openclaw_active_learning_menu() {
  while true; do
    clear
    skpl_ui_header "主动学习与知识补全" "检测知识缺口、生成学习建议、记录学习洞察"
    echo
